Ceviri.ekle("el","olay",{
"OLAYLAR:1299-01:0":{"b": ["Ίδρυση του Οθωμανικού Βεγιλικιού", "9f0b7c0a"], "d": ["Η έναρξη της ανεξάρτητης δράσης του Οσμάν Γαζή, από τη φυλή των Καγιί, στην περιοχή Σεγιούτ–Ντομανίτς θεωρείται η παραδοσιακή αφετηρία για την ίδρυση του Οθωμανικού κράτους· ορισμένοι ιστορικοί θεωρούν τη νίκη στο Βαφεύς το 1302 το πραγματικό σημείο καμπής. Χάρη στη θέση του στα βυζαντινά σύνορα, το βεγιλίκι ισχυροποιήθηκε γρήγορα με επιδρομές γκαζί. Στο περιβάλλον αυτό, όπου διαλυόταν η σελτζουκική κληρονομιά, ο Οσμάν Γαζής συγκέντρωσε γύρω του αχί, γκαζήδες και νομάδες Τουρκομάνους· ο δεσμός του με τον Σεΐχη Εντεμπαλί θεωρείται το θεμέλιο της πνευματικής νομιμοποίησης του βεγιλικιού. Άλλα μέρη που προσαρτήθηκαν την ίδια ημερομηνία: İnegöl, Yarhisar.", "9d689d45"]},
"OLAYLAR:1326-04-06:0":{"b": ["Κατάληψη της Προύσας", "98c727fa"], "d": ["Η Προύσα, που επί χρόνια βρισκόταν υπό αποκλεισμό, παραδόθηκε στον Ορχάν Γαζή, ο οποίος διηύθυνε το τελευταίο στάδιο της πολιορκίας· η πόλη έγινε η πρώτη μεγάλη πρωτεύουσα του βεγιλικιού. Σύμφωνα με την παράδοση, η είδηση της κατάληψης μεταφέρθηκε στον Οσμάν Γαζή στο νεκρικό του κρεβάτι· κατά τη διαθήκη του, ο Οσμάν Γαζής ετάφη στην Προύσα. Η πόλη γρήγορα εφοδιάστηκε με τζαμιά, ιμαρέτ και μεντρεσέδες και έγινε πρότυπο της πρώιμης οθωμανικής πολεοδομίας.", "9ede6ee9"]},
"OLAYLAR:1331-03-02:0":{"b": ["Κατάληψη της Νίκαιας", "a846a811"], "d": ["Η Νίκαια (İznik), ένα από τα σημαντικότερα κέντρα του Βυζαντίου στη Μικρά Ασία, μετά τη νίκη στο Πελεκάνον το 1329 έχασε την ελπίδα αντίστασης και παραδόθηκε στον Ορχάν Γαζή. Εδώ ιδρύθηκε ο πρώτος οθωμανικός μεντρεσές και λόγιοι όπως ο Νταβούντ-ι Καϊσερί άρχισαν να διδάσκουν· η πόλη έγινε το επιστημονικό κέντρο της πρώιμης περιόδου. Η εκκλησία της Αγίας Σοφίας μετατράπηκε σε τζαμί, παράδειγμα της πρώιμης παράδοσης των κατακτήσεων.", "8fd3bfb5"]},
"OLAYLAR:1337-01-01:0":{"b": ["Κατάληψη της Νικομήδειας (İzmit)", "06a35035"], "d": ["Με την πτώση της Νικομήδειας (İzmit) και το τελευταίο σημαντικό φρούριο του Βυζαντίου στην ασιατική πλευρά πέρασε στην οθωμανική διοίκηση· ολόκληρη η χερσόνησος του Κοτζαελί, μέχρι την απέναντι ακτή της Κωνσταντινούπολης, έγινε οθωμανικό έδαφος. Έτσι το βεγιλίκι κυριάρχησε σε όλες τις νότιες και ανατολικές ακτές της Προποντίδας και προετοίμασε τη βάση για τη διάβαση στη Ρούμελη.", "f677745c"]},
"OLAYLAR:1352-03-01:0":{"b": ["Φρούριο Τζίμπε — διάβαση στη Ρούμελη", "c2f0a07d"], "d": ["Ο Σουλεϊμάν Πασάς, γιος του Ορχάν Γαζή, είχε καταλάβει ως βάση το φρούριο Τζίμπε (Τζύμπη), που του δόθηκε στον βυζαντινό εμφύλιο, το 1352· μετά τον μεγάλο σεισμό του Μαρτίου 1354 που κατέστρεψε την Καλλίπολη, τα εγκαταλελειμμένα φρούρια οχυρώθηκαν γρήγορα και η χερσόνησος έγινε μόνιμο οθωμανικό προγεφύρωμα. Αυτό το βήμα, που στηρίχθηκε στον εποικισμό με τουρκομανικό πληθυσμό από τη Μικρά Ασία, αποτελεί την αρχή της παρουσίας των Οθωμανών στην ευρωπαϊκή ήπειρο, που θα διαρκέσει πάνω από 550 χρόνια.", "4857333a"]},
"OLAYLAR:1361-05-05:0":{"b": ["Κατάληψη της Αδριανούπολης", "2f54ebb0"], "d": ["Η κατάληψη της Αδριανούπολης (Edirne), κομβικής πόλης της Θράκης, καθόρισε την κύρια βάση και την κατεύθυνση των βαλκανικών κατακτήσεων· η ημερομηνία της κατάληψης είναι αμφισβητούμενη στις πηγές, μεταξύ 1361 και 1369. Η πόλη έγινε λίγο αργότερα πρωτεύουσα, δηλώνοντας ότι το κέντρο βάρους του κράτους μετατοπίστηκε στη Ρούμελη· παρέμεινε πρωτεύουσα για περίπου 90 χρόνια, μέχρι την άλωση της Κωνσταντινούπολης.", "25bd644f"]},
"OLAYLAR:1362-03:0":{"b": ["Ο Μουράτ Α΄ ανέβηκε στον θρόνο", "f8d48a26"], "d": ["Ο Μουράτ Α΄ (Χουνταβεντιγκιάρ), που διαδέχθηκε τον Ορχάν Γαζή μετά τον θάνατό του, στη βασιλεία των 27 ετών του μετέφερε το κράτος από ένα συνοριακό βεγιλίκι στον σκελετό μιας αυτοκρατορίας. Με το σύστημα πεντσίκ τέθηκαν τα θεμέλια του σώματος των γενιτσάρων, το σύστημα τιμαρίου επεκτάθηκε, ιδρύθηκε το Μπεϊλέρμπεϊλίκι της Ρούμελης και ενισχύθηκε ο θεσμός του βεζίρη. Οι κατακτήσεις στα Βαλκάνια έγιναν στην εποχή του συστηματική κρατική πολιτική.", "d463078a"]},
"OLAYLAR:1389-06-15:0":{"b": ["Μάχη του Κοσσυφοπεδίου Α΄ — μαρτυρικός θάνατος του Μουράτ Α΄", "10b8ddc9"], "d": ["Η βαλκανική συμμαχία υπό τον πρίγκιπα Λάζαρο ηττήθηκε αποφασιστικά στο Κοσσυφοπέδιο· η Σερβία πέρασε στην οθωμανική επικυριαρχία. Ο Μουράτ Α΄, που περιέρχονταν το πεδίο της μάχης, δολοφονήθηκε με στιλέτο από τον Σέρβο ευγενή Μίλος Ομπίλιτς και πέθανε ως μάρτυρας — είναι ο μοναδικός Οθωμανός σουλτάνος που πέθανε στο πεδίο της μάχης. Στη θέση του ανέβηκε στο στρατόπεδο ο Βαγιαζήτ ο Κεραυνός· ο αδελφός του Γιακούμπ Τσελεμπί στραγγαλίστηκε και αυτό είναι ένα από τα πρώτα γνωστά παραδείγματα της πρακτικής της αδελφοκτονίας.", "153449fe"]},
"OLAYLAR:1396-09-25:0":{"b": ["Νίκη της Νικόπολης", "75716e96"], "d": ["Ο μεγάλος σταυροφορικός στρατός, που συγκεντρώθηκε μετά την έκκληση του βασιλιά της Ουγγαρίας Σιγισμούνδου και στον οποίο συμμετείχαν και Γάλλοι και Βουργουνδοί ιππότες, ηττήθηκε βαριά από τον Βαγιαζήτ τον Κεραυνό μπροστά στη Νικόπολη, στις όχθες του Δούναβη. Η νίκη επιβεβαίωσε οριστικά την οθωμανική κυριαρχία στη Βουλγαρία· στην Ευρώπη δεν οργανώθηκε μεγάλη σταυροφορία για μία ολόκληρη γενιά.", "0d06e36c"]},
"OLAYLAR:1402-07-28:0":{"b": ["Μάχη της Άγκυρας — Άρχισε η περίοδος του Φετρέτ", "b4a99d96"], "d": ["Στη βαριά ήττα στην πεδιάδα του Τσουμπούκ απέναντι στον στρατό του Ταμερλάνου, ο Βαγιαζήτ ο Κεραυνός αιχμαλωτίστηκε και πέθανε στην αιχμαλωσία λίγους μήνες αργότερα. Ο Ταμερλάνος αναβίωσε τα μικρασιατικά βεγιλίκια· τα οθωμανικά εδάφη διαμελίστηκαν ανάμεσα στους γιους του Βαγιαζήτ και άρχισε ένας αγώνας διαδοχής που θα διαρκέσει 11 χρόνια (περίοδος του Φετρέτ). Η περίοδος αυτή, η βαρύτερη κρίση που γνώρισε το κράτος από την ίδρυσή του, χαράχτηκε στην οθωμανική μνήμη ως απόδειξη της σημασίας της συγκεντρωτικής δομής. Άλλοι οικισμοί που χάθηκαν την ίδια ημερομηνία: Datça, Marmaris, Fethiye (Μάκρη), Söke, Kütahya, Afyon, Isparta, Manisa, Aydın, Denizli, Muğla, Antalya, Konya, Karaman, Kayseri, Kastamonu, Bartın, Safranbolu, Samsun, Sivas, Malatya, Beyşehir, Sivrihisar, Kırşehir, Çorum, Çankırı, Yenişehir (Προύσα), İnegöl, Aydos Kalesi, Geyve, Köprühisar (Yenişehir), Marmaracık, Akhisar (Pamukova), Mekece, Kestel, Ulubat, Harmankaya, Akyazı, νησί İmralı, Kandıra, Mudanya, Yalova, Karamürsel, Armutlu, Gemlik (Κίος), Söğüt, Bilecik, Eskişehir, Προύσα, Νίκαια, Νικομήδεια, Balıkesir, Τσανάκκαλε, Πέργαμος, Amasya, Tokat, Çorlu, Lüleburgaz, Malkara, Keşan, İpsala, Kilitbahir, Çirmen, Eski Zağra (Στάρα Ζαγόρα), Tatarpazarcığı, İhtiman, Köstendil, Petriç, Nevrokop (Γκότσε Ντέλτσεφ), Δράμα, Καλλίπολη, Çimpe, Αδριανούπολη, Διδυμότειχο, Kırklareli, Tekirdağ, Φιλιππούπολη, Σόφια, Νις, Βιδίνιο, Τίρνοβο, Βάρνα, Şumnu, Silistre, Νικόπολη, Rusçuk, Θεσσαλονίκη, Σέρρες, Καβάλα, Σκόπια, Μοναστήρι, Αχρίδα, Yenişehir (Λάρισα), Τρίκαλα, İzdin (Λαμία), Πλέβεν, Κομοτηνή, Biga, Domaniç, Kulacahisar, Karacahisar, Yarhisar, Dimbos, Kite (Kete), Lefke (Osmaneli), Leblebicihisar, Karaçepüş, Karatigin, Absu (Hypsu), Adranos (Orhaneli), Πελεκάνον (Eskihisar), Gebze, Hereke, Samandıra, Kirmasti (M.Kemalpaşa), Mihaliç (Karacabey), Κωστάντζα, Gölyazı (Απολλωνιάδα).", "d34e55d5"]},
"OLAYLAR:1413-07-05:0":{"b": ["Ο Τσελεμπί Μεχμέτ αποκατέστησε την ενότητα", "03413dfd"], "d": ["Στον τελευταίο λογαριασμό μεταξύ των αδελφών, ο Μεχμέτ Α΄, αφού νίκησε τον Μουσά Τσελεμπί στο Τσαμουρλού, ένωσε τα εδάφη της χώρας υπό ενιαία διοίκηση· γι' αυτό θεωρείται «ο δεύτερος ιδρυτής του κράτους». Στη βασιλεία του επισκευάστηκε η φθαρμένη κρατική δομή, εξισορροπήθηκαν οι σχέσεις με τα βεγιλίκια της Μικράς Ασίας και ακολουθήθηκε προσεκτική πολιτική ειρήνης στη Ρούμελη.", "d8f535c2"]},
"OLAYLAR:1416-05-01:0":{"b": ["Εξέγερση του Σεΐχη Μπεντρεντίν", "e0a072ca"], "d": ["Το θρησκευτικό-κοινωνικό κίνημα που αναπτύχθηκε γύρω από τον Σεΐχη Μπεντρεντίν, μεγάλο νομομαθή και μυστικιστή που είχε διατελέσει καζασκέρης την περίοδο του Φετρέτ, ξέσπασε ταυτόχρονα με τις εξεγέρσεις του Μπορκλουτζέ Μουσταφά στο Καραμπουρούν και του Τορλάκ Κεμάλ στη Μανισά. Οι εξεγέρσεις κατεστάλησαν αιματηρά· ο Μπεντρεντίν συνελήφθη στο Ντελιορμάν και εκτελέστηκε στις Σέρρες. Το γεγονός άφησε βαθύ ίχνος στη λογοτεχνία και την ιστοριογραφία ως η πρώιμη μεγαλύτερη κοινωνική-μεσσιανική εξέγερση της οθωμανικής ιστορίας.", "1cf72ec4"]},
"OLAYLAR:1444-11-10:0":{"b": ["Νίκη της Βάρνας", "f739eedc"], "d": ["Ο ουγγροπολωνικός σταυροφορικός στρατός, που κατέβηκε νότια παραβιάζοντας τη συνθήκη του Σεγκεντίν, εξοντώθηκε στη Βάρνα από τον Μουράτ Β΄, ο οποίος είχε παραιτηθεί από τον θρόνο αλλά επέστρεψε στην ηγεσία του στρατού· ο νεαρός βασιλιάς Λαδίσλαος Γ΄ έπεσε στο πεδίο της μάχης. Η νίκη εξάλειψε την τελευταία μεγάλη πιθανότητα εξωτερικής επέμβασης με στόχο την εκρίζωση της οθωμανικής παρουσίας στα Βαλκάνια και εξασφάλισε τον δρόμο προς την άλωση της Κωνσταντινούπολης.", "43adf0fb"]},
"OLAYLAR:1448-10-17:0":{"b": ["Μάχη του Κοσσυφοπεδίου Β΄", "ebe0b662"], "d": ["Ο στρατός του Γιάνος Χούνυαντι, που ήθελε να εκδικηθεί τη Βάρνα, ηττήθηκε οριστικά από τον Μουράτ Β΄ σε μια σκληρή μάχη τριών ημερών. Αυτή ήταν η τελευταία μεγάλη μάχη σε ανοιχτό πεδίο που επιχείρησαν οι σταυροφόροι στα Βαλκάνια κατά των Οθωμανών· με τη νίκη η οθωμανική κυριαρχία νότια του Δούναβη εδραιώθηκε οριστικά.", "ea3ae23b"]},
"OLAYLAR:1453-05-29:0":{"b": ["Άλωση της Κωνσταντινούπολης", "583d5e3e"], "d": ["Μετά από πολιορκία πενήντα τεσσάρων ημερών (6 Απριλίου–29 Μαΐου 1453), το πρωί της 29ης Μαΐου ο οθωμανικός στρατός πέρασε τα τείχη και μπήκε στην πόλη· ο τελευταίος αυτοκράτορας Κωνσταντίνος ΙΑ΄ έπεσε στις μάχες και η Ανατολική Ρωμαϊκή Αυτοκρατορία, ιστορίας 1100 ετών, έγινε παρελθόν. Ο νεαρός σουλτάνος πήρε τον τίτλο «Φατίχ» (Πορθητής), έκανε την πόλη πρωτεύουσα και μετέτρεψε την Αγία Σοφία σε τζαμί· η πόλη σύντομα αναζωογονήθηκε με εποικισμό και ανοικοδόμηση. Σύμφωνα με το TDV, η Σηλυβρία και η Βιζύη κατακτήθηκαν οριστικά μόλις το 1453· σύμφωνα με το λήμμα Λήμνος του TDV, το νησί πέρασε στην οθωμανική διοίκηση αμέσως μετά την άλωση και παραδόθηκε στην οικογένεια Γατιλούζι με όρο φόρου υποτέλειας. Στον άτλαντα η Σηλυβρία, η Βιζύη και η Λήμνος (φόρου υποτελής) καταγράφονται από αυτή την ημέρα ως μετάβαση από το Βυζάντιο στους Οθωμανούς. Η χύτευση γιγαντιαίων κανονιών, η μεταφορά των πλοίων στη στεριά και η διάταξη πολιορκίας μπροστά στα τείχη θεωρούνται κορυφαία στρατιωτικής μηχανικής της εποχής. Η άλωση θεωρείται στην ευρωπαϊκή ιστοριογραφία μία από τις συμβολικές ημερομηνίες του τέλους του Μεσαίωνα.", "d4b39486"]},
"OLAYLAR:1461-08-15:0":{"b": ["Κατάληψη της Τραπεζούντας", "15f52403"], "d": ["Στο τέλος της δύσκολης εκστρατείας στη Μαύρη Θάλασσα, που ο Φατίχ διεξήγαγε ταυτόχρονα με στρατό και στόλο, η Αυτοκρατορία της Τραπεζούντας παραδόθηκε· με την εξάλειψη αυτού του τελευταίου υπολείμματος του βυζαντινού κόσμου στη Μικρά Ασία, ολόκληρη η νότια ακτή της Μαύρης Θάλασσας πέρασε στην οθωμανική κυριαρχία. Το τέλος της δυναστείας των Κομνηνών ενίσχυσε τον ισχυρισμό του Φατίχ ως «κυρίαρχου δύο θαλασσών και δύο ηπείρων». Άλλα μέρη που προσαρτήθηκαν την ίδια ημερομηνία: Giresun, Rize.", "ca6ead13"]},
"OLAYLAR:1473-01-01:0":{"b": ["Οριστική κατάληψη της Σελεύκειας (Silifke) — κάμψη της τελευταίας αντίστασης των Καραμανιδών", "d988bee4"], "d": ["Το φρούριο της Silifke είχε παραδοθεί μία φορά το 1472 στον Γκεντίκ Αχμέτ Πασά, αλλά την ίδια χρονιά ο Καραμανόγλου Κασίμ Μπέης το ανακατέλαβε με τη βοήθεια του σταυροφορικού στόλου στη Μεσόγειο. Μετά τη νίκη του Οτλούκμπελι ο Φατίχ ανέθεσε στον γιο του και στον Γκεντίκ Αχμέτ Πασά να καταλάβουν οριστικά την περιοχή· με τη βοήθεια παλαιών οθωμανών πυροβολητών πυρπολήθηκε η αποθήκη πυρίτιδας και το φρούριο έπεσε γρήγορα. Έτσι κάμφθηκε η τελευταία αντίσταση των Καραμανιδών στα βουνά Τασελί–Ιτσέλ· η εξάλειψη του βεγιλικιού θα ολοκληρωνόταν το 1474.", "e9814184"]},
"OLAYLAR:1473-08-11:0":{"b": ["Μάχη του Οτλούκμπελι", "42c7194e"], "d": ["Ο ηγεμόνας των Ακκογιούνλου Ουζούν Χασάν, που είχε γίνει μεγάλη δύναμη στην Ανατολή και συμμάχησε με τη Βενετία, ηττήθηκε βαριά στο Οτλούκμπελι από τον στρατό του Φατίχ, εξοπλισμένο με πυροβόλα όπλα. Η νίκη επιβεβαίωσε οριστικά την οθωμανική υπεροχή στη Μικρά Ασία· ήταν επίσης μια πρώιμη απόδειξη της υπεροχής του συγκεντρωτικού στρατού που χρησιμοποιούσε κανόνια και τουφέκια απέναντι στον κλασικό στρατό. Σύμφωνα με το λήμμα Gümüşhane του TDV, η πόλη βρισκόταν από το 1467 υπό την κυριαρχία των Ακκογιούνλου· η κυριαρχία αυτή έληξε με την ήττα στο Οτλούκμπελι και το Gümüşhane πέρασε οριστικά στην οθωμανική κυριαρχία.", "63e0811f"]},
"OLAYLAR:1475-06-06:0":{"b": ["Η Κριμαία τίθεται υπό οθωμανική προστασία", "44e3f7c8"], "d": ["Ο στόλος υπό τον Γκεντίκ Αχμέτ Πασά κατέλαβε τις νότιες παράκτιες πόλεις της Κριμαίας, πρώτα την Καφά που ήταν στα χέρια των Γενουατών· οι ακτές αυτές έγιναν απευθείας οθωμανικό σαντζάκι. Το Χανάτο της Κριμαίας, υπό τον Μενγκλί Γκιράι, έγινε προνομιούχο υποτελές κράτος που αναγνώριζε την οθωμανική επικυριαρχία και επί τρεις αιώνες αποτέλεσε ακρογωνιαίο λίθο της βόρειας πολιτικής· η Μαύρη Θάλασσα μετατράπηκε πλέον de facto σε οθωμανική εσωτερική θάλασσα. Άλλα μέρη που προσαρτήθηκαν την ίδια ημερομηνία: Bahçesaray, Kerç, Azak.", "a3448d71"]},
"OLAYLAR:1481-05-03:0":{"b": ["Ο θάνατος του Φατίχ — Η υπόθεση του Τζεμ Σουλτάν", "190ecf01"], "d": ["Μετά τον ξαφνικό θάνατο του Φατίχ στον δρόμο της εκστρατείας, στον θρόνο ανέβηκε ο Βαγιαζήτ Β΄· ο αδελφός του Τζεμ Σουλτάν, διεκδικώντας τον θρόνο, έκανε να διαβαστεί το χουτμπέ στο όνομά του στην Προύσα και έκοψε νόμισμα. Όταν ηττήθηκε, κατέφυγε πρώτα στους Μαμελούκους και έπειτα στους ιππότες της Ρόδου· ο Τζεμ, που στα χέρια των ιπποτών και του παπισμού έγινε διαπραγματευτικό χαρτί της ευρωπαϊκής διπλωματίας, πέθανε στη Νάπολη το 1495. Το γεγονός ανάγκασε την οθωμανική εξωτερική πολιτική να φέρεται προσεκτικά επί δεκαπέντε χρόνια.", "7e488d7b"]},
"OLAYLAR:1514-08-23:0":{"b": ["Νίκη του Τσαλντιράν", "fea64ebb"], "d": ["Ο Γιαβούζ Σουλτάν Σελίμ, που ήθελε να λύσει εκ θεμελίων την απειλή που δημιουργούσε η σαφαβιδική προπαγάνδα στη Μικρά Ασία, νίκησε βαριά τον στρατό του Σάχη Ισμαήλ στην πεδιάδα του Τσαλντιράν χάρη στην υπεροχή σε κανόνια και τουφέκια. Εισήλθε στην Ταυρίδα (Τεμπρίζ)· η Ανατολική και Νοτιοανατολική Μικρά Ασία και η γραμμή Μοσούλης–Ντιγιάρμπακιρ προσαρτήθηκαν στην οθωμανική διοίκηση. Η προσχώρηση των Κούρδων μπέηδων στους Οθωμανούς με την προσπάθεια του Ιντρίς-ι Μπιτλισί έθεσε το πλαίσιο των ανατολικών συνόρων που θα διαρκέσει αιώνες.", "67b03a64"]},
"OLAYLAR:1516-08-24:0":{"b": ["Νίκη του Μερτζ Νταμπίκ", "07d254d3"], "d": ["Ο στρατός των Μαμελούκων διαλύθηκε μέσα σε λίγες ώρες στο Μερτζ Νταμπίκ, βόρεια του Χαλεπίου· ο ηλικιωμένος σουλτάνος Καντσού Γκαβρί πέθανε κατά τη διάρκεια της μάχης. Με τη νίκη, που άνοιξε διάπλατα τις πύλες του Χαλεπίου και της Δαμασκού, η Συρία, ο Λίβανος και η Παλαιστίνη πέρασαν στην οθωμανική διοίκηση· άνοιξε ο δρόμος για την εκστρατεία στην Αίγυπτο που θα έθετε τέλος στο Μαμελουκικό κράτος.", "c4b15f39"]},
"OLAYLAR:1517-01-22:0":{"b": ["Ριντανίγια — Κατάκτηση της Αιγύπτου και χαλιφάτο", "caf378d6"], "d": ["Ο οθωμανικός στρατός, αφού διέσχισε γρήγορα την έρημο του Σινά, διέσπασε στο Ριντανίγια τη γραμμή άμυνας του Τομανμπέη και εισήλθε στο Κάιρο· ο Τομανμπέης, που συνέχιζε την αντίσταση, συνελήφθη και εκτελέστηκε και το Μαμελουκικό κράτος έγινε παρελθόν. Η Αίγυπτος, το Χιτζάζ και οι άγιες πόλεις πέρασαν στην οθωμανική διοίκηση· ο Αββασίδης χαλίφης και τα ιερά κειμήλια μεταφέρθηκαν στην Κωνσταντινούπολη. Με τη μεταβίβαση του χαλιφάτου στην οθωμανική δυναστεία, οι σουλτάνοι ανέλαβαν την αξίωση της ηγεσίας του ισλαμικού κόσμου· ο έλεγχος του Δρόμου των Μπαχαρικών απέφερε επίσης μεγάλα έσοδα στην αυτοκρατορία. Άλλα μέρη που προσαρτήθηκαν την ίδια ημερομηνία: Akkâ, Maan, Sayda, Kerak.", "a0cc8fdc"]},
"OLAYLAR:1520-09-30:0":{"b": ["Ο Σουλεϊμάν ο Νομοθέτης ανέβηκε στον θρόνο", "f6512269"], "d": ["Η βασιλεία 46 ετών του Σουλεϊμάν Α΄, που ανέβηκε στον θρόνο μετά τον θάνατο του Γιαβούζ ως ο μοναδικός άρρην απόγονος, θεωρείται η πολιτική, στρατιωτική, νομική και πολιτιστική κορυφή της αυτοκρατορίας. Οι κανουννάμηδες που συστηματοποίησαν το εθιμικό δίκαιο του χάρισαν τον τίτλο «Κανουνί» (Νομοθέτης)· στη Δύση είναι γνωστός ως «Μεγαλοπρεπής» (Magnificent). Τα έργα του αρχιτέκτονα Σινάν, η χρυσή εποχή της λογοτεχνίας του διβανιού και η ναυτική υπεροχή στη Μεσόγειο είναι τα σύμβολα της περιόδου αυτής.", "cda7a2fb"]},
"OLAYLAR:1521-08-29:0":{"b": ["Κατάληψη του Βελιγραδίου", "59ef5cec"], "d": ["Το Βελιγράδι, που ο Φατίχ δεν είχε καταφέρει να καταλάβει το 1456 και θεωρούνταν «το κλειδί της Κεντρικής Ευρώπης», έπεσε στην πρώτη εκστρατεία του Κανουνί με πολιορκία στη συμβολή Δούναβη–Σάβα. Η νότια αμυντική γραμμή της Ουγγαρίας είχε καταρρεύσει· με την κατάληψη αυτή άνοιξε η πύλη της εκστρατείας στην Κεντρική Ευρώπη, που θα έφτανε πέντε χρόνια αργότερα στο Μοχάτς και είκοσι χρόνια αργότερα στην προσάρτηση της Βούδας.", "69dbb7cc"]},
"OLAYLAR:1522-12-21:0":{"b": ["Κατάληψη της Ρόδου", "807bbb1e"], "d": ["Η Ρόδος, βάση των ιπποτών του Αγίου Ιωάννη που απειλούσαν τους θαλάσσιους δρόμους της Ανατολικής Μεσογείου και τη διαδρομή των προσκυνητών, παραδόθηκε με συνθήκη μετά από αιματηρή πολιορκία μηνών· επετράπη στους ιππότες να αποχωρήσουν ελεύθερα από το νησί (αργότερα εγκαταστάθηκαν στη Μάλτα). Εξασφαλίστηκε η ασφάλεια των μικρασιατικών ακτών και η θαλάσσια γραμμή Κωνσταντινούπολης–Αιγύπτου περιήλθε σε αδιάλειπτο οθωμανικό έλεγχο.", "aeedfb16"]},
"OLAYLAR:1526-08-29:0":{"b": ["Μάχη του Μοχάτς", "f3418b0d"], "d": ["Ο ουγγρικός στρατός εξολοθρεύτηκε μέσα σε περίπου δύο ώρες στην πεδιάδα του Μοχάτς χάρη στο πυρ των κανονιών και την υπεροχή στους ελιγμούς· ο βασιλιάς Λουδοβίκος Β΄ πέθανε σε έλος καθώς το έβαζε στα πόδια. Το Μοχάτς, μία από τις ταχύτερα κερδισμένες μεγάλες μάχες σε ανοιχτό πεδίο της οθωμανικής ιστορίας, έβαλε de facto τέλος στο ανεξάρτητο ουγγρικό βασίλειο και άνοιξε την εποχή της οθωμανο-αψβουργικής αντιπαλότητας στην Κεντρική Ευρώπη.", "48967894"]},
"OLAYLAR:1529-09-27:0":{"b": ["Πολιορκία της Βιέννης Α΄", "dc49ea4f"], "d": ["Στην εκστρατεία που οργανώθηκε κατά της επιβολής των Αψβούργων στον ουγγρικό θρόνο, ο οθωμανικός στρατός πολιόρκησε τη Βιέννη· λόγω της εγκατάλειψης των βαρέων κανονιών στον δρόμο, του πρόωρου χειμώνα και των δυσκολιών εφοδιασμού, η πολιορκία λύθηκε μετά από τρεις εβδομάδες. Αν και η πόλη δεν καταλήφθηκε, η οθωμανική επιρροή στην Ουγγαρία διατηρήθηκε· τα περίχωρα της Βιέννης σηματοδότησαν το όριο της επιμελητικής πρόσβασης της αυτοκρατορίας στην Κεντρική Ευρώπη.", "a49fc760"]},
"OLAYLAR:1534-12-04:0":{"b": ["Κατάληψη της Βαγδάτης — Εκστρατεία των δύο Ιράκ", "897092c3"], "d": ["Στην εκστρατεία που οργανώθηκε στα «δύο Ιράκ» (Ιράκ-ι Αράμπ και Ιράκ-ι Αζάμ), εισήλθαν πρώτα στην Ταυρίδα και έπειτα στη Βαγδάτη χωρίς μάχη· η κατάληψη της παλιάς πρωτεύουσας των Αββασιδών χάρισε στον Οθωμανό ηγεμόνα μεγάλο κύρος στον ισλαμικό κόσμο. Το μαυσωλείο του Ιμάμη Αζάμ Εμπού Χανίφε ανακαινίστηκε· με την προσάρτηση της Βαγδάτης και της Βασόρας τα οθωμανικά εδάφη έφτασαν στον Περσικό Κόλπο. Άλλα μέρη που προσαρτήθηκαν την ίδια ημερομηνία: Kerkük, Kerbelâ.", "f3f80434"]},
"OLAYLAR:1538-09-28:0":{"b": ["Ναυμαχία της Πρέβεζας", "30dc0f97"], "d": ["Ο σταυροφορικός στόλος που συγκροτήθηκε υπό την ηγεσία του Πάπα, παρά την αριθμητική του υπεροχή, διασκορπίστηκε ανοιχτά της Πρέβεζας χάρη στην τακτική του Μπαρμπαρόσα που εκμεταλλεύτηκε επιδέξια τον άνεμο και την ακτή· ο Αντρέα Ντόρια εγκατέλειψε το πεδίο της μάχης. Η νίκη εγκαθίδρυσε αδιαμφισβήτητη οθωμανική ναυτική υπεροχή στη Μεσόγειο για περίπου 33 χρόνια· είναι η συμβολική ημερομηνία της Ημέρας του Στόλου στην τουρκική ναυτική παράδοση. Άλλα μέρη που προσαρτήθηκαν την ίδια ημερομηνία: Aden, Bender.", "0411d92f"]},
"OLAYLAR:1541-08-29:0":{"b": ["Προσάρτηση της Βούδας — Η Ουγγαρία οθωμανική επαρχία", "db53b244"], "d": ["Ο Κανουνί, που εξεστράτευσε όταν οι Αψβούργοι πολιόρκησαν τη Βούδα, αφού έσωσε την πόλη, έθεσε την Κεντρική Ουγγαρία απευθείας υπό οθωμανική διοίκηση και ίδρυσε το Μπεϊλέρμπεϊλίκι της Βούδας· η Τρανσυλβανία έγινε αυτόνομο πριγκιπάτο εξαρτημένο από τους Οθωμανούς. Η τριμερής αυτή διάταξη της Ουγγαρίας διήρκεσε περίπου 150 χρόνια και αποτέλεσε τον μόνιμο σκελετό της οθωμανικής διοίκησης στην Κεντρική Ευρώπη.", "1eb63e33"]},
"OLAYLAR:1555-05-29:0":{"b": ["Συνθήκη της Αμάσειας", "a5afe0d1"], "d": ["Είναι η πρώτη επίσημη συνθήκη ειρήνης που έβαλε τέλος στους πολυετείς οθωμανο-σαφαβιδικούς πολέμους. Η Βαγδάτη και το Ιράκ παρέμειναν στους Οθωμανούς, τα σύνορα της Ανατολικής Μικράς Ασίας αναγνωρίστηκαν αμοιβαία για πρώτη φορά· οι Σαφαβίδες ανέλαβαν να σταματήσουν τη σιιτική προπαγάνδα στα οθωμανικά εδάφη και οι Οθωμανοί να εγγυηθούν την ασφάλεια διέλευσης των Ιρανών προσκυνητών. Η συνθήκη έγινε το πρώτο παράδειγμα νομικού πλαισίου των σχέσεων μεταξύ των δύο κρατών.", "220b198f"]},
"OLAYLAR:1566-09-07:0":{"b": ["Ζιγκέτβαρ — Ο θάνατος του Κανουνί", "e2917ed2"], "d": ["Ο Κανουνί, 72 ετών, πέθανε στη σκηνή του στη δέκατη τρίτη εκστρατεία του λίγες ώρες πριν πέσει το φρούριο Ζιγκέτβαρ που πολιορκούσε· ο Σοκολλού Μεχμέτ Πασάς απέκρυψε τον θάνατο για εβδομάδες ώστε να μη διαλυθεί ο στρατός. Το φρούριο καταλήφθηκε, όμως το κράτος είχε χάσει τον μακροβιότερο και πιο μεγαλοπρεπή σουλτάνο του· στον θρόνο ανέβηκε ο γιος του Σελίμ Β΄ και το βάρος των μεγάλων βεζίρηδων στη διοίκηση του κράτους άρχισε να αυξάνεται.", "62c468a1"]},
"OLAYLAR:1571-08-01:0":{"b": ["Κατάληψη της Κύπρου", "e364a2b3"], "d": ["Στην Κύπρο, που βρισκόταν υπό βενετική διοίκηση, έγινε απόβαση το 1570· η Λευκωσία έπεσε γρήγορα, ενώ η Αμμόχωστος παραδόθηκε μόλις τον Αύγουστο του 1571 μετά από πολιορκία έντεκα μηνών. Το νησί, κρίσιμο για την ασφάλεια των εμπορικών και προσκυνητικών δρόμων της Ανατολικής Μεσογείου, οργανώθηκε ως μπεϊλέρμπεϊλίκι και εποικίστηκε με πληθυσμό από τη Μικρά Ασία· η κατάκτηση υπήρξε και η αιτία της μεγάλης σταυροφορικής συμμαχίας που θα οδηγούσε στη Ναύπακτο.", "6dcfdc0f"]},
"OLAYLAR:1571-10-07:0":{"b": ["Ήττα της Ναυπάκτου (Λεπάντο)", "6a1d44a9"], "d": ["Ο σταυροφορικός στόλος, που ενώθηκε μετά την κατάκτηση της Κύπρου, έπιασε τον οθωμανικό στόλο στον κόλπο της Ναυπάκτου και κατέστρεψε το μεγαλύτερο μέρος του· ο καπουδάν πασάς Μουεζζινζαντέ Αλή Πασάς έπεσε μάρτυρας, μόνο ο στόλος του Ουλούτς Αλή σώθηκε. Μετά την καταστροφή ο μέγας βεζίρης Σοκολλού Μεχμέτ Πασάς διόρισε τον Ουλούτς Αλή Πασά καπουδάν πασά και τον επιφόρτισε να συγκεντρώσει τον διασκορπισμένο στόλο, και ξεκίνησε την ναυπήγηση νέου στόλου σε όλα τα ναυπηγεία από την Κωνσταντινούπολη μέχρι την Αλάνια· ωστόσο η απόλυτη υπεροχή στη Μεσόγειο είχε κλονιστεί ψυχολογικά.", "4cb5c93e"]},
"OLAYLAR:1596-10-26:0":{"b": ["Μάχη του Χατσόβα (Μεζοκερέστες)", "da308ec5"], "d": ["Στη μεγαλύτερη μάχη σε ανοιχτό πεδίο του Μακρού Πολέμου (1593–1606), ο στρατός με επικεφαλής αυτοπροσώπως τον Μεχμέτ Γ΄, τη στιγμή που έφτασε στο σημείο διάλυσης, ανασυντάχθηκε με την παρότρυνση του Χότζα Σααντεντίν Εφέντη και κατέστρεψε τον αψβουργικό στρατό. Θεωρείται η τελευταία μεγάλη κλασική μάχη σε ανοιχτό πεδίο που κέρδισαν οι Οθωμανοί· ωστόσο το ότι δεν άλλαξε τη γενική πορεία του πολέμου θεωρήθηκε και ένδειξη της φθοράς του στρατιωτικού συστήματος.", "77f2a384"]},
"OLAYLAR:1606-11-11:0":{"b": ["Συνθήκη του Ζιτβατορόκ", "39c01142"], "d": ["Με τη συνθήκη που έβαλε τέλος στον φθοροποιό πόλεμο δεκατριών ετών, ο Αψβούργος ηγεμόνας θεωρήθηκε για πρώτη φορά ισότιμος του σουλτάνου με την ιδιότητα του «Ρωμαίου Αυτοκράτορα» και καταργήθηκε ο ετήσιος φόρος υποτέλειας. Η απώλεια εδαφών ήταν σχεδόν ανύπαρκτη· όμως η αλλαγή αυτή της διπλωματικής γλώσσας διαβάζεται ως σύμβολο του τέλους της οθωμανικής αξίωσης απόλυτης υπεροχής απέναντι στην Ευρώπη.", "99a455e7"]},
"OLAYLAR:1639-05-17:0":{"b": ["Συνθήκη του Κασρ-ι Σιρίν", "c1acf3af"], "d": ["Η συνθήκη που υπογράφηκε μετά την ανακατάληψη της Βαγδάτης από τον Μουράτ Δ΄ (1638) έβαλε τέλος στους οθωμανο-σαφαβιδικούς πολέμους που διήρκεσαν πάνω από εκατό χρόνια. Η Βαγδάτη και το Ιράκ παρέμειναν οριστικά στους Οθωμανούς, το Ερεβάν αφέθηκε στους Σαφαβίδες· η γραμμή που χαράχτηκε, με μικρές αλλαγές, έγινε το θεμέλιο των σημερινών συνόρων Τουρκίας–Ιράν και θεωρείται από τα μακροβιότερα σύνορα του κόσμου. Η συνθήκη άφησε στους Οθωμανούς τα Μπεντρέ, Τζεσσάν, Μεντελί, Ντερτένγκ και Ντέρνε· το φρούριο Ζεντζίρ στα σύνορα θα κατεδαφιζόταν, τα χωριά δυτικά του θα έμεναν στους Οθωμανούς και τα ανατολικά στο Ιράν. Η περιοχή γύρω από το φρούριο Ζαλίμ κοντά στο Σεχριζόρ και το Κιζιλτζά Καλέ έμειναν στους Οθωμανούς, το Αβρομάν και το Μιχριμπάν στο Ιράν· τα φρούρια Κοτούρ, Μακού και Μαγκάζμπερντ θα κατεδαφίζονταν και από τις δύο πλευρές.", "c2d59f3f"]},
"OLAYLAR:1669-09-06:0":{"b": ["Ολοκληρώθηκε η κατάκτηση της Κρήτης", "e0d85604"], "d": ["Η πολιορκία του Χάνδακα (Κανδίας), τελευταίο στάδιο του πολέμου της Κρήτης που είχε αρχίσει το 1645, ολοκληρώθηκε με την αποφασιστική τριετή επιχείρηση του Φαζίλ Αχμέτ Πασά· ο Βενετός διοικητής Μοροζίνι παρέδωσε την πόλη με συνθήκη. Ο αγώνας, που κράτησε περίπου ένα τέταρτο του αιώνα, καταγράφηκε ως η μακρότερη πολιορκία της οθωμανικής ιστορίας· και το τελευταίο μεγάλο λατινικό φρούριο της Ανατολικής Μεσογείου πέρασε στην οθωμανική διοίκηση. Τρία μικρά βραχώδη φρούρια στη βόρεια ακτή του νησιού — η Σούδα, η Σπιναλόγκα και η Γραμβούσα — παρέμειναν ακόμη στη Βενετία· επειδή είναι κτισμένα σε ξεχωριστά νησάκια, δεν μπορούν να απεικονιστούν στον χάρτη χωριστά από την υπόλοιπη Κρήτη.", "314efa97"]},
"OLAYLAR:1672-10-18:0":{"b": ["Συνθήκη του Μπουτσάς — τα ευρύτερα σύνορα", "b17b6e5a"], "d": ["Με τη Συνθήκη του Μπουτσάς, που υπογράφηκε μετά την κατάληψη του Καμένιετς στην εκστρατεία της Πολωνίας, η Ποδολία προσαρτήθηκε στους Οθωμανούς και ένα τμήμα της Ουκρανίας τέθηκε υπό προστασία. Η αυτοκρατορία έφτασε έτσι στα ευρύτερα σύνορά της στην Ευρώπη· το σημείο αυτό θεωρείται η κορυφή της εποχής της επέκτασης και ταυτόχρονα ο τελευταίος κρίκος της.", "6d489670"]},
"OLAYLAR:1683-09-12:0":{"b": ["Ήττα στην πολιορκία της Βιέννης Β΄", "7d889252"], "d": ["Η πολιορκία της Βιέννης, που κράτησε δύο μήνες υπό τον Μερζιφονλού Καρά Μουσταφά Πασά, κατέληξε σε ήττα με το ξαφνικό χτύπημα που κατέβασε από τους λόφους του Καλενμπεργκ ο βασιλιάς της Πολωνίας Γιαν Σομπιέσκι· ο στρατός αποσύρθηκε εγκαταλείποντας τα φορτία του και ο Μερζιφονλού εκτελέστηκε στο Βελιγράδι. Με την Ιερά Συμμαχία που συγκροτήθηκε μετά τη νίκη, ο πόλεμος κράτησε 16 χρόνια· η ήττα αυτή υποδεικνύεται ως η αφετηρία της μεγάλης παρακμής στην οθωμανική ιστορία.", "88ceb19f"]},
"OLAYLAR:1692-01-01:0":{"b": ["Κατάληψη του φρουρίου της Γραμβούσας — ενός από τα βραχώδη φρούρια της Κρήτης που παρέμεναν στη Βενετία", "3ddf9eeb"], "d": ["Αν και με την παράδοση του Χάνδακα το 1669 η κατάκτηση της Κρήτης θεωρείται σε μεγάλο βαθμό ολοκληρωμένη, το βραχώδες νησί-φρούριο της Γραμβούσας, στο βορειοδυτικό άκρο του νησιού, έμεινε στα χέρια των Βενετών άλλα είκοσι τρία χρόνια. Με την κατάληψή του το 1692 εξαλείφθηκε ένα από τα τρία βενετικά υπολείμματα στην Κρήτη· η Σούδα και η Σπιναλόγκα θα περίμεναν την εκστρατεία του Μοριά το 1715.", "05e94fe9"]},
"OLAYLAR:1699-01-26:0":{"b": ["Συνθήκη του Κάρλοβιτς — η πρώτη μεγάλη απώλεια εδαφών", "8f7e2546"], "d": ["Με το Κάρλοβιτς, που έβαλε τέλος στους πολέμους της Ιεράς Συμμαχίας διάρκειας δεκαέξι ετών, η Ουγγαρία και η Τρανσυλβανία παραχωρήθηκαν στην Αυστρία, η Ποδολία στην Πολωνία, ο Μοριάς και οι ακτές της Δαλματίας στη Βενετία. Για πρώτη φορά στην οθωμανική ιστορία τόσο μεγάλη έκταση γης χανόταν στο τραπέζι των διαπραγματεύσεων και μόνιμα· η συνθήκη θεωρείται το αρχικό έγγραφο της νέας εποχής κατά την οποία η αυτοκρατορία πέρασε σε άμυνα απέναντι στην Ευρώπη και αποτελεί και σταθμό της οθωμανικής διπλωματικής ιστορίας. Οικισμοί που άλλαξαν χέρια την ίδια ημέρα στον άτλαντα: Kostajnica και Jasenovac (από τους Οθωμανούς στους Αψβούργους· το κείμενο της συνθήκης αφήνει το Castanoviz στα χέρια του αυτοκράτορα, η ημέρα παράδοσης του Jasenovac δεν υπάρχει στην πηγή, γράφτηκε η ημέρα της συνθήκης) και η Πρέβεζα (από τη Βενετία στους Οθωμανούς· TDV karlofca: σύμφωνα με τη διάταξη που υπογράφηκε στις 24 Ρετζέπ 1110 / 26 Ιανουαρίου 1699, επεστράφησαν οι κατεχόμενοι από τη Βενετία τόποι βόρεια του κόλπου της Ναυπάκτου). Ο άτλαντας γράφει επίσης το Kostayniçe (Kostajnica) και το Jasenovaç στην πλευρά των Αψβούργων, την Uman και τη Vinnitsa στην Ουκρανία της δεξιάς όχθης από τους Οθωμανούς στην Πολωνία (TDV merzifonlu-kara-mustafa-pasa· IEU Vinnytsia: 1672–99 τουρκική κυριαρχία) και το Nadin στη Δαλματία στη Βενετία (η ημέρα παράδοσης ειδικά για τον οικισμό δεν υπάρχει στην πηγή, γράφτηκε η ημέρα της συνθήκης· τα όρια περιόδου του Nadin δεν επαληθεύτηκαν με πηγή — δηλωμένη προσέγγιση). Και η Βονίτσα, βόρεια του κόλπου της Ναυπάκτου, επιστρέφεται από τη Βενετία στους Οθωμανούς (TDV karlofca)· στη Δαλματία η Vrana (Urana) είναι ανάμεσα στους τόπους που παρέμειναν στη Βενετία (το όριο της περιόδου δεν επαληθεύτηκε — δηλωμένο).", "0909e24e"]},
"OLAYLAR:1711-07-19:0":{"b": ["Νίκη του Προύθου", "2583572f"], "d": ["Στον πόλεμο που ξέσπασε εξαιτίας του ζητήματος του βασιλιά της Σουηδίας, που είχε καταφύγει στους Οθωμανούς μετά την ήττα της Πολτάβας, ο στρατός του Τσάρου Πέτρου Α΄ περικυκλώθηκε στις όχθες του Προύθου και αναγκάστηκε να παραδοθεί. Με τη συνθήκη που υπογράφηκε ανακτήθηκε το Αζάκ· το ότι ο στρατός δεν εξοντώθηκε και ο τσάρος αφέθηκε ελεύθερος καταγράφηκε στην ιστορία ως απόφαση που συζητείται από τότε μέχρι σήμερα.", "ce9c2996"]},
"OLAYLAR:1715-01-01:0":{"b": ["Κατάληψη των φρουρίων της Σούδας και της Σπιναλόγκας — Εξάλειψη του τελευταίου βενετικού ίχνους στην Κρήτη", "7261f7ba"], "d": ["Είκοσι τρία χρόνια μετά την πτώση της Γραμβούσας το 1692, με έναν παράπλευρο κλάδο της εκστρατείας του Μοριά κατακτήθηκαν και τα φρούρια της Σούδας και της Σπιναλόγκας, τα δύο τελευταία στηρίγματα της Βενετίας στην Κρήτη. Έτσι η κατάκτηση της Κρήτης που είχε αρχίσει το 1645 ολοκληρώθηκε μετά από σαράντα έξι χρόνια, μέχρι και το τελευταίο εκατοστό του νησιού.", "d2044cae"]},
"OLAYLAR:1730-09-25:0":{"b": ["Εξέγερση του Πατρόνα Χαλίλ", "100941a4"], "d": ["Η αποτυχία στο μέτωπο του Ιράν, οι φόροι και η οργή για την πολυτέλεια του περιβάλλοντος του παλατιού μετατράπηκαν σε μεγάλη εξέγερση υπό την ηγεσία του Πατρόνα Χαλίλ, λουτρατζή. Ο μέγας βεζίρης Ιμπραήμ Πασάς σκοτώθηκε, ο Αχμέτ Γ΄ καθαιρέθηκε και η Εποχή της Τουλίπας έληξε· το ότι οι εξεγερμένοι κυριάρχησαν στην πόλη επί μήνες έδειξε εντυπωσιακά την ευθραυστότητα της κεντρικής εξουσίας.", "d87eea77"]},
"OLAYLAR:1739-09-18:0":{"b": ["Συνθήκη του Βελιγραδίου — Ανάκτηση του Βελιγραδίου, της Σμεντερέβου και της βόρειας Σερβίας", "ba7f8e46"], "d": ["Στο τέλος του πολέμου που διεξήχθη σε δύο μέτωπα κατά της Αυστρίας και της Ρωσίας (1736–1739), ανακτήθηκαν το Βελιγράδι και η Βόρεια Σερβία· η Ρωσία δέχτηκε να αφοπλίσει το Αζάκ και να μη διατηρεί στόλο στη Μαύρη Θάλασσα. Η συνθήκη, που θεωρείται η τελευταία μεγάλη επιτυχία της οθωμανικής διπλωματίας και του στρατού του 18ου αιώνα, χάρισε στην αυτοκρατορία μια περίοδο ειρήνης ενός τετάρτου του αιώνα. Άλλοι οικισμοί που επέστρεψαν την ίδια ημέρα στον άτλαντα από την Αυστρία στους Οθωμανούς: Hisarcık (Grocka) (αλυσίδα του αδελφού-κέντρου του Βελιγραδίου· TDV belgrad), Krayova (Craiova), Rimnik (Râmnicu Vâlcea) και Turnu Severin (επιστροφή της Μικράς Βλαχίας στους Οθωμανούς, στην υποτέλεια της Βλαχίας). Το Bosna Brod (Bosanski Brod) και η Bosna Dubiçası (Bosanska Dubica) στη ζώνη της Σάβας επιστρέφουν στον άτλαντα στους Οθωμανούς στις 28 Σεπτεμβρίου 1739 (TDV bosna-hersek· TDV mahmud-i--osmanli: 28 Σεπτεμβρίου 1739). Και το Tirgu Jiu στη Μικρή Βλαχία επιστρέφει στους Οθωμανούς την ίδια ημέρα.", "118d49db"]},
"OLAYLAR:1770-07-06:0":{"b": ["Επιδρομή του Τσεσμέ", "840b30bd"], "d": ["Ο ρωσικός στόλος, που βγήκε στη Μεσόγειο με την υποστήριξη των Άγγλων, επιτέθηκε με πυρπολικά στον οθωμανικό στόλο που είχε καταφύγει στο λιμάνι του Τσεσμέ και τον έκαψε σχεδόν ολοσχερώς. Η Ρωσία εμφανίστηκε για πρώτη φορά ως μεγάλη ναυτική δύναμη στη Μεσόγειο· η καταστροφή υπήρξε ένα από τα πλήγματα που καθόρισαν την τύχη του πολέμου που οδήγησε στο Κιουτσούκ Καϊναρτζί το 1774 και ανέδειξε την ανάγκη ριζικής μεταρρύθμισης του στόλου.", "5b133a56"]},
"OLAYLAR:1774-07-21:0":{"b": ["Συνθήκη του Κιουτσούκ Καϊναρτζί", "2776dcdb"], "d": ["Με το Κιουτσούκ Καϊναρτζί, που έβαλε τέλος στον πόλεμο του 1768–1774 και θεωρείται μία από τις βαρύτερες συνθήκες της οθωμανικής ιστορίας, δόθηκε «ανεξαρτησία» στο Χανάτο της Κριμαίας — de facto δημιουργήθηκε μια ρωσική σφαίρα επιρροής. Η Ρωσία εγκαταστάθηκε στην ακτή της Μαύρης Θάλασσας, απέκτησε δικαίωμα διέλευσης των εμπορικών πλοίων από τα Στενά και μόνιμη πρεσβεία στην Κωνσταντινούπολη· η αόριστη ρήτρα προστασίας των ορθόδοξων υπηκόων άνοιξε την πόρτα για τις δικαιολογίες επεμβάσεων του επόμενου αιώνα. Για πρώτη φορά ένα έδαφος με μουσουλμανικό πληθυσμό αφαιρούνταν από την οθωμανική κυριαρχία.", "b677ebfc"]},
"OLAYLAR:1783-04-19:0":{"b": ["Προσάρτηση της Κριμαίας από τη Ρωσία", "bdf6faa8"], "d": ["Η «ανεξάρτητη» Κριμαία που δημιούργησε το Κιουτσούκ Καϊναρτζί προσαρτήθηκε στη Ρωσία με μανιφέστο της Αικατερίνης Β΄, με πρόσχημα τις αναταραχές στην εποχή του τελευταίου χάνου Σαχίν Γκιράι. Η τριακόσιων ετών οθωμανο-κριμαϊκή συνύπαρξη έληξε· η απώλεια των βόρειων στεπών εξάλειψε το αμυντικό βάθος της Κωνσταντινούπολης και ξεκίνησε το πρώτο μεγάλο κύμα μετανάστευσης δεκάδων χιλιάδων Τατάρων της Κριμαίας στα οθωμανικά εδάφη. Αυτή την ημέρα η χερσόνησος της Κριμαίας (Aluşta, Kefe, Sudak, Yalta, Balaklava, İnkirman, Mankup, Arabat) προσαρτήθηκε στη Ρωσία· η Ταμάν και το Κουμπάν πέρασαν επίσης στη Ρωσία με την ίδια προσάρτηση (TDV Kırım: 8 Απριλίου 1783 Ιουλιανό = 19 Απριλίου Γρηγοριανό).", "aa59d3e1"]},
"OLAYLAR:1789-04-07:0":{"b": ["Ο Σελίμ Γ΄ και το Νιζάμ-ι Τζεντίντ", "d53aec21"], "d": ["Ο Σελίμ Γ΄, που ανέβηκε στον θρόνο εν μέσω πολέμου, αντιλαμβανόμενος ότι οι ήττες ήταν δομικές, ξεκίνησε ένα ευρύ πρόγραμμα μεταρρυθμίσεων με την ονομασία «Νιζάμ-ι Τζεντίντ» (Νέα Τάξη): ένας νέος στρατός εκπαιδευμένος κατά το ευρωπαϊκό πρότυπο, ένα ξεχωριστό ταμείο που τον χρηματοδοτούσε (Ιράντ-ι Τζεντίντ), η ενίσχυση των μηχανικών σχολών και οι πρώτες μόνιμες πρεσβείες στις ευρωπαϊκές πρωτεύουσες. Το πρόγραμμα θεωρείται η αρχή της σύγχρονης τουρκικής μεταρρυθμιστικής παράδοσης· ωστόσο λόγω της αντίστασης των οτζακιών και των αγιάνηδων θα ανατρεπόταν το 1807.", "87394990"]},
"OLAYLAR:1798-06-12:0":{"b": ["Διάλυση των ιπποτών της Μάλτας — Σταθμός του γαλλικού στόλου στον δρόμο", "d62f901d"], "d": ["Ο γαλλικός στόλος που κατευθυνόταν στην Αίγυπτο έκανε στάση στη Μάλτα, που βρισκόταν στον δρόμο του· οι ιππότες του Αγίου Ιωάννη (Μάλτας) παρέδωσαν το νησί χωρίς πολλή αντίσταση. Έτσι έληξε το τελευταίο προπύργιο του ιπποτικού τάγματος, που είχε εκδιωχθεί από τη Ρόδο το 1522 και εγκατασταθεί εδώ. Η Μάλτα θα περνούσε στα χέρια της Αγγλίας δύο χρόνια αργότερα, ενώ ο Ναπολέων θα κατευθυνόταν από το νησί απευθείας στην Αλεξάνδρεια.", "aac1fe49"]},
"OLAYLAR:1798-07-01:0":{"b": ["Κατοχή της Αιγύπτου από τον Ναπολέοντα", "93fede5f"], "d": ["Ο στρατός του στρατηγού Βοναπάρτη αποβιβάστηκε στην Αλεξάνδρεια και κατέλαβε την Αίγυπτο· η εκστρατεία αυτή, που στόχευε τον δρόμο της Αγγλίας προς την Ινδία, ήταν η πρώτη άμεση επίθεση μιας ευρωπαϊκής δύναμης στα κεντρικά εδάφη των Οθωμανών. Η επιδρομή του Νέλσον στο Αμπουκίρ και η άμυνα της Άκρας από τον Τζεζζάρ Αχμέτ Πασά ανέκοψαν την γαλλική προέλαση· η κατοχή έληξε το 1801, αλλά στο κενό που άφησε ξεκίνησε η άνοδος του Καβαλιώτη Μωχάμεντ Άλι Πασά και η εποχή του «Ανατολικού Ζητήματος».", "b1ca7226"]},
"OLAYLAR:1808-10-07:0":{"b": ["Σενέντ-ι Ιττιφάκ", "cce49ef5"], "d": ["Έγγραφο που υπογράφηκε μεταξύ του παλατιού και των ισχυρών οικογενειών αγιάνηδων της επαρχίας, με πρωτοβουλία του Αλεμντάρ Μουσταφά Πασά, αγιάνη του Ρουσίουκ, ο οποίος ανέβασε τον Μαχμούτ Β΄ στον θρόνο· οι αγιάνηδες δεσμεύονταν σε πίστη στον σουλτάνο και στρατιωτική υποστήριξη, ενώ το κράτος αναγνώριζε την ύπαρξη και τα δικαιώματά τους. Επειδή είναι το πρώτο παράδειγμα περιορισμού της εξουσίας του σουλτάνου με έγγραφο στην οθωμανική ιστορία, θεωρείται από ορισμένους ιστορικούς η μακρινή αρχή της συνταγματικής παράδοσης· στην πράξη έγινε αναποτελεσματικό μέσα σε λίγους μήνες.", "2d97fdfe"]},
"OLAYLAR:1821-03-06:0":{"b": ["Ξέσπασε η Ελληνική Επανάσταση", "a7293715"], "d": ["Η εξέγερση που προετοίμασε η οργάνωση της Φιλικής Εταιρείας ξέσπασε πρώτα στη Βλαχία και έπειτα με την κύρια δύναμή της στον Μοριά· το κράτος, απασχολημένο με την υπόθεση του Αλή Πασά των Ιωαννίνων, καθυστέρησε στην πρώτη επέμβαση. Χάρη στη έντονη φιλελληνική συμπάθεια της ευρωπαϊκής κοινής γνώμης, η εξέγερση μετατράπηκε σύντομα σε διεθνές ζήτημα· έτσι άναψε το φυτίλι του πρώτου επιτυχημένου κινήματος ανεξαρτησίας στα οθωμανικά εδάφη στην εποχή του εθνικισμού. Άλλοι οικισμοί που χάθηκαν την ίδια ημερομηνία: Αθήνα, Balyabadra (Πάτρα), İstefe (Θήβα), Livadya, Eleusis (Αττική), Μεσολόγγι.", "f11097ac"]},
"OLAYLAR:1821-04-02:0":{"b": ["Η πρώτη ένοπλη εξέγερση στον Μοριά", "77e6250f"], "d": ["Μετά τη διάβαση του Προύθου η εξέγερση εξαπλώθηκε στον Μοριά: η ένοπλη δράση που ξεκίνησε στα Καλάβρυτα (21 Μαρτίου Ιουλιανό) ακολουθήθηκε από κινήματα στην Πάτρα, στην Καλαμάτα και στη Μάνη· ο Μοριάς μετατράπηκε σύντομα σε γενική εξέγερση και η οθωμανική διοίκηση έχασε το μεγαλύτερο μέρος της χερσονήσου. Άλλοι οικισμοί που χάθηκαν την ίδια ημερομηνία: Αθήνα, Balyabadra (Πάτρα), İstefe (Θήβα), Livadya, Eleusis (Αττική), Μεσολόγγι.", "143953b8"]},
"OLAYLAR:1826-06-15:0":{"b": ["Βακ'α-ι Χαϊριγιέ — Κατάργηση του σώματος των γενιτσάρων", "08c9372a"], "d": ["Οι γενίτσαροι, που ξεσήκωσαν ταραχή (ανέτρεψαν τα καζάνια) κατά της εκπαίδευσης του νεοϊδρυθέντος σώματος Εσκιντζί, εξοντώθηκαν στους στρατώνες τους στην Ετμεϊντανί με το πυρ των κανονιών των πιστών μονάδων που είχε προετοιμάσει εκ των προτέρων ο Μαχμούτ Β΄· το σώμα καταργήθηκε μαζί με όλους τους κλάδους του και τους συνδεδεμένους βεκτασίτικους τεκέδες. Η επιχείρηση αυτή, που έμεινε στην ιστορία με το όνομα που σημαίνει «ευνοϊκό γεγονός», εξάλειψε έναν θεσμό τεσσάρων αιώνων και άνοιξε τον δρόμο στον στρατό Ασακίρ-ι Μανσούρε-ι Μουχαμμεντίγιε και σε όλες τις επόμενες μεταρρυθμίσεις συγκεντρωτισμού.", "9ee152dd"]},
"OLAYLAR:1827-10-20:0":{"b": ["Επιδρομή της Ναυαρίνου", "ee579e7f"], "d": ["Ο οθωμανο-αιγυπτιακός στόλος, που καταπίεζε την ελληνική εξέγερση, κάηκε στο Ναυαρίνο από τον ενωμένο αγγλο-γαλλο-ρωσικό στόλο που μπήκε στο λιμάνι χωρίς κήρυξη πολέμου· χάθηκαν περίπου εξήντα πλοία και χιλιάδες ναύτες. Η επιδρομή, που στην ευρωπαϊκή διπλωματία παρουσιάστηκε ως «ατυχές γεγονός», εγγυήθηκε de facto την ελληνική ανεξαρτησία και άνοιξε τον δρόμο στον οθωμανο-ρωσικό πόλεμο του 1828–29.", "0d4b2c6f"]},
"OLAYLAR:1839-11-03:0":{"b": ["Διάταγμα του Τανζιμάτ", "5042ce7b"], "d": ["Με το Χατ-ι Χουμαγιούν που διαβάστηκε στο Γκιουλχανέ, η ασφάλεια ζωής, περιουσίας και τιμής όλων των υπηκόων, χωρίς διάκριση θρησκείας, τέθηκε υπό την εγγύηση του κράτους· διακηρύχθηκαν οι αρχές της δικαιοσύνης στη φορολογία, της τάξης στη στράτευση και της μη επιβολής ποινής χωρίς δίκη. Το διάταγμα, έργο του Μουσταφά Ρεσίτ Πασά, θεωρείται το πρώτο μεγάλο έγγραφο συνταγματικού χαρακτήρα του οθωμανικού εκσυγχρονισμού και η «Εποχή του Τανζιμάτ» (1839–1876) έδωσε το όνομά της στην εποχή των μεταρρυθμίσεων· στο πλαίσιο αυτό υλοποιήθηκε ριζική αναδιάρθρωση στη διοίκηση, το δίκαιο, την εκπαίδευση και τα οικονομικά.", "6ace4b82"]},
"OLAYLAR:1853-10-04:0":{"b": ["Ξέσπασε ο Πόλεμος της Κριμαίας", "3b9ca3c8"], "d": ["Η κρίση που άρχισε με το ζήτημα των Αγίων Τόπων και την αξίωση της Ρωσίας για προστασία των ορθόδοξων υπηκόων μετατράπηκε σε ανοιχτή σύγκρουση με την κήρυξη πολέμου από τους Οθωμανούς· μετά την επιδρομή της Σινώπης, η Αγγλία και η Γαλλία (αργότερα και το Πεδεμόντιο) μπήκαν στον πόλεμο στο πλευρό των Οθωμανών. Με την απόβαση των συμμαχικών στρατών στην Κριμαία και την κατάληψη της Σεβαστούπολης ο πόλεμος κερδήθηκε με τη Συνθήκη των Παρισίων το 1856· ωστόσο το πρώτο εξωτερικό δάνειο που ελήφθη στα χρόνια του πολέμου (1854) έβαλε την αυτοκρατορία σε μια σπείρα οικονομικής εξάρτησης που θα διαρκέσει μισό αιώνα.", "bae16135"]},
"OLAYLAR:1856-02-18:0":{"b": ["Διάταγμα Ισλαχάτ (Μεταρρυθμίσεων)", "78ff234d"], "d": ["Το διάταγμα που διακηρύχθηκε πριν από τις ειρηνευτικές διαπραγματεύσεις των Παρισίων, επεκτείνοντας τις αρχές του Τανζιμάτ, παραχώρησε στους μη μουσουλμάνους υπηκόους ευρεία δικαιώματα ισότητας, συμπεριλαμβανομένων των δημοσίων θέσεων, της στράτευσης και της ίδρυσης σχολείων· οι οργανώσεις των κοινοτήτων αναδιαρθρώθηκαν. Με τη Συνθήκη των Παρισίων που υπογράφηκε ακολούθως, το Οθωμανικό κράτος έγινε επίσημα δεκτό στην οικογένεια του ευρωπαϊκού δικαίου των εθνών και η εδαφική του ακεραιότητα τέθηκε υπό την κοινή εγγύηση των μεγάλων δυνάμεων — η εγγύηση αυτή στην πράξη θα γινόταν νέα πύλη επεμβάσεων.", "cfe6d847"]},
"OLAYLAR:1876-12-23:0":{"b": ["Κανούν-ι Εσασί — Α΄ Συνταγματική Περίοδος", "0fe052c1"], "d": ["Την ημέρα που άνοιξε η διεθνής διάσκεψη που συγκλήθηκε στην Κωνσταντινούπολη για να συζητήσει τη βαλκανική κρίση, με κανονιοβολισμούς διακηρύχθηκε το πρώτο οθωμανικό σύνταγμα· με το Κανούν-ι Εσασί, έργο του κινήματος των «Νέων Οθωμανών» υπό την ηγεσία του Μιντχάτ Πασά, ιδρύθηκε δικοινοβουλευτικό κοινοβούλιο. Η Μεκλίς-ι Μεμπουσάν άνοιξε τον Μάρτιο του 1877· ωστόσο ο Αμπντούλχαμιτ Β΄, επικαλούμενος τον Πόλεμο του ’93, διέκοψε επ' αόριστον τη βουλή τον Φεβρουάριο του 1878 και το σύνταγμα έμεινε σε αναστολή τριάντα χρόνια.", "c0f01a41"]},
"OLAYLAR:1877-04-24:0":{"b": ["Πόλεμος του ’93 (Οθωμανο-ρωσικός πόλεμος 1877–78)", "5bd96af7"], "d": ["Στον πόλεμο που ονομάστηκε «Πόλεμος του ’93» επειδή αντιστοιχούσε στο έτος 1293 του ρούμι ημερολογίου, οι ρωσικοί στρατοί επιτέθηκαν σε δύο μέτωπα· παρότι η άμυνα της Πλεύνας από τον Γκαζί Οσμάν Πασά και οι μάχες του Καυκάσου από τον Αχμέτ Μουχτάρ Πασά έγιναν έπος, το μέτωπο κατέρρευσε και οι Ρώσοι προχώρησαν μέχρι το Γεσίλκιοϊ (Αγιος Στέφανος). Ο πόλεμος ξεκίνησε τα μεγάλα κύματα μουσουλμανικής μετανάστευσης από τα Βαλκάνια και τον Καύκασο προς την Κωνσταντινούπολη, των οποίων τα αποτελέσματα φτάνουν μέχρι σήμερα· η δημογραφική και οικονομική δομή της αυτοκρατορίας δεν επανήλθε ποτέ στην προηγούμενη κατάσταση.", "3a2b2296"]},
"OLAYLAR:1878-07-13:0":{"b": ["Συνθήκη του Βερολίνου", "47f76a49"], "d": ["Το Συνέδριο του Βερολίνου, που αναθεώρησε τη «Μεγάλη Βουλγαρία» που δημιούργησε ο Άγιος Στέφανος στο όνομα της ισορροπίας των μεγάλων δυνάμεων, άφησε ωστόσο μια βαριά εικόνα: η Σερβία, το Μαυροβούνιο και η Ρουμανία έγιναν ανεξάρτητα· ιδρύθηκε το αυτόνομο Πριγκιπάτο της Βουλγαρίας· η Βοσνία-Ερζεγοβίνη παραχωρήθηκε στην αυστριακή κατοχή, η Κύπρος στην αγγλική διοίκηση, το Καρς–Αρνταχάν–Βατούμ στη Ρωσία. Η πεντακοσίων ετών οθωμανική τάξη στη Ρούμελη διαλύθηκε σε μεγάλο βαθμό· το «ανατολικό ζήτημα» έγινε σταθερό θέμα της ευρωπαϊκής διπλωματίας. Άλλοι οικισμοί που χάθηκαν την ίδια ημερομηνία: Φιλιππούπολη, Βιδίνιο, Τίρνοβο, Βάρνα, Şumnu, Silistre, Rusçuk, Βουκουρέστι, Ιάσιο, Κωστάντζα. Η Ρουμανία, με αντάλλαγμα την παραχώρηση της Βεσσαραβίας στη Ρωσία, πήρε την Τούλτσεα (Tulcea) και τη Δοβρουτσά: η Tulça (Tulcea), το Babadağı (Babadag), το Maçin, το İshakçı (Isaccea), το Hırsova (Hârșova) και η Mangalya (Mangalia) στη Βόρεια Δοβρουτσά περιήλθαν στη Ρουμανία.", "5c7d5594"]},
"OLAYLAR:1881-05-12:0":{"b": ["Κατοχή της Τυνησίας και Ντουγιούν-ι Ουμουμιγιέ", "c7e25598"], "d": ["Η Γαλλία, με πρόσχημα τα επεισόδια στα σύνορα με την Αλγερία, κατέλαβε την Τυνησία και την έθεσε υπό την προστασία της με τη Συνθήκη του Μπαρντό· η οθωμανική παρουσία στη Βόρεια Αφρική περιορίστηκε στην Τριπολίτιδα. Με το Διάταγμα του Μουχαρρέμ που εκδόθηκε την ίδια χρονιά ιδρύθηκε η Διοίκηση Ντουγιούν-ι Ουμουμιγιέ, όπου εκπροσωπούνταν οι πιστωτές, για τη διαχείριση των χρεοκοπημένων εξωτερικών χρεών: βασικά έσοδα όπως το αλάτι, ο καπνός και το μετάξι συνδέθηκαν απευθείας με αυτή την ξένη διοίκηση και η οικονομική κυριαρχία περιορίστηκε σοβαρά. Άλλοι οικισμοί που χάθηκαν την ίδια ημερομηνία: Kayrevan, Gabes, Sfaks, Cerbe (Djerba).", "64f23b86"]},
"OLAYLAR:1882-09-13:0":{"b": ["Αγγλική κατοχή της Αιγύπτου", "f1269768"], "d": ["Το κίνημα του Ουράμπι Πασά, που αναδύθηκε στην Αίγυπτο ενάντια στην οικονομική χρεοκοπία και τον ξένο έλεγχο, συνετρίβη με τη νίκη του Τελ ελ-Κεμπίρ του αγγλικού στρατού που αποβιβάστηκε μετά τον βομβαρδισμό της Αλεξάνδρειας και το Κάιρο καταλήφθηκε. Αν και η Αίγυπτος εξακολούθησε νομικά να παραμένει εξαρτημένη από τους Οθωμανούς, de facto πέρασε σε αγγλική διοίκηση· ο έλεγχος της Διώρυγας του Σουέζ εγκαταστάθηκε στο κέντρο της βρετανικής αυτοκρατορικής στρατηγικής.", "b7bcf2d2"]},
"OLAYLAR:1908-07-23:0":{"b": ["Διακήρυξη της Β΄ Συνταγματικής Περίοδου", "95ee2fd2"], "d": ["Μπροστά στο κίνημα που μεγάλωσε με την έξοδο αξιωματικών της Εταιρείας Ένωση και Πρόοδος στα βουνά της Μακεδονίας, ο Αμπντούλχαμιτ Β΄ έθεσε ξανά σε ισχύ το Κανούν-ι Εσασί· η «διακήρυξη της ελευθερίας» έγινε δεκτή με ενθουσιασμό και προκηρύχθηκαν εκλογές. Ωστόσο δεν επήλθε σταθερότητα: μετά την καταστολή του Συμβάντος της 31ης Μαρτίου (Απρίλιος 1909) ο Αμπντούλχαμιτ καθαιρέθηκε· η ανεξαρτησία της Βουλγαρίας, η προσάρτηση της Βοσνίας και η στροφή της Κρήτης προς την Ελλάδα έλαβαν επίσης χώρα σε αυτούς τους ταραχώδεις μήνες.", "370f359f"]},
"OLAYLAR:1911-09-29:0":{"b": ["Ιταλοτουρκικός πόλεμος (Τριπολίτιδα)", "ed441994"], "d": ["Η Ιταλία, που αναζητούσε αποικίες, κήρυξε τον πόλεμο στην Τριπολίτιδα, το τελευταίο οθωμανικό έδαφος στη Βόρεια Αφρική, και κατέλαβε τις ακτές· καθώς το κράτος, χωρίς στόλο, δεν μπορούσε να στείλει τακτικό στρατό, νεαροί αξιωματικοί όπως ο Μουσταφά Κεμάλ και ο Ενβέρ Μπέης πέρασαν κρυφά στην περιοχή και οργάνωσαν αποτελεσματική αντίσταση με τις φυλές των Σενουσί. Με τη Συνθήκη του Ουσί (18 Οκτωβρίου 1912), που υπογράφηκε μετά το ξέσπασμα του Βαλκανικού Πολέμου, η Λιβύη παραχωρήθηκε στην Ιταλία· η Ιταλία κατέλαβε επίσης τη Ρόδο και τα Δωδεκάνησα.", "9820482a"]},
"OLAYLAR:1913-05-30:0":{"b": ["Συνθήκη του Λονδίνου — Απώλεια της Ρούμελης", "f3f976df"], "d": ["Με τη Συνθήκη του Λονδίνου, που έβαλε τέλος στον Α΄ Βαλκανικό Πόλεμο, χάθηκαν όλα τα εδάφη δυτικά της γραμμής Μίδεια–Ένεζ και τα νησιά του Αιγαίου· η Αλβανία έγινε ανεξάρτητη. Από τη Ρούμελη, που επί πάνω από πεντακόσια χρόνια ήταν το δημογραφικό, οικονομικό και πολιτιστικό κέντρο βάρους της αυτοκρατορίας, θα έμενε μόνο η Ανατολική Θράκη (η Αδριανούπολη ανακτήθηκε στον Β΄ Βαλκανικό Πόλεμο)· η απώλεια ριζικά σκλήρυνε την πολιτική πολέμου και εποικισμού της διοίκησης της Ένωσης και Προόδου. Χάθηκαν τα εξής μέρη δυτικά της γραμμής Μίδεια–Ένεζ: Üsküp, Köprülü (Veles), İştip (Štip), Ustrumca, Doyran, Gevgili (Gevgelija), Manastır, Ohri, Debre (Dibra), Prizren, Priştine, Peç (Pejë), Yenipazar (Novi Pazar), Kosova Ovası (Kosovo Polje)· Σέρρες, Δράμα, Καβάλα, Petriç, Nevrokop, Ξάνθη, Κομοτηνή, Αλεξανδρούπολη (Dedeağaç), Διδυμότειχο, Çirmen, Ferecik (Feres), Sofulu (Soufli), Orestiada (Kumçiftliği), Praviște (Eleftheroupoli), Stérna, Távri, Umur Fakih (Fakia), Malak Dervent (Lalkovo)· στην Κρήτη τα Χανιά, ο Χάνδακας (Ηράκλειο), η Κρήτη (Ρέθυμνο), η Σητεία και οι Σφακιά.", "b193bdae"]},
"OLAYLAR:1914-11-01:0":{"b": ["Είσοδος στον Α΄ Παγκόσμιο Πόλεμο", "05a0252e"], "d": ["Η είσοδος των θωρηκτών Goeben και Breslau, που διέφυγαν από την Αγγλία, στα Στενά παρουσιαζόμενων ως αγορασμένων, τράβηξε βήμα βήμα το κράτος στο πλευρό της Γερμανίας· με τον βομβαρδισμό των ρωσικών λιμανιών από τον στόλο υπό τον ναύαρχο Souchon (29 Οκτωβρίου) ο πόλεμος ξεκίνησε de facto και οι αμοιβαίες κηρύξεις ήρθαν στις αρχές Νοεμβρίου. Παρά την κήρυξη του Τζιχάντ-ι Εκμπέρ, δεν επήλθε το αναμενόμενο αποτέλεσμα· η αυτοκρατορία, επί τέσσερα χρόνια, μπήκε σε πόλεμο επιβίωσης σε πέντε διαφορετικά μέτωπα, από τον Καύκασο μέχρι την Παλαιστίνη.", "a9f179e7"]},
"OLAYLAR:1915-03-18:0":{"b": ["Νίκη των Δαρδανελίων (Τσανάκκαλε)", "95d888e8"], "d": ["Η συμμαχική αρμάδα, που στόχευε να ρίξει την Κωνσταντινούπολη και να φτάσει στη Ρωσία, απωθήθηκε από τα Στενά στις 18 Μαρτίου με το πυρ των ναρκοπεδίων και των πυροβολείων· η γραμμή που έστρωσε το νάρκαλιευτικό Nusret καθόρισε την τύχη του πολέμου. Η χερσαία επιχείρηση της Καλλίπολης, που ξεκίνησε τον Απρίλιο, ανακόπηκε επίσης στις Αναφάρτες και στο Τζονκμπαϊρί· οι σύμμαχοι εκκένωσαν πλήρως τη χερσόνησο τον Ιανουάριο του 1916. Το όνομα του αντισυνταγματάρχη Μουσταφά Κεμάλ έγινε γνωστό σε αυτό το μέτωπο· η νίκη, που κερδήθηκε με περίπου ένα τέταρτο εκατομμυρίου νεκρούς και απολεσθέντες, θεωρείται ο τόπος γέννησης των στελεχών και του πνεύματος του Εθνικού Αγώνα.", "005303c3"]},
"OLAYLAR:1916-06-10:0":{"b": ["Εξέγερση του Σερίφη Χουσεΐν", "75f7c58c"], "d": ["Ο Εμίρης της Μέκκας Σερίφης Χουσεΐν, μετά την μυστική αλληλογραφία που διεξήγαγε με τους Άγγλους, εξεγέρθηκε με την υπόσχεση ανεξάρτητου αραβικού βασιλείου· ο σιδηρόδρομος του Χιτζάζ έγινε στόχος επιδρομών. Αν και η θρυλική άμυνα της Μεδίνας από τον Φαχρεντίν Πασά, που κράτησε μέχρι μετά την ανακωχή, έμεινε ως σύμβολο της αντίστασης, η εξέγερση, σε συνδυασμό με την αγγλική προέλαση στο μέτωπο της Παλαιστίνης, επιτάχυνε τη διάλυση της οθωμανικής κυριαρχίας στις αραβικές επαρχίες. Άλλοι οικισμοί που χάθηκαν την ίδια ημερομηνία: Tâif.", "a0e859bd"]},
"OLAYLAR:1918-10-30:0":{"b": ["Ανακωχή του Μούδρου", "9e87c767"], "d": ["Το Οθωμανικό κράτος, του οποίου τα μέτωπα αποκόπηκαν μεταξύ τους με την κατάρρευση της Βουλγαρίας, αποσύρθηκε από τον πόλεμο με την ανακωχή που υπογράφηκε στο θωρηκτό Agamemnon. Το άρθρο 7, που επέτρεπε το άνοιγμα των Στενών και ιδίως την κατοχή τόπων των οποίων η ασφάλεια απειλούνταν, έγινε σύντομα το νομικό περιτύλιγμα του de facto διαμελισμού: καταλήφθηκαν η Μοσούλη, η Αλεξανδρέτα και έπειτα η Σμύρνη και η Κωνσταντινούπολη. Η ανακωχή θεωρείται το έγγραφο του de facto τέλους της αυτοκρατορίας. Άλλοι οικισμοί που χάθηκαν την ίδια ημερομηνία: Hama, Δαμασκός, Homs.", "261b57f2"]},
"OLAYLAR:1919-05-19:0":{"b": ["Ο Μουσταφά Κεμάλ στη Σαμψούντα — Εθνικός Αγώνας", "09a8f784"], "d": ["Στο κλίμα αγανάκτησης που δημιούργησε η κατοχή της Σμύρνης, ο Μουσταφά Κεμάλ Πασάς, που αποβιβάστηκε στη Σαμψούντα με την ιδιότητα του επιθεωρητή της 9ης Στρατιάς, έστρεψε το επίσημο καθήκον του στην οργάνωση της αντίστασης στη Μικρά Ασία. Η Εγκύκλιος της Αμάσειας και τα συνέδρια του Ερζερούμ και της Σεβάστειας (Σιβάς) είναι η συνέχεια αυτής της εξόδου· η αρχή «την ανεξαρτησία του έθνους θα τη σώσει πάλι η αποφασιστικότητα και η απόφαση του ίδιου του έθνους» έγινε ο πυρήνας του πολιτικού προγράμματος του Εθνικού Αγώνα.", "330e4c51"]},
"OLAYLAR:1920-04-23:0":{"b": ["Άνοιγμα της Μεγάλης Εθνοσυνέλευσης της Τουρκίας (TBMM) και Σέβρες", "2008feec"], "d": ["Μετά την επίσημη κατοχή της Κωνσταντινούπολης και τη διάλυση της Μεκλίς-ι Μεμπουσάν, στις 23 Απριλίου 1920 άνοιξε στην Άγκυρα η Μεγάλη Εθνοσυνέλευση· η συνέλευση, που συγκέντρωσε στον εαυτό της έκτακτες εξουσίες, έγινε ο πυρήνας του νέου κράτους που βασιζόταν στην εθνική βούληση. Η Συνθήκη των Σεβρών που υπέγραψε τον Αύγουστο η κυβέρνηση της Κωνσταντινούπολης μοίραζε τη Μικρά Ασία· η TBMM κήρυξε προδότες της πατρίδας όσους υπέγραψαν τη συνθήκη και οι Σέβρες δεν εφαρμόστηκαν ποτέ.", "9b4f7c0b"]},
"OLAYLAR:1921-09-13:0":{"b": ["Μάχη του Σαγγαρίου", "f2f970a6"], "d": ["Η ελληνική επίθεση, που πλησίασε την Άγκυρα σε απόσταση 50 χιλιομέτρων, κάμφθηκε σε μάχη 22 ημερών και 22 νυχτών που διεξήχθη με τη διαταγή «δεν υπάρχει γραμμή άμυνας, υπάρχει επιφάνεια άμυνας» του Μουσταφά Κεμάλ Πασά, ο οποίος είχε αναλάβει την αρχιστρατηγία. Ο ελληνικός στρατός πέρασε για πρώτη φορά σε στρατηγική άμυνα· η νίκη έφερε στον Μουσταφά Κεμάλ τους τίτλους του γαζί και του μαρεσάλ (στρατάρχη) και άνοιξε την πόρτα στη Συμφωνία της Άγκυρας με τη Γαλλία και στη διεθνή αναγνώριση.", "f3372310"]},
"OLAYLAR:1922-09-09:0":{"b": ["Μεγάλη Επίθεση και απελευθέρωση της Σμύρνης", "172a50c4"], "d": ["Η επίθεση που ξεκίνησε το πρωί της 26ης Αυγούστου από το Κοτζατέπε οδήγησε στις 30 Αυγούστου στην εξόντωση των κύριων ελληνικών δυνάμεων με τη Μάχη του Αρχιστράτηγου στο Ντουμλουπινάρ· με την καταδίωξη που συνεχίστηκε με τη διαταγή «Στρατιές, ο πρώτος σας στόχος είναι η Μεσόγειος, εμπρός!», η Σμύρνη απελευθερώθηκε στις 9 Σεπτεμβρίου. Με την Ανακωχή των Μουδανιών (11 Οκτωβρίου) η Ανατολική Θράκη ανακτήθηκε χωρίς πόλεμο· η στρατιωτική νίκη καθόρισε τη δύναμη του νέου κράτους στο τραπέζι της Λωζάνης.", "02bd94a5"]},
"OLAYLAR:1922-11-01:0":{"b": ["Κατάργηση του σουλτανάτου", "9f36a9f6"], "d": ["Μετά την πρόσκληση και της κυβέρνησης της Κωνσταντινούπολης στις διαπραγματεύσεις της Λωζάνης, η TBMM την 1η Νοεμβρίου 1922 διαχώρισε το σουλτανάτο από το χαλιφάτο και κατήργησε το σουλτανάτο· η οθωμανική δυναστική διοίκηση 623 ετών έληξε νομικά. Ο Μεχμέτ ΣΤ΄ Βαχιντεντίν έφυγε από τη χώρα στις 17 Νοεμβρίου με ένα βρετανικό θωρηκτό· στο αξίωμα του χαλίφη τοποθετήθηκε με απόφαση της TBMM ο Αμπντουλμετζίντ Εφέντη και το αξίωμα αυτό θα καταργούνταν στις 3 Μαρτίου 1924.", "910b763d"]},
"OLAYLAR:1923-07-24:0":{"b": ["Συνθήκη της Λωζάνης", "38c27f7d"], "d": ["Με τη Συνθήκη Ειρήνης της Λωζάνης, που υπογράφηκε στο τέλος σκληρών διαπραγματεύσεων οκτώ μηνών, αναγνωρίστηκαν διεθνώς τα σύνορα, η πλήρης ανεξαρτησία και η κυριαρχία του νέου τουρκικού κράτους· καταργήθηκαν οι διομολογήσεις, τέθηκε σε διαδικασία εκκαθάρισης η Ντουγιούν-ι Ουμουμιγιέ και ρυθμίστηκε η ανταλλαγή πληθυσμών. Η Λωζάνη, που ακύρωσε de facto τις Σέβρες, θεωρείται η διπλωματική νίκη του Εθνικού Αγώνα και το ιδρυτικό εξωτερικό έγγραφο της Δημοκρατίας.", "6d498c3f"]},
"OLAYLAR:1923-10-29:0":{"b": ["Διακήρυξη της Δημοκρατίας", "d5bfcdfb"], "d": ["Με την αποδοχή από την TBMM, με τροποποίηση του συντάγματος, της διάταξης «η μορφή διακυβέρνησης του Τουρκικού Κράτους είναι η δημοκρατία», διακηρύχθηκε η Δημοκρατία· ο Μουσταφά Κεμάλ Πασάς εξελέγη πρώτος πρόεδρος. Έτσι έκλεισε η οθωμανική περιπέτεια 624 ετών που είχε αρχίσει το 1299 ως συνοριακό βεγιλίκι· το νέο κράτος, όπου η κυριαρχία ανήκει άνευ όρων στο έθνος, ιδρύθηκε πάνω στην κληρονομιά της αυτοκρατορίας.", "f5cabb8c"]},
"OLAYLAR_0073_IRAN_YANYA:1820-03-01:0":{"b": ["Καθαίρεση του Tepedelenli Ali Paşa και έναρξη της πολιορκίας των Ιωαννίνων", "e8a6530b"], "d": ["Η πολιτική του Μαχμούτ Β' για την εκκαθάριση των τοπικών δυνάμεων έφτασε στον Tepedelenli Ali Paşa, που επί τριάντα τρία χρόνια διοικούσε τα Ιωάννινα και κρατούσε στην πράξη τη Θεσσαλία και την Ήπειρο. Ο πασάς καθαιρέθηκε από την αρχηγία των derbends και ο γιος του Veli από την πασαλίκι των Τρικάλων· επειδή αναμενόταν ότι δεν θα υπάκουε, στάλθηκαν δυνάμεις εναντίον του. Ο Hurşid Ahmed Paşa, που ανέλαβε αυτό το έργο, ήταν ταυτόχρονα κυβερνήτης του Μορέως και του δόθηκε και το serasker της Ρούμελης· όλοι οι πολιτικοί και στρατιωτικοί διοικητές της περιοχής ανέλαβαν να συλλάβουν τον Tepedelenli. Δηλαδή, όταν ξέσπασε η ελληνική εξέγερση, ο διοικητής που έπρεπε να διοικεί τον Μορέα και οι δυνάμεις υπό τις διαταγές του πολιορκούσαν το Κάστρο των Ιωαννίνων. Ο Ali Paşa στις 23 Μαΐου 1820 διοργάνωσε συνάντηση με Έλληνες στα Ιωάννινα, επιχείρησε να ιδρύσει υπό τη διοίκησή του ελληνική επαρχία και τους βοήθησε με χρήματα και όπλα. Στην αντίπερα πλευρά δεν υπήρχε δύναμη που να υποτιμάται: ο Ali Paşa είχε στρατό 30-40.000 ανδρών, από τους οποίους 7.000 μόνιμοι, και μικρό στόλο· ο πληθυσμός υπό τη διοίκησή του υπολογιζόταν σε 1,5-2 εκατομμύρια, το ετήσιο εισόδημα σε 4-5 εκατομμύρια kuruş.", "d0250e2a"]},
"OLAYLAR_0073_IRAN_YANYA:1821-01-01:0":{"b": ["Ξεκίνησε ο οθωμανοϊρανικός πόλεμος — απώλεια του Kars και του Bayazıt, πολιορκία του Erzurum", "570b27bd"], "d": ["Τον δεύτερο χρόνο της ελληνικής εξέγερσης το ανατολικό σύνορο της αυτοκρατορίας μετατράπηκε σε πολεμική ζώνη. Ο διάδοχος των Qajar Abbas Mirza, με πρόσχημα ότι οι οθωμανικοί εκπρόσωποι έψαξαν το καραβάνι με τη σύζυγο του σάχη που πήγαινε στο χατζ, πέρασε το σύνορο με μεγάλη στρατιωτική δύναμη· κατέλαβε τα βιλαέτια Kars και Bayazıt και πολιόρκησε το Erzurum. Η δύναμη απέναντι δεν ήταν συνηθισμένη συνοριακή μονάδα: ο Abbas Mirza είχε εκπαιδεύσει τον στρατό του Αζερμπαϊτζάν σύμφωνα με ευρωπαϊκές μεθόδους, είχε ιδρύσει στην Ταυρίδα εργαστήριο πυρίτιδας και εργοστάσια κανονιών. Η Οθωμανική Αυτοκρατορία εν τω μεταξύ ασχολούνταν στα δυτικά με την εξέγερση του Μορέως και στα βορειοδυτικά με την αντίσταση του Tepedelenli Ali Paşa στα Ιωάννινα και δεν είχε στρατό εκπαιδευμένο με ευρωπαϊκό τρόπο· το Τάγμα των Γενιτσάρων θα επιβίωνε μέχρι το 1826.", "88b4be76"]},
"OLAYLAR_0073_IRAN_YANYA:1821-01-01:1":{"b": ["Ιρανική κατοχή της Süleymaniye και της Βαγδάτης — πολιορκία του Kirkuk", "384d74e4"], "d": ["Ταυτόχρονα με την επιχείρηση στην Ανατολική Ανατολία, οι ιρανικές δυνάμεις εξαπέλυσαν ευρεία επίθεση στο Βόρειο Ιράκ και στο βιλαέτι της Βαγδάτης που υπήρχαν υπό οθωμανική διοίκηση. Τη Βαγδάτη διοικούσε τότε ο Kölemen Davud Paşa, κυβερνήτης από το 1817· ο πασάς είχε δύναμη 10.000 ανδρών πεζικού και πυροβολικού που είχε εκπαιδεύσει ο Deveaux, πρώην βοηθός του Ναπολέοντα. Στο κέντρο της αυτοκρατορίας δεν υπήρχε ακόμη τέτοιος στρατός — οι εκπαιδευμένες με ευρωπαϊκό τρόπο μονάδες εκείνα τα χρόνια βρίσκονταν μόνο στα χέρια ισχυρών επαρχιακών κυβερνητών. Αυτό που έβαλε τέλος στον πόλεμο δεν ήταν οθωμανική νίκη: η οθωμανική αντίσταση και η επιδημία που κατέλαβε το Αζερμπαϊτζάν ανάγκασαν τις ιρανικές δυνάμεις να αποσυρθούν.", "b60b096c"]},
"OLAYLAR_0073_IRAN_YANYA:1822-02-14:0":{"b": ["Δολοφονία του Tepedelenli Ali Paşa — το τέλος της πολιορκίας των Ιωαννίνων", "da679150"], "d": ["Η αντίσταση στα Ιωάννινα διήρκεσε σχεδόν δύο χρόνια και ακριβώς μέσα σε αυτό το διάστημα η ελληνική εξέγερση απέκτησε γενική εξάπλωση. Όταν ο Hurşid Paşa έστειλε κατασκόπους στο φρούριο και διένειμε βαθμούς και αμοιβές σε όσους δραπέτευαν, ο αριθμός των στρατιωτών γύρω από τον Ali Paşa έπεσε στους σαράντα πενήντα· ο πασάς αποσύρθηκε στο Μοναστήρι του Αγίου Παντελεήμονα πάνω στη λίμνη με τη διαβεβαίωση ότι αν παραδοθεί δεν θα του πειράξουν τη ζωή. Εν τω μεταξύ η οικογένεια του Hurşid Paşa είχε πέσει στα χέρια των Ελλήνων στασιαστών· για να επιστρέψει όσο πιο γρήγορα στον Μορέα, αγνόησε το έγγραφο ασφάλειας που είχε δώσει και ετοίμασε πλαστό διάταγμα θανατικής καταδίκης. Όταν μπήκαν στο δωμάτιό του, ο Ali Paşa απάντησε με όπλο και σκοτώθηκε στη σύγκρουση που ακολούθησε· το κεφάλι του μεταφέρθηκε στην Κωνσταντινούπολη στις 24 Φεβρουαρίου. Η πολιορκία είχε φέρει στο φως και το ρήγμα μέσα στην ίδια την οθωμανική διοίκηση: όταν η εξέγερση του Μορέως έγινε πιο επικίνδυνη από το ζήτημα του Tepedelenli, ο Seyyid Ali Paşa διορίστηκε ανεξάρτητος serasker του Μορέως, ο Hurşid Paşa, που δεν το άρεσε αυτό, απέρριψε τα αιτήματα βοήθειάς του και προσπάθησε μάλιστα να τον παρουσιάσει αποτυχημένο στα μάτια του κράτους. Στο τέλος της χρονιάς που εξαφανίστηκε ο Ali Paşa, έπεσε το ισχυρότερο φρούριο του Μορέως, το Ναύπλιο (Anabolu).", "c7a915be"]},
"OLAYLAR_0073_IRAN_YANYA:1823-07-28:0":{"b": ["Συνθήκη του Erzurum — αποχώρηση των ιρανικών δυνάμεων σε εξήντα ημέρες", "166373c3"], "d": ["Ο διετής πόλεμος έληξε με την ειρηνευτική συνθήκη που υπογράφηκε στο Erzurum. Σύμφωνα με τη συνθήκη, οι ιρανικές δυνάμεις θα αποσύρονταν μέσα σε εξήντα ημέρες από τα εδάφη που είχαν καταλάβει. Η συνθήκη δεν χάραξε νέο σύνορο, επανέφερε την προπολεμική κατάσταση· οι συνοριακές διαφορές των δύο κρατών θα μετατραπούν ξανά σε σύγκρουση το 1833-1842 και θα ρυθμιστούν μόνο το 1847 με δεύτερη συνθήκη, που υπογράφηκε πάλι στο Erzurum. Το κλείσιμο του ανατολικού μετώπου ήταν προϋπόθεση για να μπορέσει η αυτοκρατορία να ρίξει όλο της το βάρος στην ελληνική εξέγερση.", "7c54983b"]},
"OLAYLAR_2S1019:0330-05-11:0":{"b": ["Η Κωνσταντινούπολη εγκαινιάστηκε ως πρωτεύουσα του Βυζαντίου (Ανατολικής Ρώμης)", "9d155dd6"], "d": ["Το Βυζάντιο που ξανάχτισε ο Κωνσταντίνος εγκαινιάστηκε με τελετές που διήρκεσαν ημέρες ως η νέα πρωτεύουσα της αυτοκρατορίας. Η καταγραφή του Βυζαντίου (Ανατολικής Ρώμης) στον άτλαντα ξεκινά στην Κωνσταντινούπολη με αυτή την ημέρα.", "c4468b48"]},
"OLAYLAR_2S1019:0969-07-06:0":{"b": ["Οι Φατιμίδες κατέλαβαν την Αίγυπτο: ο Jawhar al-Siqilli μπήκε στη Fustat, τέθηκαν τα θεμέλια του Καΐρου", "500aef7a"], "d": ["Ο φατιμιδικός διοικητής Jawhar al-Siqilli, βάζοντας τέλος στην κυριαρχία των Ikhshidides στην Αίγυπτο, μπήκε στη Fustat και ίδρυσε στη Manah, στα βόρεια, το ανάκτορο και τα τείχη της νέας πρωτεύουσας, του Καΐρου.", "d9599f90"]},
"OLAYLAR_2S1019:0990-03-31:0":{"b": ["Οι Ουκαϊλίδες κατέλαβαν τη Μοσούλη — ίδρυση της δυναστείας των Ουκαϊλιδών της Μοσούλης", "49eb93a6"], "d": ["Ο Abu'l-Zawwad, σκοτώνοντας τον Abu Tahir Ibrahim και τον γιο του, κατέλαβε τη Μοσούλη· στην πόλη ιδρύθηκε η δυναστεία των Ουκαϊλιδών, εξαρτημένη από τους Μπουγιίδες.", "affdc0ec"]},
"OLAYLAR_2S1019:1084-12-12:0":{"b": ["Ο Sulayman Shah, γιος του Kutalmish, πήρε την Αντιόχεια από το Βυζάντιο", "17d1c6f0"], "d": ["Την Αντιόχεια, που έμεινε πάνω από έναν αιώνα στα βυζαντινά χέρια, την πήρε ο ηγεμόνας των Σελτζούκων της Ανατολίας Sulayman Shah· η εσωτερική ακρόπολη που αντιστεκόταν παραδόθηκε στις 12 Ιανουαρίου 1085.", "a6f1f783"]},
"OLAYLAR_2S1019:1098-06-03:0":{"b": ["Οι Σταυροφόροι κατέλαβαν την Αντιόχεια — ιδρύθηκε το Πριγκιπάτο της Αντιόχειας", "c9f47942"], "d": ["Η Αντιόχεια, που άντεξε σε μακρά πολιορκία, περιήλθε στα χέρια των Σταυροφόρων με την προδοσία του Φιρούζ, διοικητή του Γιαγκισιγιάν. Το Πριγκιπάτο της Αντιόχειας που ιδρύθηκε περιέλαβε και την Αλεξανδρέττα.", "f6409190"]},
"OLAYLAR_2S1019:1207-03-05:0":{"b": ["Ο Γκιγιασεντίν Κεϊχουσρέβ κατέκτησε την Αττάλεια — οι Σελτζούκοι έφτασαν στη Μεσόγειο", "9812e629"], "d": ["Την Αττάλεια, που μετά την κατάληψη της Κωνσταντινούπολης από τους Λατίνους πέρασε στα χέρια του Ιταλού Aldobrandini, την κατέλαβε ο σουλτάνος των Σελτζούκων της Ανατολίας Α΄ Γκιγιασεντίν Κεϊχουσρέβ με την υποστήριξη και των Ελλήνων που ήταν δυσαρεστημένοι με τη λατινική διοίκηση.", "9d3888e0"]},
"OLAYLAR_2S1019:1216-01-22:0":{"b": ["Ο Ιζεντίν Κεϊκαβούς ανακατέλαβε την Αττάλεια από τους Κυπρίους", "ec2446f9"], "d": ["Την Αττάλεια, που χάθηκε το 1212 ως αποτέλεσμα εξέγερσης με την υποστήριξη του βασιλιά της Κύπρου, την ξανακατέκτησε ο Α΄ Ιζεντίν Κεϊκαβούς και έδωσε ξανά τη διοίκησή της στον Μουμπαριζεντίν Ερτοκούς.", "62389ac4"]},
"OLAYLAR_2S1019:1268-03-08:0":{"b": ["Ο Μπαϊμπάρς πήρε την Ιόππη από τους Σταυροφόρους — η κυριαρχία του Βασιλείου της Ιερουσαλήμ στην Ιόππη έληξε", "c7629d70"], "d": ["Ο Μαμελούκος σουλτάνος Α΄ Μπαϊμπάρς έβαλε τέλος στη σταυροφορική κυριαρχία στην Ιόππη, έβαλε να καταστραφεί η πόλη· έστειλε το ξύλο και το μάρμαρο του εσωτερικού κάστρου για την ανέγερση του τζαμιού του στο Κάιρο.", "32ed8c27"]},
"OLAYLAR_2S1019:1268-05-18:0":{"b": ["Ο Μπαϊμπάρς κατέλαβε την Αντιόχεια — τέλος του Πριγκιπάτου της Αντιόχειας", "da2b511a"], "d": ["Ο μαμελουκικός στρατός με γενική επίθεση πέρασε τα τείχη της Αντιόχειας· το σταυροφορικό πριγκιπάτο των 170 ετών έληξε και η Αλεξανδρέττα προσαρτήθηκε ξανά στα ισλαμικά εδάφη.", "7f091a6b"]},
"OLAYLAR_2S1019:1328-11-05:0":{"b": ["Οι Καραμανογλού ανακατέλαβαν το Ικόνιο από τους Ιλχανίδες", "057ec073"], "d": ["Μετά τη φυγή στην Αίγυπτο του ιλχανιδικού διοικητή της Ανατολίας Ντεμιρτάς, το Ικόνιο περιήλθε ξανά στα χέρια των Καραμανογλού. Η πόλη θα περάσει το 1350 στον Ερετνά.", "c2d583f3"]},
"OLAYLAR_2S1019:1344-03-26:0":{"b": ["Ο βασιλιάς της Καστίλης ΙΑ΄ Αλφόνσος κατέλαβε το Αλγκεσίρας (Cezîretülhadrâ): μετά από πολιορκία είκοσι μηνών η κυριαρχία των Μερινιδών έληξε", "5de2a877"], "d": ["Μετά την πολιορκία του βασιλιά της Καστίλης ΙΑ΄ Αλφόνσου που διήρκεσε περίπου είκοσι μήνες, στο τέλος των διαπραγματεύσεων που άρχισαν στις 21 Μαρτίου 1344 ο ηγεμόνας των Μερινιδών Αμπού αλ-Χασάν ανακοίνωσε στους μουσουλμάνους να εγκαταλείψουν την πόλη· στις 26 Μαρτίου εκκενώθηκε η Villa Nueva, την επόμενη ημέρα η Villa Vieja και οι Καστιλιάνοι παρέλαβαν την πόλη. Ο Αλφόνσος ΙΑ΄ μπήκε με τελετή στην πόλη στις 28 Μαρτίου 1344 (Κυριακή των Βαΐων). Το Αλγκεσίρας έμεινε στην Καστίλη μέχρι το 1369.", "ceda27c4"]},
"OLAYLAR_2S1019:1345-01-01:0":{"b": ["Ο Στέφανος Δουσάν πήρε τις Σέρρες από το Βυζάντιο", "2cc79d36"], "d": ["Ο Σέρβος βασιλιάς Στέφανος Δουσάν, εκμεταλλευόμενος τον βυζαντινό εμφύλιο, κατέλαβε τις Σέρρες και έκανε την πόλη πρωτεύουσα της Σερβικής Αυτοκρατορίας.", "24066996"]},
"OLAYLAR_2S1019:1375-01-01:0":{"b": ["Η κομητεία του Feldkirch πουλήθηκε στην Αυστρία των Αψβούργων", "fe4a0306"], "d": ["Ο Rudolf, ο τελευταίος κόμης του κλάδου Montfort-Feldkirch, το 1375 πούλησε όλη την περιουσία του στους δούκες της Αυστρίας Αψβούργους· η πραγματική μεταβίβαση ολοκληρώθηκε με τον θάνατό του (1390). Το Feldkirch ήταν το πρώτο μεγάλο τμήμα του Vorarlberg που πέρασε στους Αψβούργους.", "6f5d639e"]},
"OLAYLAR_2S1019:1389-07-01:0":{"b": ["Η Βαλτσίκ και η ακτή της Δοβρουτσάς μπήκαν στην οθωμανική διοίκηση", "dfd348b9"], "d": ["Μετά τη νίκη του Κοσσυφοπεδίου, η Βαλτσίκ στην ακτή της Δοβρουτσάς μπήκε στην οθωμανική διοίκηση. Την περιοχή θα καταλάβει αμέσως μετά ο βοεβόδας της Βλαχίας Μίρτσεα, η οθωμανική κυριαρχία θα αποκατασταθεί το 1393.", "e99a023b"]},
"OLAYLAR_2S1019:1392-10-26:0":{"b": ["Οι Σεγιίδες Μαραΐ παραδόθηκαν στον Ταμερλάνο στο Μαχανεσέρ — το Μαζενταράν πέρασε στους Τιμουρίδες", "125dbed8"], "d": ["Ο Ταμερλάνος, που μπήκε στο Μαζενταράν στην πενταετή εκστρατεία του, στρίμωξε στο κάστρο Μαχανεσέρ τους Μαραΐδες που στάθηκαν απέναντί του στο Καρατογάν και τους παρέλαβε. Έγινε μεγάλη σφαγή στη Σαρί και στο Αμούλ· η Σαρί δόθηκε στον Ισκεντέρ Σεϊχί, γιο του Κιγιά Εφρασιγιάμπ.", "0352c0d3"]},
"OLAYLAR_2S1019:1412-01-01:0":{"b": ["Το Σιμπένικ μπήκε ξανά στη διοίκηση της Βενετικής Δημοκρατίας", "9b7998bf"], "d": ["Μετά την πώληση το 1409 των δικαιωμάτων του Λαδίσλαου της Νάπολης στη Δαλματία στη Βενετία, το Σιμπένικ, που αντιστάθηκε, το 1412 μπήκε ξανά στη βενετική διοίκηση. Η πόλη έμεινε ως δαλματικό κτήμα της Βενετίας μέχρι την κατάλυση της Δημοκρατίας το 1797.", "ed5b7778"]},
"OLAYLAR_2S1019:1417-02-18:0":{"b": ["Εκστρατεία του Τσελεμπί Μεχμέτ κατά των Τσανταρογλού: το Τσανκιρί δόθηκε στον Κασίμ Μπέη υπό οθωμανική προστασία", "da03b919"], "d": ["Ο Τσελεμπί Μεχμέτ, που βάδισε κατά του Τσανταρογλού Ισφεντιγιάρ Μπέη που βοήθησε τον Σεΐχη Μπεντρεντίν να περάσει στη Βλαχία, προχώρησε στην Καστάμονη και πολιόρκησε τη Σινώπη όπου αποσύρθηκε ο Ισφεντιγιάρ. Ο Ισφεντιγιάρ αναγνώρισε την οθωμανική κυριαρχία· με το όρος Ιλγκάζ ως σύνορο, στον γιο του Κασίμ Μπέη, που είχε καταφύγει στους Οθωμανούς, δόθηκαν το Τσανκιρί και τα περίχωρα.", "f88b8d5e"]},
"OLAYLAR_2S1019:1439-08-27:0":{"b": ["Με την κατάληψη της Σμεντερέβου πέρασε στους Οθωμανούς και το Χισαρτζίκ (Grocka)", "ab724ec9"], "d": ["Η Σμεντερέβο καταλήφθηκε μετά από τρίμηνη πολιορκία. Το Χισαρτζίκ (Grocka), 17 χλμ. κοντά στη Σμεντερέβο, στον άτλαντα ακολουθεί την τύχη του αδελφού κέντρου Σμεντερέβου και την ίδια ημέρα περνά από το Σερβικό Δεσποτάτο στους Οθωμανούς (θα επιστραφεί το 1444).", "81989831"]},
"OLAYLAR_2S1019:1451-01-01:0":{"b": ["Το πρώτο μισό της κομητείας του Bregenz πουλήθηκε στην Αυστρία των Αψβούργων", "3a9598db"], "d": ["Η Elisabeth του Hochberg, κληρονόμος των Montfort-Bregenz, το 1451 πούλησε το μισό της κομητείας του Bregenz στους Αψβούργους· το υπόλοιπο μισό αποκτήθηκε το 1523. Το Bregenz έτσι έγινε μέρος του Vorarlberg των Αψβούργων.", "c02a452c"]},
"OLAYLAR_2S1019:1458-08-06:0":{"b": ["Με την παράδοση του Γκόρδους (Κόρινθος) πέρασε στους Οθωμανούς και η Σικυώνα", "c7b0d22d"], "d": ["Ο Πορθητής, στην εκστρατεία του Μοριά, κατέλαβε ειρηνικά το Γκόρδους (Κόρινθο) μετά από τρίμηνη πολιορκία. Η Σικυώνα, 17 χλμ. από την Κόρινθο, στον άτλαντα ακολουθεί την τύχη του αδελφού κέντρου Γκόρδους και την ίδια ημέρα περνά στους Οθωμανούς.", "42b1e20d"]},
"OLAYLAR_2S1019:1459-06-20:0":{"b": ["Με την παράδοση της Σμεντερέβου πέρασε στους Οθωμανούς και το Χισαρτζίκ (Grocka)", "e3d76f5c"], "d": ["Η χήρα του Λάζαρου Μπράνκοβιτς, Ελένη, παρέδωσε το κάστρο της Σμεντερέβου στους Οθωμανούς· το Σερβικό Δεσποτάτο έληξε. Το Χισαρτζίκ (Grocka), με αδελφό κέντρο τη Σμεντερέβο, περνά την ίδια ημέρα στους Οθωμανούς.", "13f15640"]},
"OLAYLAR_2S1019:1475-06-06:0":{"b": ["Παράδοση της Κάφα και υποτέλεια του χάνου της Κριμαίας — η ακτή της Κιρκασίας (Σότσι, Τουάψε, Μαϊκόπ) προσαρτήθηκε στο Χανάτο της Κριμαίας ως περιοχή χαλαρής προστασίας", "e99eb8e8"], "d": ["Μετά από τετραήμερη πολιορκία η Κάφα παραδόθηκε στον Αχμέτ Πασά και ο Μενγκλί Γκιράι δέχτηκε την υποτέλεια στον Οθωμανό σουλτάνο. Η περιοχή του Σότσι, του Τουάψε και του Μαϊκόπ, πατρίδα των κιρκασιανών φυλών που αναγνώριζαν τους χάνους της Κριμαίας ως επικυρίαρχους, στον άτλαντα από αυτή την ημερομηνία εμφανίζεται δεμένη με το Χανάτο της Κριμαίας ως χαλαρή προστασία.", "63b788a5"]},
"OLAYLAR_2S1019:1500-01-01:0":{"b": ["Η Μόσχα πήρε το Μπριάνσκ από το Μεγάλο Δουκάτο της Λιθουανίας", "fb1c3a61"], "d": ["Στον πόλεμο Μόσχας-Λιθουανίας του 1500-1503 ο ρωσικός στρατός κατέλαβε το Μπριάνσκ και η πόλη προσαρτήθηκε στο κράτος της Μόσχας· η ανακωχή του 1503 αναγνώρισε αυτό το κέρδος.", "8e507991"]},
"OLAYLAR_2S1019:1500-04-12:0":{"b": ["Ο τελευταίος κόμης του Görz Leonhard πέθανε — το Lienz και η κοιλάδα Puster πέρασαν στην Αυστρία των Αψβούργων (Τιρόλο)", "93331339"], "d": ["Ο Leonhard, ο τελευταίος εκπρόσωπος των κομήτων του Görz (Gorizia), πέθανε στις 12 Απριλίου 1500 στο Lienz. Σύμφωνα με προϋπάρχουσα συμφωνία διαδοχής, η προ-κομητεία που περιλάμβανε το Lienz και την κοιλάδα Puster πέρασε στον Μαξιμιλιανό Α΄ και προσαρτήθηκε στο Τιρόλο.", "996079fc"]},
"OLAYLAR_2S1019:1516-08-24:0":{"b": ["Ο Μπιγιίκλι Μεχμέτ Πασάς πήρε από τους Σαφαβίδες τη Μοσούλη, το Σιντζάρ και την Ιμαντίγιε", "3039d6af"], "d": ["Ο Μπιγιίκλι Μεχμέτ Πασάς, που νίκησε τον Κάρα Χαν στο Κοτσχισάρ, ενώ πολιορκούσε το Μαρντίν, πήρε από τους Σαφαβίδες τα γύρω κάστρα: καταλήφθηκαν η Μοσούλη, η Ρούχα, το Μπιρετζίκ και το Σιντζάρ, η Ιμαντίγιε και οι άλλοι Κούρδοι άρχοντες δέχτηκαν την οθωμανική υποτέλεια. Το κάστρο του Μαρντίν θα παραλαμβανόταν μετά την επιστροφή του Πασά από το Μερτζ Νταμπίκ.", "0ce2275b"]},
"OLAYLAR_2S1019:1523-06-06:0":{"b": ["Ο Γουσταύος Βάσα εξελέγη βασιλιάς στο Strängnäs — το Βασίλειο της Σουηδίας αποχωρίστηκε από την Ένωση του Κάλμαρ", "a6e95f4c"], "d": ["Ο Gustav Eriksson Vasa, που εξεγέρθηκε κατά του βασιλιά της Δανίας Β΄ Χριστιανού μετά το Λουτρό Αίματος της Στοκχόλμης (1520), εξελέγη βασιλιάς στις 6 Ιουνίου 1523 στο σουηδικό Riksdag που συνήλθε τον Μάιο του 1523 στο Strängnäs. Η Σουηδία και η εξαρτημένη από αυτήν Φινλανδία έτσι βγήκαν οριστικά από την Ένωση του Κάλμαρ που διαρκούσε από το 1397 και άρχισε η περίοδος των Βάσα του ανεξάρτητου Βασιλείου της Σουηδίας.", "64dcc4c4"]},
"OLAYLAR_2S1019:1526-12-05:0":{"b": ["Οι τάξεις της Σιλεσίας αναγνώρισαν τον Φερδινάνδο Α΄ ως βασιλιά — η Σιλεσία πέρασε στην Αυστρία των Αψβούργων", "a28e10c2"], "d": ["Τον Αψβούργο Φερδινάνδο, που εξελέγη τον Οκτώβριο του 1526 στο στέμμα της Βοημίας που χήρεψε με τον θάνατο του Β΄ Λάγιος στο Μοχάτς, οι τάξεις της Άνω και Κάτω Σιλεσίας στη γενική συνέλευση, με τον όρο της επιβεβαίωσης των προνομίων τους, τον αναγνώρισαν στις 5 Δεκεμβρίου 1526 ως βασιλιά και τη σύζυγό του Άννα ως βασίλισσα. Τα δουκάτα της Σιλεσίας έτσι μπήκαν μαζί με το στέμμα της Βοημίας στη διοίκηση των Αψβούργων.", "bc2a3ff9"]},
"OLAYLAR_2S1019:1550-06-12:0":{"b": ["Ο βασιλιάς της Σουηδίας Γουσταύος Βάσα ίδρυσε το Ελσίνκι", "43468b54"], "d": ["Ο βασιλιάς της Σουηδίας Gustav Vasa το 1550 έβαλε να ιδρυθεί στις εκβολές του ποταμού Vantaa το Ελσίνκι ως νέα εμπορική πόλη, ώστε να ανταγωνίζεται το Reval (Ταλίν) στο εμπόριο της Βαλτικής. Η πόλη το 1640 μεταφέρθηκε στη σημερινή της θέση, προς τη θάλασσα.", "eb67b9f0"]},
"OLAYLAR_2S1019:1633-01-01:0":{"b": ["Ο ιμάμης των Γιαρουμπιδών του Ομάν Νασίρ μπ. Μουρσίντ πήρε το Τζουλφάρ από τους Πορτογάλους", "6ca9fb0c"], "d": ["Οι Πορτογάλοι, που κρατούσαν το Τζουλφάρ ακόμη και μετά την πτώση του Ορμούζ το 1622, εκδιώχθηκαν από την περιοχή με την κατάληψη του ιμάμη των Γιαρουμπιδών του Ομάν Νασίρ μπ. Μουρσίντ το 1633.", "55e774dd"]},
"OLAYLAR_2S1019:1686-09-30:0":{"b": ["Απώλεια του κάστρου Sinj στη Βενετία — εσωτερικό της Δαλματίας", "3af8e103"], "d": ["Κατά τον Πόλεμο του Μοριά, οι βενετικές δυνάμεις το 1686 πήραν από τους Οθωμανούς το κάστρο Sinj στο εσωτερικό της Δαλματίας· το κάστρο άντεξε και στην οθωμανική πολιορκία του 1715 και έμεινε στη Βενετία.", "9c5c08b5"]},
"OLAYLAR_2S1019:1687-09-06:0":{"b": ["Το Varadin και η Bač πέρασαν στο Βασίλειο της Ουγγαρίας (Στέμμα των Αψβούργων) — αποχώρηση από τη Bačka μετά τη Χαρσάν", "6bc2b1ac"], "d": ["Ο στρατός του Σαρί Σουλεϊμάν Πασά, που αποσύρθηκε από την ήττα της Χαρσάν, πέρασε στις 1 Σεπτεμβρίου 1687 από το Varadin και άφησε το κάστρο στον Τζαφέρ Πασά· λίγο αργότερα το Varadin και η Bač στη Bačka περιήλθαν στα χέρια των συμμαχικών αψβουργικών δυνάμεων. Όταν στο Κάρλοβιτς ο Σάβας έγινε σύνορο, το Varadin έμεινε στην αυστριακή πλευρά.", "5ba42bd5"]},
"OLAYLAR_2S1019:1687-09-26:0":{"b": ["Το Όσιεκ πέρασε στο Βασίλειο της Ουγγαρίας (Στέμμα των Αψβούργων) — άρχισε η απώλεια της Σλαβονίας", "7af97ffe"], "d": ["Μετά την ήττα της Χαρσάν, το φρούριο-γέφυρα του Όσιεκ στον Δράβο πέρασε στις 26 Σεπτεμβρίου 1687 στις αψβουργικές δυνάμεις. Η οθωμανική στρατιωτική παρουσία και ο τουρκικός πληθυσμός στη Σλαβονία αποσύρθηκαν σταδιακά μεταξύ 1686-1688· η περιοχή μπήκε στη διοίκηση των Αψβούργων.", "ae45a854"]},
"OLAYLAR_2S1019:1687-09-30:0":{"b": ["Απώλεια του Herceg Novi στη Βενετία — είσοδος του κόλπου του Κότορ", "b88046d8"], "d": ["Κατά τον Πόλεμο του Μοριά, ο βενετικός στόλος και οι σύμμαχοί του το 1687 πολιόρκησαν και κατέλαβαν το κάστρο Herceg Novi στην είσοδο του κόλπου του Κότορ· η πόλη έμεινε στη Βενετία μέχρι την κατάλυση της Βενετικής Δημοκρατίας το 1797.", "aae8f2d8"]},
"OLAYLAR_2S1019:1794-06-15:0":{"b": ["Η Κορσική συνδέθηκε με το βρετανικό στέμμα — Αγγλοκορσικό Βασίλειο", "10f18bde"], "d": ["Ο Paoli, που εξεγέρθηκε κατά της Επαναστατικής Γαλλίας, με την υποστήριξη του βρετανικού στόλου καθάρισε το νησί από τις γαλλικές φρουρές· στη consulta που συνήλθε στην Corte εγκρίθηκε σύνταγμα που συνέδεε την Κορσική με τον βασιλιά της Αγγλίας. Το νησί παρέμεινε για δύο χρόνια ως Αγγλοκορσικό Βασίλειο υπό τη διοίκηση του Βρετανού γενικού κυβερνήτη Gilbert Elliot.", "bdf0e618"]},
"OLAYLAR_2S1019:1796-10-01:0":{"b": ["Εκκένωση της Κορσικής από τους Βρετανούς — το νησί ξανά της Γαλλίας", "c9f986fe"], "d": ["Η Βρετανία, που βρέθηκε σε δύσκολη θέση στη Μεσόγειο με τις νίκες του Βοναπάρτη στην Ιταλία και τη στροφή της Ισπανίας στο πλευρό της Γαλλίας, εκκένωσε την Κορσική. Το Αγγλοκορσικό Βασίλειο έληξε και το νησί συνδέθηκε ξανά με τη Γαλλία.", "0338523e"]},
"OLAYLAR_2S1019:1878-09-18:0":{"b": ["Ο αυστροουγγρικός στρατός έσπασε την αντίσταση και κατέλαβε το Bihać", "ffec53e0"], "d": ["Η Αυστροουγγαρία, που με τη Συνθήκη του Βερολίνου έλαβε το δικαίωμα κατάληψης της Βοσνίας-Ερζεγοβίνης, συνάντησε στο Bihać την αντίσταση των ντόπιων μουσουλμάνων. Οι δυνάμεις υπό τον στρατηγό Wilhelm von Reinländer κατέλαβαν την πόλη στις 18 Σεπτεμβρίου 1878· και η φρουρά του Ostrovica στην κοιλάδα του Una βγήκε από οθωμανικά χέρια με την ίδια επιχείρηση.", "207d2a2b"]},
"OLAYLAR_2S1019:1903-03-15:0":{"b": ["Οι Βρετανοί κατέλαβαν το Σοκότο — το Χαλιφάτο του Σοκότο έχασε την πρωτεύουσά του", "e744f986"], "d": ["Ο Lugard, διοικητής της Βρετανίας που ανακήρυξε το 1900 αποικία τη Βόρεια Νιγηρία, αφού κατέλαβε τα εμιράτα ένα-ένα, υπέβαλε τον στρατό του Σοκότο σε βαριά ήττα και στις 15 Μαρτίου 1903 κατέλαβε την πρωτεύουσα. Με τη δολοφονία του χαλίφη Ταχίρ, που διέφυγε, τον Ιούλιο στο Μπούρμι, η πολιτική κυριαρχία του χαλιφάτου έληξε.", "fe9507bb"]},
"OLAYLAR_2S1019:1906-04-13:0":{"b": ["Ο Ιμπν Σαούντ νίκησε τον εμίρη των Ρασιντιδών — το Κασίμ πέρασε από το Εμιράτο των Σαμμάρ στους Σαουδίδες", "a32201dd"], "d": ["Ο Αμπντουλαζίζ μπ. Σαούντ, που ανακατέλαβε το Ριάντ το 1902, στις 13 Απριλίου 1906 νίκησε και σκότωσε τον εμίρη των Ρασιντιδών Αμπντουλαζίζ μπ. Μουτ'ίμπ. Μετά από αυτή τη μάχη κατέλαβε την περιοχή του Κασίμ (Μπουρεϊντά, Ουνεϊζά)· οι Ρασιντίδες από τότε βασίλευαν μόνο στο Χαΐλ και τα περίχωρα.", "c99fc129"]},
"OLAYLAR_2S1019:1915-06-10:0":{"b": ["Το νησί Καμαράν καταλήφθηκε από τους Βρετανούς", "c514bb66"], "d": ["Το νησί Καμαράν στην ακτή της Υεμένης στην Ερυθρά Θάλασσα καταλήφθηκε το 1915 από τους Βρετανούς κατά τον Α΄ Παγκόσμιο Πόλεμο και άρχισε να διοικείται από το Άντεν.", "33e76176"]},
"OLAYLAR_2S1019:1918-09-21:0":{"b": ["Κατάληψη της Ναμπλούς από τους Βρετανούς — κατάρρευση του μετώπου της Παλαιστίνης", "b5e85950"], "d": ["Τον Σεπτέμβριο του 1918 η μεγάλη επίθεση του Allenby στο μέτωπο της Παλαιστίνης διέλυσε την 7η και 8η οθωμανική στρατιά· η Ναμπλούς πέρασε στα χέρια των Βρετανών και η τετρακοσιετής οθωμανική κυριαρχία στην πόλη έληξε. Η πόλη έμεινε υπό βρετανική στρατιωτική διοίκηση μέχρι το 1920.", "d3195be1"]},
"OLAYLAR_2S1019:1918-11-08:0":{"b": ["Είσοδος των Βρετανών στη Μοσούλη — κατάληψη του βιλαετίου της Μοσούλης κατά παράβαση της ανακωχής", "ed5e8e33"], "d": ["Όταν υπογράφηκε η Ανακωχή του Μούδρου, η Μοσούλη βρισκόταν στα χέρια των τουρκικών δυνάμεων. Οι Βρετανοί, στηριζόμενοι στο 7ο άρθρο της ανακωχής, μπήκαν στην πόλη στις 8 (ή 10) Νοεμβρίου 1918 και στις 15 Νοεμβρίου οι τουρκικές μονάδες αναγκάστηκαν να αποσυρθούν από το βιλαέτι. Το ζήτημα της Μοσούλης δεν λύθηκε ούτε στη Λωζάνη και έμεινε για τη Συνθήκη της Άγκυρας του 1926.", "168f5310"]},
"OLAYLAR_2S1114D5:1923-07-24:0":{"b": ["Συνθήκη της Λωζάνης — η Πάτμος αφέθηκε στην Ιταλία, επιβεβαιώθηκε η ελληνική κυριαρχία στα νησιά του Αιγαίου", "185960b3"], "d": ["Με το άρθρο 15 της Λωζάνης η Τουρκία παραιτήθηκε υπέρ της Ιταλίας από όλα τα δικαιώματα και τους τίτλους της στα Δωδεκάνησα, συμπεριλαμβανομένης της Πάτμου (Μπατνός)· τα νησιά βρίσκονταν από το 1912 υπό ιταλική κατοχή. Το άρθρο 12 επιβεβαίωσε την ελληνική κυριαρχία στη Λήμνο, τη Σαμοθράκη, τη Μυτιλήνη, τη Χίο, τη Σάμο και την Ικαρία. Οι Ψαρά (Αγ. Στράτης) και οι Φούρνοι ήταν από το 1912 στα ελληνικά χέρια και παρέμειναν στην Ελλάδα και μετά τη Λωζάνη· τα ίδια αυτά δύο ονόματα δεν αναφέρονται στο άρθρο 12 της Λωζάνης.", "73a0b71c"]},
"OLAYLAR_2S1114D5:1935-12-25:0":{"b": ["Νόμος του Τουντζελί — αντί για το σαντζάκι του Ντέρσιμ ιδρύθηκε το βιλαέτι του Τουντζελί (κέντρο Καλάν)", "1ae9ad50"], "d": ["Με τον νόμο αρ. 2885 αποφασίστηκε η ίδρυση στην περιοχή του Ντέρσιμ ενός νέου βιλαετίου με το όνομα Τουντζελί· διοικητικό κέντρο του βιλαετίου έγινε ο οικισμός Καλάν και ο οικισμός αργότερα πήρε το όνομα Τουντζελί. Η περιοχή παρέμεινε εντός της Τουρκικής Δημοκρατίας· αυτό που άλλαξε είναι το διοικητικό καθεστώς και το όνομα.", "7970d4ac"]},
"OLAYLAR_2S1114D5:1956-03-02:0":{"b": ["Ανεξαρτησία του Μαρόκου: η γαλλική προστασία έληξε, το Σαλέ και το Ραμπάτ έμειναν στο Βασίλειο του Μαρόκου", "a62a3fdb"], "d": ["Με τη συνθήκη ανεξαρτησίας που υπογράφηκε στις 2 Μαρτίου 1956 η γαλλική προστασία που διαρκούσε από το 1912 έληξε· το Σαλέ και το Ραμπάτ έγιναν έδαφος του ανεξάρτητου Βασιλείου του Μαρόκου. Η Ισπανία αναγνώρισε την ανεξαρτησία του Μαρόκου στις 5 Απριλίου 1956.", "e888afb6"]},
"OLAYLAR_2S1114D5:1980-07-30:0":{"b": ["Τα Νέα Εβρίδες έγιναν ανεξάρτητα: ιδρύθηκε η Δημοκρατία του Βανουάτου", "cc93330f"], "d": ["Το Κοινοκτημόνιο των Νέων Εβρίδων, υπό κοινή κυριαρχία Γαλλίας και Ηνωμένου Βασιλείου, έγινε στις 30 Ιουλίου 1980 ανεξάρτητο με το όνομα Βανουάτου. Η πρωτεύουσα Πορτ Βίλα στο νησί Εφατέ και ο οικισμός Teouma πέρασαν από τη διοίκηση του κοινοκτημονίου στο Βανουάτου.", "29b000d6"]},
"OLAYLAR_2S1114D5:1994-03-01:0":{"b": ["Η Νότια Αφρική παρέδωσε τον Κόλπο Walvis (Walvis Bay) στη Ναμίμπια", "96bb0184"], "d": ["Η Δημοκρατία της Νότιας Αφρικής την 1η Μαρτίου 1994 παρέδωσε το λιμάνι του Κόλπου Walvis και τα δώδεκα νησιά ανοιχτά στην κυβέρνηση της Ναμίμπια· ο ογδονταετής νοτιοαφρικανικός έλεγχος έληξε.", "fdd93117"]},
"OLAYLAR_ALM1115B:1024-09-08:0":{"b": ["Ο Κονράδος Β' εκλέχθηκε βασιλιάς των Γερμανών και στέφθηκε στη Mainz — ξεκίνησε η δυναστεία των Salier", "c88123e8"], "d": ["Μετά τον θάνατο του Ερρίκου Β', οι Γερμανοί πρίγκιπες συνήλθαν στις 4 Σεπτεμβρίου 1024 στο Kamba, στη δεξιά όχθη του Ρήνου· την εκλογή διηύθυνε ο αρχιεπίσκοπος της Mainz Aribo. Ο Κονράδος ο Πρεσβύτερος νίκησε τον ανιψιό του τον Νεότερο και στη γιορτή της Γέννησης της Θεοτόκου (8 Σεπτεμβρίου) στέφθηκε βασιλιάς από τον Aribo στη Mainz.", "1d5ce932"]},
"OLAYLAR_ALM1115B:1039-06-04:0":{"b": ["Ο αυτοκράτορας Κονράδος Β' πέθανε στην Utrecht", "f967406b"], "d": ["Ο Κονράδος Β', ο πρώτος αυτοκράτορας της δυναστείας των Salier, πέθανε στις 4 Ιουνίου 1039 στην Utrecht μετά από σύντομη και οδυνηρή ασθένεια.", "6af4f169"]},
"OLAYLAR_ALM1115B:1122-09-23:0":{"b": ["Κονκορδάτο της Worms — η διαμάχη των επενδύσεων (investitur) έληξε", "8073e4a0"], "d": ["Η ειρήνη ανάμεσα στον αυτοκράτορα Ερρίκο Ε' και τον πάπα Καλλιξτο Β', με τη μεσολάβηση της παπικής αποστολής, ανακηρύχθηκε στις 23 Σεπτεμβρίου 1122 στη Worms (στο Lobwiesen, ακριβώς δίπλα στην πόλη). Ο Ερρίκος παραιτήθηκε από την επένδυση με δαχτυλίδι και ράβδο και αποδέχθηκε την κανονική εκλογή επισκόπων και ηγουμένων.", "a915c2e7"]},
"OLAYLAR_ALM1115B:1125-05-23:0":{"b": ["Ο αυτοκράτορας Ερρίκος Ε' πέθανε στην Utrecht", "790cadc4"], "d": ["Ο αυτοκράτορας Ερρίκος Ε' πέθανε στις 23 Μαΐου 1125 στην Utrecht· αναφέρεται ως ο αυτοκράτορας του Κονκορδάτου της Worms (1122).", "8402ca28"]},
"OLAYLAR_ALM1115B:1152-03-05:0":{"b": ["Ο Φρειδερίκος Α' Βαρβαρόσα εκλέχθηκε βασιλιάς των Γερμανών στη Φρανκφούρτη", "b91f29a3"], "d": ["Οι πρίγκιπες ανέβασαν τον Φρειδερίκο στο βασίλειο στις 5 Μαρτίου 1152 στη Φρανκφούρτη· στέφθηκε στο Aachen στις 9 Μαρτίου. Έτσι ξεκίνησε η περίοδος του Βαρβαρόσα της δυναστείας των Hohenstaufen.", "26fcdb8c"]},
"OLAYLAR_ALM1115B:1156-09-17:0":{"b": ["Privilegium Minus — η Αυστρία έγινε δουκάτο, η Βαυαρία δόθηκε στον Ερρίκο τον Λέοντα", "a64c125b"], "d": ["Με απόφαση των πριγκίπων στο Regensburg, η Αυστρία αναβαθμίστηκε σε δουκάτο και στον Heinrich Jasomirgott αναγνωρίστηκαν ειδικά δικαιώματα· στην ίδια ρύθμιση ο Heinrich επέστρεψε τη Βαυαρία στον αυτοκράτορα και ο αυτοκράτορας έδωσε τη Βαυαρία ως φέουδο στον Ερρίκο τον Λέοντα.", "fe899d87"]},
"OLAYLAR_ALM1115B:1218-01-01:0":{"b": ["Με το σβήσιμο της γενιάς των Zähringen η Βέρνη έγινε ελεύθερη αυτοκρατορική πόλη", "1473c219"], "d": ["Όταν η δυναστεία των Zähringen έσβησε το 1218, η Βέρνη έγινε ελεύθερη πόλη άμεσα εξαρτημένη από την αυτοκρατορία· το 1353 μπήκε στην Ελβετική Συνομοσπονδία ως όγδοο μέλος.", "8bbdceab"]},
"OLAYLAR_ALM1115B:1264-01-01:0":{"b": ["Landgraviate της Έσσης: ο Ερρίκος Α' του Brabant έγινε ο πρώτος landgrave της Έσσης, ειρήνη με το Meißen 1264", "57067f04"], "d": ["Η ιστορία της Έσσης ως ανεξάρτητης χώρας ξεκινά με τον Ερρίκο Α' («το Παιδί»)· η ειρήνη με το Meißen έγινε το 1264. Ο Ερρίκος έχτισε φρούριο στο Kassel και αυτό έγινε τα επόμενα χρόνια η συνήθης κατοικία του· το 1292 έγινε δεκτός στην αυτοκρατορική ηγεμονία (Reichsfürstenstand).", "43d237e5"]},
"OLAYLAR_ALM1115B:1358-12-01:0":{"b": ["Η Κομητεία του Schwerin πέρασε με συμφωνία στον δούκα του Mecklenburg Albrecht Β'", "013b6860"], "d": ["Ο Albrecht Β', με σύμβαση της 1ης Δεκεμβρίου 1358, πληρώνοντας στον κόμη Nicolaus 10.000 μάρκα αργύρου, πήρε την Κομητεία του Schwerin· η πόλη από τότε έγινε έδαφος του δουκάτου του Mecklenburg (η εδραίωσή της ως πρωτεύουσας ωστόσο παγιώθηκε τον 16ο αιώνα).", "1d69a777"]},
"OLAYLAR_ALM1115B:1567-03-31:0":{"b": ["Ο landgrave Φίλιππος ο «Μεγαλόψυχος» πέθανε στο Kassel — η Έσση διαιρέθηκε ανάμεσα στους τέσσερις γιους του", "c0cb27ed"], "d": ["Ο landgrave της Έσσης Φίλιππος Α', ένας από τους πολιτικούς ηγέτες της Μεταρρύθμισης, πέθανε στο Kassel στις 31 Μαρτίου 1567. Σύμφωνα με τη διαθήκη του 1562, η χώρα μοιράστηκε στους τέσσερις γιους του ως Έσση-Kassel (Wilhelm Δ'), Έσση-Marburg (Ludwig Δ'), Έσση-Rheinfels (Philipp Β') και Έσση-Darmstadt (Georg)· έτσι έληξε το ενιαίο Landgraviate της Έσσης.", "288ab83b"]},
"OLAYLAR_ALM1115B:1637-03-10:0":{"b": ["Ο τελευταίος δούκας της Πομερανίας Bogislaw ΙΔ' πέθανε στο Stettin — η δυναστεία των Griffin έληξε", "ab96746a"], "d": ["Ο τελευταίος δούκας της Πομερανίας Bogislaw ΙΔ' πέθανε στις 10 Μαρτίου 1637 στο Stettin και μαζί του έσβησε η ντόπια πομερανική δυναστεία. Η πραγματική διανομή του δουκάτου (Βρανδεμβούργο-Σουηδία) επικυρώθηκε με την Ειρήνη της Βεστφαλίας του 1648.", "2e5f6d25"]},
"OLAYLAR_ALM1115B:1646-01-01:0":{"b": ["Ο Φερδινάνδος Γ΄ έδωσε στη Βρέμη τα προνόμια της ελεύθερης αυτοκρατορικής πόλης", "174142ee"], "d": ["Ο αυτοκράτορας Φερδινάνδος Γ΄ το 1646 αναγνώρισε στη Βρέμη τα προνόμια της ελεύθερης αυτοκρατορικής πόλης· η Σουηδία αντιτάχθηκε σε αυτό και το 1666 προσπάθησε να υποτάξει την πόλη με τα όπλα και απέτυχε. Όταν ο εκλέκτορας του Ανόβερου πήρε την αρχιεπισκοπή (1720), αναγνώρισε τη Βρέμη ως ελεύθερη πόλη.", "4a574693"]},
"OLAYLAR_ALM1115B:1810-01-01:0":{"b": ["Η Βρέμη προσαρτήθηκε στη Γαλλική Αυτοκρατορία — έγινε κέντρο του νομού των Εκβολών του Βέζερ", "d5d149ae"], "d": ["Η Βρέμη είχε καταληφθεί το 1806 από τους Γάλλους και από το 1810 έως το 1813 ήταν κέντρο του νομού των Εκβολών του Βέζερ (Bouches-du-Weser).", "0ac80a63"]},
"OLAYLAR_ALM1115B:1810-12-01:0":{"b": ["Ο Ναπολέων προσάρτησε το Λύμπεκ στη Γαλλική Αυτοκρατορία", "1ca78afe"], "d": ["Μετά την παράδοση του Blücher κοντά στο Λύμπεκ τον Νοέμβριο του 1806, η πόλη λεηλατήθηκε από τους Γάλλους και τον Δεκέμβριο του 1810 ο Ναπολέων προσάρτησε την πόλη στην αυτοκρατορία του. Το Λύμπεκ μέχρι αυτή την ημερομηνία ήταν ελεύθερη αυτοκρατορική πόλη από το 1226.", "b7bf744b"]},
"OLAYLAR_ALM1115B:1813-01-01:0":{"b": ["Το Λύμπεκ εξεγέρθηκε κατά της γαλλικής κυριαρχίας και ανέκτησε το καθεστώς της ελεύθερης πόλης", "84e70d49"], "d": ["Το Λύμπεκ, που εξεγέρθηκε το 1813 κατά της γαλλικής διοίκησης, αναγνωρίστηκε το 1815 από το Συνέδριο της Βιέννης ως ελεύθερη και ανσεατική πόλη της Γερμανικής Συνομοσπονδίας.", "f5432e01"]},
"OLAYLAR_ALM1115B:1813-01-01:1":{"b": ["Η γαλλική κυριαρχία έληξε — η Βρέμη ανέκτησε το καθεστώς ελεύθερης πόλης", "4afa71be"], "d": ["Η παραμονή της Βρέμης υπό γαλλική διοίκηση ως έδρα του διαμερίσματος των Εκβολών του Weser έληξε το 1813· η πόλη το 1815 αποκαταστάθηκε στην ανεξαρτησία της από το Συνέδριο της Βιέννης και προσχώρησε στη Γερμανική Συνομοσπονδία.", "b4e1a2ef"]},
"OLAYLAR_ALM1115B:1815-01-01:0":{"b": ["Το δουκάτο του Mecklenburg-Schwerin πήρε τον τίτλο του μεγάλου δουκάτου", "3f5d05eb"], "d": ["Ο δούκας του Mecklenburg-Schwerin Friedrich Franz Α' πήρε το 1815 τον τίτλο του μεγάλου δουκάτου («großherzogliche Würde»)· το δελτίο του δουκάτου του Mecklenburg (1348-1815) λήγει σε αυτό το σημείο, η χώρα συνεχίζει ως μεγάλο δουκάτο στο πλαίσιο της Γερμανικής Συνομοσπονδίας.", "bfbe2246"]},
"OLAYLAR_ALM1115B:1937-04-01:0":{"b": ["Ο Νόμος του Μεγάλου Αμβούργου τέθηκε σε ισχύ — το καθεστώς του Λύμπεκ ως ανεξάρτητου κρατιδίου έληξε", "6df2f92a"], "d": ["Ο Νόμος του Μεγάλου Αμβούργου, που εκδόθηκε στις 26 Ιανουαρίου 1937, τέθηκε σε ισχύ την 1η Απριλίου 1937· το Λύμπεκ έχασε την αυτονομία του που διαρκούσε πάνω από 700 χρόνια και προσαρτήθηκε στο πρωσικό κρατίδιο του Σλέσβιχ-Χολστάιν, τα σύνορα του Αμβούργου διευρύνθηκαν.", "b96594d2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0014-01-01:0":{"b": ["Η Ραιτία και το Νωρικό προσαρτήθηκαν στη Ρώμη: ο Τιβέριος και ο Δρούσος κατέλαβαν τη χώρα πέρα από τις Άλπεις", "be6f2a15"], "d": ["Το 15 π.Χ. ο Τιβέριος και ο Δρούσος νίκησαν τις αλπικές φυλές και ολοκλήρωσαν τη Ραιτία (και την προσάρτηση του Νωρικού)· η άνω όχθη του Δούναβη έγινε ρωμαϊκό σύνορο.", "b564c899"]},
"OLAYLAR_ANTIK_AKDENIZ:-0024-01-01:0":{"b": ["Με τον θάνατο του Αμύντα η Γαλατία έγινε ρωμαϊκή επαρχία", "e4250ad7"], "d": ["Όταν ο Γαλάτης βασιλιάς Αμύντας, που είχε διορίσει ο Αντώνιος, σκοτώθηκε στην Κιλικία (25 π.Χ.), ο Αύγουστος μετέτρεψε τη Γαλατία σε ρωμαϊκή επαρχία και την ένωσε με την Πισιδία και τη Λυκαονία. Πρωτεύουσα έγινε η Άγκυρα (Άγκυρα)· η επιγραφή Res Gestae του Αυγούστου (Monumentum Ancyranum) γράφτηκε εδώ.", "d9e5074f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0026-01-16:0":{"b": ["Ο Οκταβιανός πήρε τον τίτλο «Augustus»: άρχισε η περίοδος του Principatus (αυτοκρατορία)", "310297b6"], "d": ["Στις 16 Ιανουαρίου του 27 η Σύγκλητος έδωσε στον Οκταβιανό τον τίτλο Augustus· ο Οκταβιανός ανέλαβε για μακρά διάρκεια τη διοίκηση (imperium) του μεγαλύτερου μέρους των επαρχιών. Η ημερομηνία αυτή θεωρείται η αρχή της Ρωμαϊκής Αυτοκρατορίας.", "6a533271"]},
"OLAYLAR_ANTIK_AKDENIZ:-0032-01-01:0":{"b": ["Ο Β΄ Βόκχος πέθανε· η Μαυριτανία περιήλθε στον έλεγχο του Οκταβιανού", "414fa36c"], "d": ["Όταν ο Β΄ Βόκχος πέθανε χωρίς παιδιά το 33, η Μαυριτανία, με την κληρονομιά του Οκταβιανού με διαθήκη, μπήκε στη ρωμαϊκή διοίκηση· παρέμεινε για ένα διάστημα υπό άμεση ρωμαϊκή διοίκηση και το 25 δόθηκε στον Ιόβα Β΄.", "ab445b2d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0035-01-01:0":{"b": ["Ο Αντώνιος έκανε τον Αρχέλαο βασιλιά της Καππαδοκίας", "1e83e691"], "d": ["Ο Αντώνιος, αναδιοργανώνοντας την Ανατολή, έδωσε τον θρόνο της Καππαδοκίας στον Αρχέλαο· ο Αρχέλαος κυβέρνησε μέχρι που τον κάλεσε στη Ρώμη ο Τιβέριος το 17 μ.Χ. Η Καππαδοκία έγινε ρωμαϊκή επαρχία το 17 μ.Χ. (το γεγονός αυτό είναι ξεχωριστό λήμμα στη χρονολογία).", "cdb79213"]},
"OLAYLAR_ANTIK_AKDENIZ:-0041-01-01:0":{"b": ["Φίλιπποι: ο Οκταβιανός και ο Αντώνιος νίκησαν τον Βρούτο και τον Κάσσιο", "4386016f"], "d": ["Τον Οκτώβριο του 42 έγιναν δύο ξεχωριστές μάχες κοντά στους Φιλίππους· ο Κάσσιος και ο Βρούτος αυτοκτόνησαν και η δημοκρατική δύναμη εξαλείφθηκε. Οι τριάρχες μοίρασαν μεταξύ τους τον ρωμαϊκό κόσμο.", "ee38e78c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0043-01-01:0":{"b": ["Ο Ιούλιος Καίσαρας έβαλε να ξαναϊδρυθεί η Κόρινθος ως ρωμαϊκή αποικία", "283a5daa"], "d": ["Λίγο πριν από τη δολοφονία του Καίσαρα εγκαταστάθηκαν στην Κόρινθο άποικοι Ρωμαίοι πολίτες (οι περισσότεροι απελεύθεροι)· η πόλη έγινε ένα από τα σημαντικά κέντρα της ρωμαϊκής επαρχίας Αχαΐας. Η απόφαση για την επανίδρυση χρονολογείται το 44 π.Χ., ο εποικισμός το 44/43 π.Χ.", "237b35af"]},
"OLAYLAR_ANTIK_AKDENIZ:-0043-01-01:1":{"b": ["Ο Μπουρεμπίστας έπεσε θύμα δολοφονίας: το βασίλειο των Δακών κατακερματίστηκε", "9b9edb14"], "d": ["Ο Στράβων γράφει ότι ο Μπουρεμπίστας σκοτώθηκε με εσωτερικό πραξικόπημα πριν από τον θάνατο του Καίσαρα και ότι το βασίλειο διαιρέθηκε σε πέντε και έπειτα σε τέσσερα τμήματα. Η ένωση της Δακίας δεν μπόρεσε να ξαναδημιουργηθεί μέχρι τον Δεκέβαλο (87 μ.Χ.).", "eaa97397"]},
"OLAYLAR_ANTIK_AKDENIZ:-0043-03-15:0":{"b": ["Ο Καίσαρας δολοφονήθηκε στη Σύγκλητο τις Ειδούς του Μαρτίου (15 Μαρτίου)", "18649074"], "d": ["Ο Καίσαρας, που ανακηρύχθηκε διαρκής δικτάτορας, στις 15 Μαρτίου του 44 μαχαιρώθηκε στη συνεδρίαση της Συγκλήτου στο Θέατρο του Πομπηίου από μια ομάδα συγκλητικών. Ο θάνατός του προετοίμασε το έδαφος για νέους εμφυλίους και την εξουσία του Αυγούστου.", "4180e38f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0044-03-17:0":{"b": ["Μούντα: ο Καίσαρας νίκησε τους γιους του Πομπηίου", "e1e93362"], "d": ["Στις 17 Μαρτίου του 45 στη Μούντα ο Καίσαρας νίκησε τον στρατό του Γναίου Πομπηίου και του Σέξτου Πομπηίου· η Ισπανία παρέμεινε στα χέρια του Καίσαρα. Είναι η τελευταία μεγάλη μάχη του εμφυλίου πολέμου.", "67dd7b63"]},
"OLAYLAR_ANTIK_AKDENIZ:-0045-01-01:0":{"b": ["Θάψος: ο Καίσαρας νίκησε τον Ιόβα Α΄· η Ανατολική Νουμιδία έγινε επαρχία Africa Nova", "77b28c50"], "d": ["Ο Καίσαρας την άνοιξη του 46 διέλυσε στη Θάψο τον στρατό του Σκιπίωνα και του Ιόβα Α΄· ο Ιόβας αυτοκτόνησε. Το ανατολικό τμήμα της Νουμιδίας έγινε επαρχία Africa Nova που διοικούσε ο Σαλλούστιος, το δυτικό τμήμα δόθηκε στον Βόκχο και στον Σίττιο.", "a92567de"]},
"OLAYLAR_ANTIK_AKDENIZ:-0046-05-21:0":{"b": ["Ζήλα: ο Καίσαρας νίκησε τον Β΄ Φαρνάκη («veni vidi vici»)", "11bf082a"], "d": ["Ο Φαρνάκης Β΄, γιος του Μιθριδάτη, εκμεταλλευόμενος τον εμφύλιο προσπάθησε να ανακτήσει τον Πόντο· ο Καίσαρας το 47 τον νίκησε στη Ζήλα και αναδιοργάνωσε τον Πόντο υπό ρωμαϊκό έλεγχο. Ο Φαρνάκης διέφυγε στον Βόσπορο και πέθανε εκεί.", "8dc5a21a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0047-01-01:0":{"b": ["Φάρσαλος: ο Καίσαρας νίκησε τον Πομπήιο", "e821abe8"], "d": ["Ο Καίσαρας, μετά την υποχώρηση στο Δυρράχιο, διέλυσε στη Φάρσαλο τον μεγαλύτερο στρατό του Πομπηίου. Ο Πομπήιος διέφυγε στην Αίγυπτο και σκοτώθηκε· οι επαρχίες της Ανατολής άνοιξαν στον Καίσαρα.", "c606b7e2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0051-01-01:0":{"b": ["Αλεσία: ο Καίσαρας πολιόρκησε και νίκησε τον Βερκιγγετορίγα, η αντίσταση της Γαλατίας έσπασε", "d57cab9f"], "d": ["Η εξέγερση της Γαλατίας του 52 π.Χ. υπό τον Αρβέρνο Βερκιγγετορίγα καταστάλθηκε με την πολιορκία της Αλεσίας από τον Καίσαρα και την άμυνα της γραμμής πολιορκίας· ο Βερκιγγετορίξ παραδόθηκε. Η Γαλατία το επόμενο έτος μπήκε εξ ολοκλήρου υπό ρωμαϊκό έλεγχο.", "9e045798"]},
"OLAYLAR_ANTIK_AKDENIZ:-0057-01-01:0":{"b": ["Άρχισε η εκστρατεία του Καίσαρα στη Γαλατία: οι Ελβετοί ηττήθηκαν", "1e594bb3"], "d": ["Το 58 π.Χ. ο Καίσαρας, ως διοικητής της Κισαλπικής και Υπεραλπικής Γαλατίας, σταμάτησε τη μετανάστευση των Ελβετών κοντά στο Bibracte· στη συνέχεια νίκησε τους Γερμανούς του Αριόβιστου. Η εκστρατεία θα διαρκέσει οκτώ χρόνια και θα προσαρτήσει τη Γαλατία στη Ρώμη.", "b0789047"]},
"OLAYLAR_ANTIK_AKDENIZ:-0062-01-01:0":{"b": ["Ο Μιθριδάτης ΣΤ΄ πέθανε στο Παντικάπαιο· ο Βόσπορος έμεινε στον Φαρνάκη", "0831b871"], "d": ["Ο Μιθριδάτης, που διέφυγε από τον Πομπήιο, με την εξέγερση του γιου του Φαρνάκη αυτοκτόνησε στο κάστρο του Παντικαπαίου (63). Ο Φαρνάκης παρέδωσε τον Βόσπορο στον Πομπήιο και αναγνωρίστηκε ως φίλος βασιλιάς της Ρώμης.", "13030863"]},
"OLAYLAR_ANTIK_AKDENIZ:-0062-01-01:1":{"b": ["Ο Πομπήιος ένωσε τη Βιθυνία με τη δύση του Πόντου και ίδρυσε την επαρχία Bithynia et Pontus", "b2865ea8"], "d": ["Ο Πομπήιος στην αναδιάταξη της Ανατολής (65-63) ένωσε τη Βιθυνία με το δυτικό μισό του Πόντου και δημιούργησε την επαρχία Bithynia et Pontus· οι εσωτερικές περιοχές του Πόντου στα ανατολικά δόθηκαν σε τοπικούς πρίγκιπες.", "2c7b03c0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0063-01-01:0":{"b": ["Ο Πομπήιος αναγνώρισε την Κομμαγηνή ως φίλο και σύμμαχο της Ρώμης", "a48ba55c"], "d": ["Ο Πομπήιος στην αναδιάταξη της Ανατολής επικύρωσε το βασίλειο του Αντιόχου Α΄ και ένα τμήμα της περιοχής της Σελεύκειας (Ζεύγμα) και έκανε την Κομμαγηνή συμμαχικό ανάχωμα μεταξύ Ρώμης-Πάρθων. Το βασίλειο προσαρτήθηκε στη ρωμαϊκή επαρχία το 17 μ.Χ. και μόνιμα το 72 μ.Χ. (τα γεγονότα αυτά είναι ξεχωριστά λήμματα στη χρονολογία).", "47b7f8de"]},
"OLAYLAR_ANTIK_AKDENIZ:-0065-01-01:0":{"b": ["Ο Πομπήιος νίκησε τον Μιθριδάτη· ο Πόντος προσαρτήθηκε στη Ρώμη", "8f3f50a6"], "d": ["Ο Πομπήιος το 66 στην πεδιάδα του Λύκου διέλυσε τη νύχτα τον στρατό του Μιθριδάτη· ο Μιθριδάτης διέφυγε από την Κολχίδα στον Βόσπορο. Οι παράκτιες πόλεις του Πόντου μπήκαν στον έλεγχο της Ρώμης και το 63 δημιουργήθηκε η επαρχία που ενώθηκε με τη Βιθυνία.", "2e29932b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0069-01-01:0":{"b": ["Ο Αντίοχος Α΄ Θεός ανέβηκε στον θρόνο της Κομμαγηνής", "b1680d3f"], "d": ["Ο βασιλιάς της Κομμαγηνής Αντίοχος Α΄ έβαλε να χτιστεί το ταφικό ιερό στο όρος Νεμρούτ που ενώνει περσική και μακεδονική καταγωγή. Το βασίλειο βρισκόταν σε κατάσταση ανάχωματος μεταξύ Ρώμης και Πάρθων.", "c8db269f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0073-01-01:0":{"b": ["Η Κυρήνη έγινε ρωμαϊκή επαρχία (Κυρηναϊκή)", "f9993ffb"], "d": ["Είκοσι χρόνια μετά τη διαθήκη του Πτολεμαίου Απίωνα που άφησε το βασίλειό του στη Ρώμη (96), η Ρώμη έβαλε την Κυρηναϊκή στο καθεστώς επαρχίας· το 67 ενώθηκε με την Κρήτη.", "214aba0a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0073-01-01:1":{"b": ["Ο Νικομήδης Δ΄ άφησε με διαθήκη το βασίλειό του στη Ρώμη", "e29d9fbc"], "d": ["Με τον θάνατο του Νικομήδη Δ΄ (75/74) η Βιθυνία με διαθήκη αφέθηκε στον Ρωμαϊκό Λαό· ο Μιθριδάτης ΣΤ΄ δεν το δέχτηκε και άρχισε ο Τρίτος Μιθριδατικός Πόλεμος. Η Βιθυνία μετατράπηκε σε άμεση επαρχία της Ρώμης.", "b6ff7464"]},
"OLAYLAR_ANTIK_AKDENIZ:-0081-01-01:0":{"b": ["Ο Μπουρεμπίστας ένωσε τις φυλές των Δακών και των Γετών", "3648f92e"], "d": ["Σύμφωνα με τον Στράβωνα, ο Μπουρεμπίστας συγκέντρωσε τους Γέτες και τους Δάκες σε ένα βασίλειο και έκανε εκστρατείες νότια του Δούναβη μέχρι τα σύνορα της Θράκης και της Ιλλυρίας. Το βασίλειο άρχισε να αποτελεί απειλή για τη Ρώμη κατά μήκος του Δούναβη.", "6eefe618"]},
"OLAYLAR_ANTIK_AKDENIZ:-0084-01-01:0":{"b": ["Ειρήνη του Δαρδάνου: ο Μιθριδάτης αποσύρθηκε από την Ασία και τη Βιθυνία", "535818ed"], "d": ["Στην Ειρήνη του Δαρδάνου με τον Σύλλα, ο Μιθριδάτης δέχτηκε να εκκενώσει όλες τις κατακτήσεις του (Ασία, Βιθυνία, Καππαδοκία, Παφλαγονία), να δώσει 70 πλοία και 2000-3000 τάλαντα. Ωστόσο η κυριαρχία των εχθρών του Σύλλα στη Ρώμη οδήγησε στον Δεύτερο Μιθριδατικό Πόλεμο.", "baf04269"]},
"OLAYLAR_ANTIK_AKDENIZ:-0087-01-01:0":{"b": ["Ο Μιθριδάτης κατέλαβε την επαρχία Ασία· Εσπερινός της Εφέσου (σφαγή 80.000 Ρωμαίων)", "3986833b"], "d": ["Στην αρχή του Πρώτου Μιθριδατικού Πολέμου (89/88) ο Μιθριδάτης κατέλαβε τη Βιθυνία και την επαρχία Ασία· με διαταγή που έδωσε στην Έφεσο οι Ρωμαίοι πολίτες σκοτώθηκαν μαζικά. Και η Αθήνα πέρασε στο πλευρό του Πόντου (Αριστίων).", "1dc4fbbb"]},
"OLAYLAR_ANTIK_AKDENIZ:-0089-01-01:0":{"b": ["Lex Iulia: η Ρώμη έδωσε ιθαγένεια στους Ιταλούς συμμάχους (Κοινωνικός Πόλεμος)", "f72ba27d"], "d": ["Με την εξέγερση των Ιταλών συμμάχων της Ρώμης (91-88), ο Lex Iulia (90) και ο Lex Plautia Papiria (89) αναγνώρισαν ρωμαϊκή ιθαγένεια στους πιστούς και παραδοθέντες συμμάχους. Έτσι η ιταλική χερσόνησος μέχρι τον Πάδο έγινε μία κοινωνία πολιτών.", "8b973270"]},
"OLAYLAR_ANTIK_AKDENIZ:-0094-01-01:0":{"b": ["Ο Σύλλας κάθισε τον Αριοβαρζάνη στον θρόνο της Καππαδοκίας", "8bdd078c"], "d": ["Απέναντι στην κατοχή της Καππαδοκίας από τον Μιθριδάτη ΣΤ΄ μέσω ενός παιδιού-βασιλιά, η Ρώμη έβαλε κατά τη διοίκηση του Σύλλα στην Κιλικία να ανακηρυχθεί βασιλιάς ο Αριοβαρζάνης. Η Καππαδοκία τον επόμενο αιώνα έγινε ανάχωμα των διαμαχών Ρώμης-Περσίας-Πόντου.", "d8f615b3"]},
"OLAYLAR_ANTIK_AKDENIZ:-0095-01-01:0":{"b": ["Ο Πτολεμαίος Απίων άφησε με διαθήκη την Κυρήνη στη Ρώμη", "5edef477"], "d": ["Ο Πτολεμαίος Απίων, που κυβερνούσε την Κυρήνη, πεθαίνοντας χωρίς παιδιά άφησε το βασίλειό του στον Ρωμαϊκό Λαό (96)· η Σύγκλητος άφησε τις πόλεις ελεύθερες, η Ρώμη καθυστέρησε τη μετατροπή σε επαρχία μέχρι το 74.", "14d9ff7c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0104-01-01:0":{"b": ["Ο Βόκχος παρέδωσε τον Ιουγούρθα στη Ρώμη· η δύση της Νουμιδίας προσαρτήθηκε στη Μαυριτανία", "7619ad15"], "d": ["Ο βασιλιάς της Μαυριτανίας Βόκχος Α΄, πεθερός του Ιουγούρθα, παραδίδοντας τον Ιουγούρθα στον Σύλλα συμφιλιώθηκε με τη Ρώμη· ως αντάλλαγμα του αφέθηκε το δυτικό τμήμα της Νουμιδίας. Ο Ιουγούρθας πέθανε στη φυλακή στη Ρώμη το 104.", "0097a34f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0108-01-01:0":{"b": ["Ο Παιρισάδης Ε΄ άφησε το βασίλειο στον Μιθριδάτη ΣΤ΄: ο Βόσπορος εξαρτήθηκε από τον Πόντο", "835bbe74"], "d": ["Ο Παιρισάδης Ε΄, υπό σκυθική πίεση, με τη βοήθεια του διοικητή του Μιθριδάτη Διόφαντου παρέδωσε το βασίλειο στον Μιθριδάτη· ο Βόσπορος έτσι έγινε βόρεια επέκταση του Πόντου. Το εμπόριο σιτηρών της Μαύρης Θάλασσας πέρασε στην ημερομηνία αυτή στον Πόντο ως πηγή του Μιθριδάτη.", "f9df6329"]},
"OLAYLAR_ANTIK_AKDENIZ:-0109-01-01:0":{"b": ["Ο διοικητής του Μιθριδάτη Διόφαντος νίκησε τους Σκύθες στην Κριμαία", "d8d48c68"], "d": ["Ο Διόφαντος νίκησε τον στρατό του Παλάκου, γιου του βασιλιά των Σκυθών Σκιλούρου, και κατέλαβε στην Ταυρική την περιοχή της Νεάπολης· ο Βόσπορος και η Χερσόνησος εξαρτήθηκαν από τον Πόντο.", "aa4118e0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0111-01-01:0":{"b": ["Ο Ιουγούρθας κατέλαβε την Κίρτα: η Ρώμη παρενέβη στα νουμιδικά ζητήματα", "660eb34a"], "d": ["Ο Ιουγούρθας το 112 π.Χ. πολιόρκησε την Κίρτα και σκότωσε τον Αδέρβαλ· οι Ιταλοί έμποροι που σκοτώθηκαν στην πόλη ώθησαν τη Ρώμη να κηρύξει πόλεμο στον Ιουγούρθα. Ο πόλεμος διήρκεσε μέχρι το 105.", "e2064bc2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0117-01-01:0":{"b": ["Ιδρύθηκε η Narbo Martius: η Νότια Γαλατία (Gallia Transalpina) έγινε ρωμαϊκή επαρχία", "20c4bdfa"], "d": ["Η Ρώμη, που μπήκε στη Γαλατία με την έκκληση βοήθειας της Μασσαλίας (125), κατέλαβε την κοιλάδα του Ροδανού με τις νίκες της στις Aquae Sextiae (122) και επί των Allobroges· το 118 π.Χ. η Narbo Martius ιδρύθηκε ως η πρώτη ρωμαϊκή αποικία στη Γαλατία. Η περιοχή έγινε επαρχία Gallia Transalpina.", "41f61541"]},
"OLAYLAR_ANTIK_AKDENIZ:-0119-01-01:0":{"b": ["Ο Μιθριδάτης ΣΤ' Ευπάτωρ ανέβηκε στον θρόνο του Πόντου", "c2d5fd41"], "d": ["Ο Μιθριδάτης ΣΤ', που ανέβηκε παιδί στον θρόνο με τον θάνατο του Μιθριδάτη Ε' (120/119), μετά από κηδεμονία λίγων ετών ανέδειξε τον Πόντο σε δύναμη αντίπαλο της Ρώμης γύρω από τη Μαύρη Θάλασσα.", "d5779c35"]},
"OLAYLAR_ANTIK_AKDENIZ:-0124-01-01:0":{"b": ["Με έκκληση της Μασσαλίας η Ρώμη μπήκε στη Γαλατία", "eaf7eb0a"], "d": ["Όταν η Μασσαλία, υπό την πίεση των Salluvii και των Λιγύρων, ζήτησε βοήθεια από τη Ρώμη, η Ρώμη έστειλε το 125 στρατό στη Νότια Γαλατία. Η επέμβαση αυτή οδήγησε στην ίδρυση της Narbo Martius (118) και στην κατάληψη της Gallia Transalpina.", "2260c90e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0128-01-01:0":{"b": ["Ο Αριστόνικος ηττήθηκε· από τα εδάφη της Περγάμου ιδρύθηκε η επαρχία Ασία", "7ccdc59e"], "d": ["Ο Αριστόνικος, που διεκδικούσε τον θρόνο με το όνομα Ευμένης Γ', ηττήθηκε και συνελήφθη από τον ρωμαϊκό στρατό (129)· με τη ρύθμιση του Manius Aquillius, το πρώην βασίλειο της Περγάμου έγινε επαρχία Ασία. Το φορολογικό σύστημα της επαρχίας (publicani) ήταν μεγάλη πηγή εσόδων για τη Ρώμη.", "c32277b7"]},
"OLAYLAR_ANTIK_AKDENIZ:-0132-01-01:0":{"b": ["Η Νουμαντία έπεσε: η Κελτιβηρία προσαρτήθηκε στη Ρώμη", "ced07244"], "d": ["Ο Scipio Aemilianus, μετά από οκτάμηνη πολιορκία, παρέλαβε τη Νουμαντία με την πείνα (133)· η πόλη καταστράφηκε. Οι κελτιβηρικοί πόλεμοι έληξαν και το εσωτερικό της Hispania Citerior προσαρτήθηκε στη Ρώμη.", "27b1db44"]},
"OLAYLAR_ANTIK_AKDENIZ:-0145-01-01:0":{"b": ["Αχαϊκός Πόλεμος: η Αχαϊκή Συμπολιτεία ηττήθηκε από τη Ρώμη, οι συμπολιτείες διαλύθηκαν", "e434cfe0"], "d": ["Η Αχαϊκή Συμπολιτεία, που εξεγέρθηκε εναντίον της Ρώμης λόγω συνοριακής διαφοράς με τη Σπάρτη, ηττήθηκε το 146 στη Λευκόπετρα· η Κόρινθος καταστράφηκε και η Συμπολιτεία διαλύθηκε στην πράξη, ένα μέρος της Ελλάδας πέρασε στην εποπτεία της επαρχίας Μακεδονίας.", "5fc3bb08"]},
"OLAYLAR_ANTIK_AKDENIZ:-0145-01-01:1":{"b": ["Ο Τρίτος Καρχηδονιακός Πόλεμος έληξε: η Καρχηδόνα καταστράφηκε, ιδρύθηκε η επαρχία Africa", "522515b4"], "d": ["Ο P. Cornelius Scipio Aemilianus, μετά από τριετή πολιορκία, κατέλαβε την Καρχηδόνα την άνοιξη του 146· η πόλη κάηκε και καταστράφηκε, τα εδάφη προσαρτήθηκαν στη Ρώμη. Η ενδοχώρα της Καρχηδόνας έγινε επαρχία Africa· η Νουμιδία του Μασινίσσα έμεινε γείτονας στα δυτικά.", "cbee045b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0145-01-01:2":{"b": ["Η Μακεδονία έγινε ρωμαϊκή επαρχία", "dc6d2352"], "d": ["Μετά την καταστολή της εξέγερσης του Ανδρίσκου (148), οι τέσσερις περιοχές της Μακεδονίας ενώθηκαν σε μία ρωμαϊκή επαρχία (146)· στον νότο της επαρχίας ο έλεγχος της Ελλάδας αφέθηκε επίσης στην εποπτεία του κυβερνήτη της Μακεδονίας. Η Εγνατία Οδός χτίστηκε τα επόμενα χρόνια από την Αδριατική ως τη Θεσσαλονίκη.", "ac02ecf5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0147-01-01:0":{"b": ["Εξέγερση του Ανδρίσκου: το βασίλειο της Μακεδονίας ιδρύθηκε εκ νέου για σύντομο διάστημα, καταπνίγηκε από τον Μέτελλο", "0119ff73"], "d": ["Ο Άνδρισκος, που ισχυριζόταν ότι ήταν γιος του Περσέα, ένωσε ξανά τη Μακεδονία το 150/149 και νίκησε τις πρώτες ρωμαϊκές δυνάμεις· το 148 ο Μέτελλος ανέκτησε τη Μακεδονία. Η εξέγερση έγινε η αιτία της άμεσης υπαγωγής της Μακεδονίας στη ρωμαϊκή διοίκηση.", "b03ea4e9"]},
"OLAYLAR_ANTIK_AKDENIZ:-0148-01-01:0":{"b": ["Η Ρώμη κήρυξε πόλεμο στην Καρχηδόνα: ξεκίνησε ο Τρίτος Καρχηδονιακός Πόλεμος", "2e34c235"], "d": ["Η άμυνα της Καρχηδόνας απέναντι στις επιθέσεις του Μασινίσσα θεωρήθηκε παραβίαση της συνθήκης· η Ρώμη το 149 κήρυξε πόλεμο και προσάρτησε την Ουτίκη. Η πόλη της Καρχηδόνας αντιστάθηκε υπό πολιορκία επί τρία χρόνια.", "89432e4f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0149-01-01:0":{"b": ["Ο Μασινίσσας επιτέθηκε στα εδάφη της Καρχηδόνας: Πόλεμος Νουμιδίας-Καρχηδόνας", "b47559a5"], "d": ["Με την κατάληψη εδαφών της Καρχηδόνας από τον Μασινίσσα (151/150), η Καρχηδόνα κήρυξε πόλεμο και ηττήθηκε από τον Μασινίσσα· η Ρώμη το θεώρησε παραβίαση της συνθήκης και κήρυξε πόλεμο το 149. Ο Μασινίσσας πέθανε το 148 σε ηλικία ενενήντα ετών.", "f6ed046f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0166-01-01:0":{"b": ["Η Ρώμη διέταξε τη Ρόδο να αποσύρει τους κυβερνήτες της από τη Λυκία και την Καρία· η Λυκιακή Συμπολιτεία (Πάταρα) βγήκε από τη ροδιακή κυριαρχία", "6bbe2b54"], "d": ["Μετά τον Τρίτο Μακεδονικό Πόλεμο, η Σύγκλητος διέταξε τη Ρόδο να αποσύρει τους κυβερνήτες της από τη Λυκία και την Καρία μέχρι ορισμένη ημέρα· η Ρόδος δέχθηκε αυτές τις απώλειες θεωρώντας τες ελαφρύτερες από την απειλή πολέμου. Η Λυκιακή Συμπολιτεία (με κέντρο τα Πάταρα) βγήκε έτσι από τη ροδιακή κυριαρχία και συνεχίστηκε ως Λυκιακή Συμπολιτεία υπό ρωμαϊκή προστασία.", "8f86b52d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0166-01-01:1":{"b": ["Η Ήπειρος λεηλατήθηκε από τη Ρώμη: εβδομήντα πόλεις καταστράφηκαν", "456fb461"], "d": ["Μετά τον Τρίτο Μακεδονικό Πόλεμο, οι πόλεις των Μολοσσών της Ηπείρου που έμειναν κοντά στον Περσέα λεηλατήθηκαν με εντολή του Αιμίλιου Παύλου και περίπου 150.000 άνθρωποι υποδουλώθηκαν. Η Ήπειρος έμεινε φτωχή υπό ρωμαϊκή κυριαρχία τον επόμενο αιώνα.", "0504e2ee"]},
"OLAYLAR_ANTIK_AKDENIZ:-0166-01-01:2":{"b": ["Η Μακεδονία διαιρέθηκε από τη Ρώμη σε τέσσερις αυτόνομες περιοχές (merides)", "7a795ba0"], "d": ["Με απόφαση της Συγκλήτου (167 π.Χ.) το βασίλειο της Μακεδονίας διαιρέθηκε σε τέσσερις περιοχές με κέντρα την Αμφίπολη, τη Θεσσαλονίκη, την Πέλλα και την Πελαγονία· απαγορεύτηκαν οι γάμοι και η απόκτηση ακινήτων μεταξύ των περιοχών, περιορίστηκε η εκμετάλλευση των ορυχείων.", "de7135d5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0166-01-01:3":{"b": ["Η Ρώμη πήρε τη Λυκία και την Καρία από τη Ρόδο· η Δήλος ανακηρύχθηκε ελεύθερο λιμάνι", "09c8143f"], "d": ["Στον Τρίτο Μακεδονικό Πόλεμο τιμωρήθηκε η απόπειρα της Ρόδου να μεσολαβήσει ανάμεσα στη Ρώμη και στον Περσέα: η Σύγκλητος πήρε τη Λυκία και την Καρία από τη Ρόδο και τις ανακήρυξε ελεύθερες, έδωσε τη Δήλο στην Αθήνα και την έκανε λιμάνι χωρίς τελωνεία. Τα εμπορικά έσοδα της Ρόδου έπεσαν βαριά.", "9636f108"]},
"OLAYLAR_ANTIK_AKDENIZ:-0167-06-22:0":{"b": ["Πύδνα: ο Αιμίλιος Παύλος νίκησε τον Περσέα· το βασίλειο των Αντιγονιδών έληξε", "a59c5270"], "d": ["Στις 22 Ιουνίου 168, στην Πύδνα, οι ρωμαϊκές λεγεώνες νίκησαν τη μακεδονική φάλαγγα και έβαλαν τέλος στον Τρίτο Μακεδονικό Πόλεμο· ο Περσέας παραδόθηκε στη Σαμοθράκη και μεταφέρθηκε στη Ρώμη για τον θρίαμβο. Η δυναστεία των Αντιγονιδών έληξε.", "d363d3f0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0187-01-01:0":{"b": ["Ειρήνη της Απάμειας: ο Ευμένης Β' απέκτησε για την Πέργαμο τη Χερσόνησο της Θράκης, τη Φρυγία, τη Λυδία και το μεγαλύτερο μέρος της Μυσίας", "f25ed9af"], "d": ["Μετά την ήττα στη Μαγνησία, ο Αντίοχος Γ' υπέγραψε το 188 ειρήνη με τη Ρώμη: άφησε τον βορρά των βουνών του Ταύρου. Τα περισσότερα από αυτά τα εδάφη δόθηκαν στην Πέργαμο του συμμάχου Ευμένη Β' (Χερσόνησος της Θράκης, Μεγάλη Φρυγία, Λυδία, Μυσία, μέρος της Ιωνίας).", "8ae36db5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0187-01-01:1":{"b": ["Ειρήνη της Απάμειας: η Ρόδος πήρε τη Λυκία και τον νότο της Καρίας", "aa5173c6"], "d": ["Μετά τη Μαγνησία, η Ρώμη έδωσε στον σύμμαχο Ρόδο τη Λυκία και το τμήμα της Καρίας νότια του Μαιάνδρου. Η Ρόδος έχασε αυτά τα εδάφη το 167.", "74a2ccb5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0188-01-01:0":{"b": ["Ο Manlius Vulso νίκησε τις γαλατικές φυλές: η ανεξαρτησία των Γαλατών πέρασε στην εποπτεία της Ρώμης", "30ae73d7"], "d": ["Μετά τη Μαγνησία, ο Cn. Manlius Vulso εισέβαλε στη χώρα των Γαλατών και κατατρόπωσε στον Όλυμπο και στη Μαγάβα τους Τολιστοαγίους και τους Τεκτόσαγες· με συνθήκη οι Γαλάτες δέχθηκαν να μην επιτίθενται στους γείτονες. Η Γαλατία παρέμεινε σε μεγάλο βαθμό ανεξάρτητη αλλά εξαρτήθηκε από την ισορροπία Ρώμης-Περγάμου.", "fb7daca7"]},
"OLAYLAR_ANTIK_AKDENIZ:-0188-01-01:1":{"b": ["Η Αιτωλία έκανε ειρήνη με τη Ρώμη: έχασε την Αμβρακία και τα Οινιάδες, αναγνώρισε την κυριαρχία της Ρώμης", "f332c6bf"], "d": ["Η Αιτωλία, που στον Πόλεμο του Αντιόχου είχε σταθεί στο πλευρό του Αντιόχου, έκανε ειρήνη με τη Ρώμη μετά την πολιορκία της Αμβρακίας από τον Fulvius Nobilior· αναγνώρισε την «μεγαλειότητα» της Ρώμης, πλήρωσε αποζημίωση και άφησε πόλεις όπως η Αμβρακία και τα Οινιάδες.", "a6d05b8b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0189-01-01:0":{"b": ["Μαγνησία του Σιπύλου: η Ρώμη και η Πέργαμος νίκησαν τον Αντίοχο Γ'", "f650ef21"], "d": ["Τον χειμώνα του 190/189 στη Μαγνησία, ο L. Scipio και ο Ευμένης Β' κατατρόπωσαν τον στρατό του Αντιόχου Γ'. Η Ειρήνη της Απάμειας (188), που έγινε μετά τη νίκη, οδήγησε στην εγκατάλειψη του βορρά του Ταύρου από τον Αντίοχο.", "04d021ad"]},
"OLAYLAR_ANTIK_AKDENIZ:-0191-01-01:0":{"b": ["Η Σπάρτη προσχώρησε στην Αχαϊκή Συμπολιτεία: ο Φιλοποίμην μετά τον Νάβι προσάρτησε τη Λακωνία στη συμπολιτεία", "2629b6e1"], "d": ["Μετά τη δολοφονία του Σπαρτιάτη τυράννου Νάβι (192), ο στρατηγός των Αχαιών Φιλοποίμην προσάρτησε διά της βίας τη Σπάρτη στην Αχαϊκή Συμπολιτεία. Η Σπάρτη έχασε εντελώς την ανεξαρτησία της το 188 με την κατεδάφιση των τειχών.", "6ed14d83"]},
"OLAYLAR_ANTIK_AKDENIZ:-0195-01-01:0":{"b": ["Ο Φλαμινίνος ανακήρυξε την ελευθερία των Ελλήνων στους Ισθμικούς Αγώνες", "3d850bf2"], "d": ["Μετά τις Κυνός Κεφαλές, ο Ρωμαίος διοικητής T. Quinctius Flamininus, στους Ισθμικούς Αγώνες του 196 π.Χ., ανακήρυξε ότι οι μακεδονικές φρουρές στην Κόρινθο, στη Χαλκίδα και στη Δημητριάδα θα αποσύρονταν και ότι οι ελληνικές πόλεις ήταν «ελεύθερες, αφορολόγητες και υπακούουσες στους δικούς τους νόμους». Η Ρώμη εγκαταστάθηκε έτσι ως διαιτητής στην Ελλάδα.", "41ba1fc4"]},
"OLAYLAR_ANTIK_AKDENIZ:-0196-01-01:0":{"b": ["Κυνός Κεφαλές: η Ρώμη νίκησε τον Φίλιππο Ε'· η Μακεδονία αναγκάστηκε να αποσυρθεί από την Ελλάδα", "9cb44ca6"], "d": ["Τον Ιούνιο του 197, οι ρωμαϊκές λεγεώνες του Φλαμινίνου κατατρόπωσαν τη μακεδονική φάλαγγα στις Κυνός Κεφαλές. Στην ειρήνη του 196 ο Φίλιππος άφησε όλες τις θέσεις του στην Ελλάδα (Δημητριάδα, Χαλκίδα, Κόρινθο), παρέδωσε τον στόλο του και πλήρωσε 1000 τάλαντα.", "da059ad7"]},
"OLAYLAR_ANTIK_AKDENIZ:-0196-01-01:1":{"b": ["Ιδρύθηκαν στην Hispania δύο ρωμαϊκές επαρχίες: Citerior και Ulterior", "1baa8383"], "d": ["Τα εδάφη της Hispania που πάρθηκαν από την Καρχηδόνα χωρίστηκαν το 197 για πρώτη φορά σε δύο ξεχωριστές επαρχίες και κάθε μία διοικήθηκε από praetor. Από αυτή την ημερομηνία οι κελτιβηρικοί και λουσιτανικοί πόλεμοι στη χερσόνησο γίνονταν για να επεκταθεί η ρωμαϊκή επαρχιακή τάξη.", "5b732530"]},
"OLAYLAR_ANTIK_AKDENIZ:-0200-01-01:0":{"b": ["Ειρήνη μετά τη Ζάμα: η Καρχηδόνα έχασε την Hispania και τα νησιά της Μεσογείου, τον στόλο, ανέλαβε αποζημίωση 10.000 ταλάντων", "8654422d"], "d": ["Μετά τη Ζάμα (202), η Ρώμη περιόρισε την Καρχηδόνα στα εδάφη της στην Αφρική: δέχθηκαν οι όροι της εγκατάλειψης της Hispania και των νησιών της Μεσογείου, της παράδοσης του στόλου (εκτός από 10 πλοία), της πληρωμής 10.000 ταλάντων επί 50 χρόνια και της μη κήρυξης πολέμου χωρίς άδεια της Ρώμης. Η Νουμιδία του Μασινίσσα έγινε ανεξάρτητος γείτονας.", "fcba363e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0200-01-01:1":{"b": ["Η Ρώμη επιβράβευσε τον Μασινίσσα με το βασίλειο του Σύφακα", "54ba7a64"], "d": ["Στην ειρήνη της Ζάμας η Ρώμη όρισε τον Μασινίσσα στο βασίλειο του Σύφακα και στα συνοριακά εδάφη που πάρθηκαν από την Καρχηδόνα· οι αξιώσεις του Μασινίσσα για την περιοχή «Emporia» και το σύνορο της Καρχηδόνας έγιναν αργότερα αιτία πολέμου.", "106adff6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0201-01-01:0":{"b": ["Ζάμα: ο Σκιπίων και ο Μασινίσσας νίκησαν τον Αννίβα", "52e188e6"], "d": ["Στη μάχη της Ζάμας, που έγινε μετά την ανάκληση του Αννίβα στην Αφρική, οι λεγεώνες του Σκιπίωνα και το νουμιδικό ιππικό του Μασινίσσα νίκησαν τον καρχηδονιακό στρατό. Ο Δεύτερος Καρχηδονιακός Πόλεμος έληξε με αυτή τη μάχη οριστικά υπέρ της Ρώμης.", "0cd233b4"]},
"OLAYLAR_ANTIK_AKDENIZ:-0202-01-01:0":{"b": ["Ο Σύφαξ ηττήθηκε και αιχμαλωτίστηκε· ο Μασινίσσας ένωσε τη Νουμιδία", "a42a3cb0"], "d": ["Ο Σκιπίων και ο Μασινίσσας νίκησαν το 203 τον στρατό του Σύφακα και αιχμαλώτισαν τον Σύφακα· ο Μασινίσσας κατέλαβε την Cirta και το βασίλειο του Σύφακα με τη ρωμαϊκή υποστήριξη. Η Νουμιδία έγινε ισχυρό βασίλειο με την ένωση του ανατολικού και του δυτικού τμήματος.", "d6649bd5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0205-01-01:0":{"b": ["Ilipa και Gades: η Hispania πέρασε από την Καρχηδόνα στη Ρώμη", "31e5a50c"], "d": ["Ο Σκιπίων το 206 στην Ilipa νίκησε τον στρατό του Hasdrubal Gisgo και του Mago και έβαλε τέλος στον καρχηδονιακό έλεγχο στην Hispania· και τα Γάδειρα πέρασαν λίγο αργότερα στη Ρώμη. Η Καρχηδόνα έχασε τα ασημένια ορυχεία της Hispania και τη δεξαμενή στρατιωτών.", "dd505492"]},
"OLAYLAR_ANTIK_AKDENIZ:-0208-01-01:0":{"b": ["Ο Fabius Maximus ανέκτησε τον Τάραντα από τον Αννίβα", "bd605091"], "d": ["Ο Τάρας (Tarent), που είχε παραδοθεί στον Αννίβα το 212, πέρασε το 209 με προδοσία στον Q. Fabius Maximus. Με την πτώση της πόλης ο Αννίβας έχασε το πολυτιμότερο λιμάνι του στη Νότια Ιταλία.", "33c6b48f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0210-01-01:0":{"b": ["Η Capua έπεσε στη Ρώμη: χάθηκε η βάση του Αννίβα στην Καμπανία", "cfcb9c9a"], "d": ["Η Ρώμη, που πολιόρκησε επί δύο χρόνια την Capua που είχε περάσει στον Αννίβα μετά τις Κάννες, κατέλαβε την πόλη παρά την κίνηση πορείας του Αννίβα προς τη Ρώμη και την τιμώρησε βαριά· η αυτονομία της Capua καταργήθηκε. Ο Αννίβας αποσύρθηκε σε άμυνα στη Νότια Ιταλία.", "9a129e81"]},
"OLAYLAR_ANTIK_AKDENIZ:-0215-01-01:0":{"b": ["Κάννες: ο Αννίβας περικύκλωσε και εξόντωσε τον ρωμαϊκό στρατό· η Νότια Ιταλία άρχισε να περνά στην Καρχηδόνα", "94f5110a"], "d": ["Το 216, στις Κάννες της Απουλίας, η διάταξη περικύκλωσης του Αννίβα εξόντωσε τον ρωμαϊκό στρατό περίπου εβδομήντα χιλιάδων ανδρών. Η Capua, ο Τάρας και πολλές πόλεις της Νότιας Ιταλίας πέρασαν στο πλευρό της Καρχηδόνας.", "1a19e07d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0217-01-01:0":{"b": ["Ο ρωμαϊκός στρατός αποβιβάστηκε στην Hispania: πρώτη ρωμαϊκή βάση στην Emporion", "8cb47853"], "d": ["Μετά την πορεία του Αννίβα προς την Ιταλία, ο Cn. Cornelius Scipio αποβιβάστηκε το 218 π.Χ. στην Emporion και ξεκίνησε τη ρωμαϊκή παρουσία στην Hispania στις όχθες του Έβρου· η χερσόνησος έγινε το δεύτερο μέτωπο του Δεύτερου Καρχηδονιακού Πολέμου.", "ef7a1d28"]},
"OLAYLAR_ANTIK_AKDENIZ:-0217-01-01:1":{"b": ["Ο Αννίβας πέρασε τις Άλπεις και μπήκε στην Ιταλία", "a1d3bf5a"], "d": ["Ο Αννίβας πέρασε τον Έβρο, τα Πυρηναία και τον Ροδανό και το φθινόπωρο πέρασε τις Άλπεις και κατέβηκε στη Βόρεια Ιταλία· νίκησε τους ρωμαϊκούς στρατούς στον Ticinus και στον Trebia. Το κέντρο του πολέμου της Καρχηδόνας στην Ιταλία μεταφέρθηκε έτσι μέσα στη Ρώμη.", "8a70efb1"]},
"OLAYLAR_ANTIK_AKDENIZ:-0218-01-01:0":{"b": ["Ο Αννίβας κατέλαβε τη Ζάκυνθο (Saguntum): ανάφτηκε το φυτίλι του Δεύτερου Καρχηδονιακού Πολέμου", "a497a334"], "d": ["Ο Αννίβας, μετά από οκτάμηνη πολιορκία, κατέλαβε το Saguntum, σύμμαχο της Ρώμης (219 π.Χ.)· η Ρώμη έστειλε απεσταλμένους και ζήτησε την παράδοση του Αννίβα και, όταν απορρίφθηκε, κηρύχθηκε πόλεμος. Ο πόλεμος διήρκεσε δεκαεπτά χρόνια στην Ιταλία, στην Hispania και στην Αφρική.", "8f80d7b4"]},
"OLAYLAR_ANTIK_AKDENIZ:-0221-01-01:0":{"b": ["Σελλασία: ο Αντίγονος Δώσων νίκησε τον Κλεομένη, η Σπάρτη υπέστη για πρώτη φορά ξένη κατοχή", "dc64a8db"], "d": ["Το καλοκαίρι του 222, στη Σελλασία, η μακεδονο-αχαϊκή συμμαχία νίκησε τον σπαρτιατικό στρατό του Κλεομένη· ο Κλεομένης διέφυγε στην Αίγυπτο. Ο Δώσων μπήκε στη Σπάρτη, την επανέφερε στη λυκούργεια τάξη· οι Σπαρτιάτες έζησαν για πρώτη φορά στην ιστορία τους κατοχή από ξένο στρατό.", "575b0c9d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0221-01-01:1":{"b": ["Το Mediolanum (Μιλάνο) έπεσε στη Ρώμη: οι Insubres ηττήθηκαν, η Βόρεια Ιταλία άνοιξε στη Ρώμη", "d3ec639f"], "d": ["Η Ρώμη, που νίκησε τους Γαλάτες στο Telamon (225), το 222 π.Χ. με τη νίκη του Μάρκελλου στο Clastidium και με την κατάληψη του Mediolanum έθεσε υπό έλεγχο το μεγαλύτερο μέρος της πεδιάδας του Πάδου. Η περιοχή οργανώθηκε ως Cisalpina Γαλατία.", "710258fd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0223-01-01:0":{"b": ["Η Αχαϊκή Συμπολιτεία παρέδωσε τον Ακροκόρινθο στον Αντίγονο Δώσωνα: η Κόρινθος επέστρεψε στη Μακεδονία", "c8ec9d0c"], "d": ["Η Αχαϊκή Συμπολιτεία, υπό την πίεση του Κλεομένη Γ', ζητώντας βοήθεια από τη Μακεδονία μέσω του Άρατου, παρέδωσε τον Ακροκόρινθο και την Κόρινθο στον Αντίγονο Δώσωνα· ο Δώσων ίδρυσε την Ελληνική Συμμαχία (Hellenikos symmachia).", "4337420d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0225-01-01:0":{"b": ["Συνθήκη του Έβρου: η Καρχηδόνα δέχθηκε να μην περάσει βόρεια του Έβρου", "a199de0b"], "d": ["Ο Hasdrubal, που συνέχισε την κατάκτηση της Hispania που είχε ξεκινήσει ο Hamilkar, έκανε με τη Ρώμη τη Συνθήκη του Έβρου: η Καρχηδόνα δεν θα περνούσε ένοπλη τον Έβρο. Η επίθεση του Αννίβα στο Saguntum το 219 στηρίχθηκε στην ερμηνεία αυτής της συνθήκης.", "42aa3953"]},
"OLAYLAR_ANTIK_AKDENIZ:-0237-01-01:0":{"b": ["Η Ρώμη πήρε τη Σαρδηνία και την Κορσική από την Καρχηδόνα", "4f7295ee"], "d": ["Όταν οι στασιαστές μισθοφόροι της Καρχηδόνας στη Σαρδηνία ζήτησαν βοήθεια από τη Ρώμη, η Ρώμη κατέλαβε το νησί· η Καρχηδόνα, με την απειλή πολέμου, αναγκάστηκε να αφήσει τα νησιά και να πληρώσει επιπλέον 1200 τάλαντα. Η Ρώμη δημιούργησε τη δεύτερη επαρχία (Sardinia et Corsica).", "60cb31ea"]},
"OLAYLAR_ANTIK_AKDENIZ:-0240-01-01:0":{"b": ["Αιγάτες Νήσοι: ο καρχηδονιακός στόλος καταστράφηκε· η Σικελία έγινε η πρώτη ρωμαϊκή επαρχία", "8bd16e8f"], "d": ["Ο Lutatius Catulus τον Μάρτιο του 241 κατατρόπωσε μπροστά στις Αιγάτες τον καρχηδονιακό στόλο του Hanno· στη συνέχεια, με την Ειρήνη του Lutatius, η Καρχηδόνα εκκένωσε τη Σικελία και δέχθηκε να πληρώσει πολεμική αποζημίωση 3200 ταλάντων. Η Σικελία (εκτός από τις Συρακούσες του Ιέρωνα) έγινε η πρώτη επαρχία της Ρώμης.", "24ff35a3"]},
"OLAYLAR_ANTIK_AKDENIZ:-0242-01-01:0":{"b": ["Ο Άρατος κατέλαβε τον Ακροκόρινθο: η Κόρινθος πέρασε από τη Μακεδονία στην Αχαϊκή Συμπολιτεία", "a88dfda6"], "d": ["Ο Άρατος ο Σικυώνιος, με νυχτερινή επίθεση, εξουδετέρωσε τη φρουρά του Αντιγόνου Γονατά στον Ακροκόρινθο και προσάρτησε την Κόρινθο στην Αχαϊκή Συμπολιτεία· και τα Μέγαρα, η Τροιζήνα και η Επίδαυρος πέρασαν στη συμπολιτεία. Η Μακεδονία έχασε το κλειδί της στην Πελοπόννησο.", "84d43a24"]},
"OLAYLAR_ANTIK_AKDENIZ:-0250-01-01:0":{"b": ["Ο Άρατος προσάρτησε τη Σικυώνα στην Αχαϊκή Συμπολιτεία", "6f413f9c"], "d": ["Ο νεαρός Άρατος ανέτρεψε τον τύραννο της Σικυώνας και συνέδεσε την πόλη με την Αχαϊκή Συμπολιτεία· το βήμα αυτό επέκτεινε τη Συμπολιτεία στις βόρειες και νότιες ακτές του Κορινθιακού Κόλπου και οδήγησε στην εκλογή του Άρατου ως στρατηγού.", "1becea45"]},
"OLAYLAR_ANTIK_AKDENIZ:-0262-01-01:0":{"b": ["Ο Ιέρων Β' συμμάχησε με τη Ρώμη: η Ανατολική Σικελία έγινε σύμμαχος της Ρώμης", "5e95a134"], "d": ["Ο Ιέρων, στις αρχές του Πρώτου Καρχηδονιακού Πολέμου, λόγω του ζητήματος της Μεσσάνας είχε συμμαχήσει με την Καρχηδόνα εναντίον της Ρώμης· το 263 έκανε ειρήνη και συμμαχία με τη Ρώμη και παρέμεινε πιστός σύμμαχος της Ρώμης σε όλη τη ζωή του (μέχρι το 215). Οι Συρακούσες έγιναν το συμμαχικό κράτος της ρωμαϊκής Σικελίας που έμεινε έξω από την επαρχία.", "4be7c84b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0263-01-01:0":{"b": ["Ο Νικομήδης Α' ίδρυσε τη Νικομήδεια (İzmit)", "a89ed42a"], "d": ["Ο Νικομήδης, μετά την καταστροφή του Αστακού, ίδρυσε τη Νικομήδεια στο ανατολικό άκρο του κόλπου· η πόλη έγινε τους επόμενους αιώνες κέντρο της Βιθυνίας και, την εποχή του Διοκλητιανού, της ρωμαϊκής ανατολικής πρωτεύουσας.", "a172ed71"]},
"OLAYLAR_ANTIK_AKDENIZ:-0263-01-01:1":{"b": ["Ξεκίνησε ο Πρώτος Καρχηδονιακός Πόλεμος: ο Appius Claudius πέρασε στη Μεσσάνα", "636e1533"], "d": ["Όταν οι Μαμερτίνοι ζήτησαν βοήθεια για τη Μεσσάνα εναντίον του βασιλιά των Συρακουσών Ιέρωνα, μετά την Καρχηδόνα και από τη Ρώμη, ο Ρωμαίος ύπατος Appius Claudius Caudex πέρασε το 264 στη Σικελία και κατέλαβε τη Μεσσάνα από την καρχηδονιακή φρουρά. Έτσι η Ρώμη μπήκε για πρώτη φορά σε πόλεμο εκτός Ιταλίας.", "de7b7f25"]},
"OLAYLAR_ANTIK_AKDENIZ:-0263-01-01:2":{"b": ["Το Volsinii έπεσε: η τελευταία ανεξάρτητη μεγάλη πόλη της Ετρουρίας πέρασε στη Ρώμη", "b6aed092"], "d": ["Η Ρώμη κατέλαβε το 264 το Volsinii, που είχε ζητήσει τη βοήθειά της λόγω εξέγερσης δούλων, και μετέφερε τους κατοίκους της πόλης σε νέο τόπο. Η Ετρουρία έπεσε από τότε στην πράξη υπό ρωμαϊκή κυριαρχία.", "4384ae1d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0271-01-01:0":{"b": ["Ο Πύρρος σκοτώθηκε στο Άργος", "2b4996fa"], "d": ["Στην εκστρατεία της Πελοποννήσου, στην οδομαχία του Άργους ο Πύρρος τραυματίστηκε από κεραμίδι και πέθανε (272). Η Ήπειρος έχασε το βάρος της έναντι της Μακεδονίας και ξανάφτιαξε τις σχέσεις με τη Ρώμη.", "2e7f4937"]},
"OLAYLAR_ANTIK_AKDENIZ:-0271-01-01:1":{"b": ["Ο Τάρας παραδόθηκε στη Ρώμη: η Νότια Ιταλία προσαρτήθηκε στη Ρώμη", "6e87c924"], "d": ["Μετά την αναχώρηση του Πύρρου, η ηπειρωτική φρουρά του Τάραντα αποσύρθηκε και η πόλη παραδόθηκε στη Ρώμη (272). Μαζί με το Bruttium και τη Lucania, οι ελληνικές πόλεις της Νότιας Ιταλίας έγιναν σύμμαχοι της Ρώμης· έτσι η Ρώμη έγινε κυρίαρχος της ιταλικής χερσονήσου μέχρι την πεδιάδα του Πάδου.", "b7f98699"]},
"OLAYLAR_ANTIK_AKDENIZ:-0274-01-01:0":{"b": ["Maleventum (Beneventum): ο Πύρρος αποσύρθηκε από την Ιταλία", "ab67e9f5"], "d": ["Η νέα επίθεση του Πύρρου στη Ρώμη μετά την επιστροφή του από την εκστρατεία στη Σικελία απέτυχε στο Maleventum μπροστά στον Manius Curius Dentatus· ο Πύρρος το 275 επέστρεψε στην Ήπειρο. Άφησε μικρή φρουρά στον Τάραντα· η Ρώμη έμεινε αδιαφιλονίκητη στην Ιταλία.", "f2c89575"]},
"OLAYLAR_ANTIK_AKDENIZ:-0274-01-01:1":{"b": ["Ο Αντίοχος Α΄ νίκησε τους Γαλάτες στη «Μάχη των Ελεφάντων»", "1e88c2d0"], "d": ["Ο Αντίοχος Α΄, νικώντας τους Γαλάτες με τους ελέφαντές του, πήρε το προσωνύμιο Σωτήρ («σωτήρας»)· οι Γαλάτες επέστρεψαν στο σύστημα μόνιμου φόρου και επιδρομών στην Κεντρική Ανατολία. Τους επόμενους αιώνες οι συγκρούσεις με την Πέργαμο και τη Βιθυνία συνεχίστηκαν.", "f925c4fd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0275-01-01:0":{"b": ["Ο Αντίγονος Γονατάς έγινε βασιλιάς της Μακεδονίας: η δυναστεία των Αντιγονιδών εδραιώθηκε", "4b907dd6"], "d": ["Ο Γονατάς, αφού νίκησε τους Γαλάτες στη Λυσιμάχεια το 277 και κέρδισε φήμη, εγκαταστάθηκε το 276 στον θρόνο της Μακεδονίας. Η δυναστεία κυβέρνησε τη Μακεδονία μέχρι το 168· στην Ελλάδα κράτησε τα κάστρα της Κορίνθου, της Χαλκίδας και του Πειραιά.", "d13f42b2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0277-01-01:0":{"b": ["Ο Νικομήδης Α΄ πέρασε τους Γαλάτες στην Ανατολία", "9e5ab10b"], "d": ["Ο βασιλιάς της Βιθυνίας Νικομήδης Α΄, κατά του αδελφού του Ζιποίτη και της πίεσης των Σελευκιδών, πέρασε φυλές των Γαλατών (Κελτών) από τον Βόσπορο και τις πήρε στην υπηρεσία του· οι Γαλάτες αργότερα εγκαταστάθηκαν στην Κεντρική Ανατολία· ο κλάδος των Τεκτοσάγων έκανε την Άγκυρα (Ankyra) πρωτεύουσα (TDV «Ankara»: «από το 278 έως το 189 π.Χ. έγινε πρωτεύουσα του κλάδου των Τεκτοσάγων των Γαλατών που ήρθαν από τη Θράκη»). Η ημερομηνία διέλευσης 278/277.", "b9f3dcc3"]},
"OLAYLAR_ANTIK_AKDENIZ:-0278-01-01:0":{"b": ["Η Αιτωλική Συμπολιτεία υπερασπίστηκε τους Δελφούς κατά της γαλατικής επιδρομής", "5488966a"], "d": ["Ο γαλατικός στρατός του Βρέννου πέρασε τις Θερμοπύλες και προχώρησε στους Δελφούς· η αντίσταση των Αιτωλών και των Φωκέων διέλυσε την επιδρομή. Το βάρος της Αιτωλίας στην Αμφικτυονία των Δελφών μεγάλωσε με αυτή τη νίκη.", "af3aba53"]},
"OLAYLAR_ANTIK_AKDENIZ:-0279-01-01:0":{"b": ["Ο Πύρρος πέρασε στην Ιταλία σε βοήθεια του Τάραντα· νίκησε τους Ρωμαίους στην Ηράκλεια", "55f18e85"], "d": ["Ο Πύρρος, που αποβιβάστηκε στην Ιταλία το 280 με έκκληση του Τάραντα κατά της Ρώμης, νίκησε στην Ηράκλεια τον στρατό του Valerius Laevinus με ελέφαντες και ιππικό, αλλά έχασε βαριά. Το 279 κέρδισε ξανά στο Ασκούλουμ, το 278-276 πέρασε στη Σικελία.", "60cab05c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0279-01-01:1":{"b": ["Ξαναιδρύθηκε η Αχαϊκή Συμπολιτεία: Πάτραι, Δύμη, Τριταία, Φαραί", "81bba071"], "d": ["Στην Αχαΐα υπό αντιγονιδικό έλεγχο, τέσσερις πόλεις (Δύμη, Πάτραι, Τριταία, Φαραί) το 280 π.Χ. ίδρυσαν ξανά ομοσπονδιακή συμπολιτεία· τα επόμενα χρόνια προσχώρησαν το Αίγιο και άλλες πόλεις. Η συμπολιτεία υπό την ηγεσία του Άρατου έγινε μεγάλη δύναμη της Πελοποννήσου.", "2426b2cc"]},
"OLAYLAR_ANTIK_AKDENIZ:-0280-01-01:0":{"b": ["Ο Φιλέταιρος μετά την Κουροπέδιο πέρασε στον Σέλευκο· η Πέργαμος ίδρυσε στην πράξη ανεξάρτητη δυναστεία", "ac6b3e31"], "d": ["Μετά την πτώση του Λυσιμάχου, ο Φιλέταιρος με τον θησαυρό προσχώρησε στον Σέλευκο και προστάτευσε και πλούτισε την Πέργαμο· με τον θάνατο του Σελεύκου (281) έγινε στην πράξη ανεξάρτητος. Ο Λίβιος δίνει ότι η δυναστεία των Ατταλιδών κυβέρνησε την Πέργαμο από το 283 έως το 129.", "cbc3946d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0284-01-01:0":{"b": ["Ο Λυσίμαχος έβγαλε τον Πύρρο από τη Μακεδονία και έγινε ο μοναδικός βασιλιάς της Μακεδονίας", "a83e6c64"], "d": ["Μετά τον χειμώνα του 285, όταν ο Δημήτριος παραδόθηκε στον Σέλευκο, ο Λυσίμαχος έδιωξε τον Πύρρο από τη Μακεδονία και κυβέρνησε μόνος τη χώρα. Το κράτος του έφτασε σε μια εκτεταμένη περιοχή που περιλάμβανε τη Θράκη, τη Μακεδονία και τη Δυτική Ανατολία.", "8ba7b764"]},
"OLAYLAR_ANTIK_AKDENIZ:-0286-01-01:0":{"b": ["Ο Πύρρος και ο Λυσίμαχος διαίρεσαν τη Μακεδονία· ο Δημήτριος ο Πολιορκητής ανατράπηκε", "63371ab8"], "d": ["Όταν το καλοκαίρι του 287 ο Δημήτριος πέρασε στην Ασία, ο Πύρρος και ο Λυσίμαχος διαίρεσαν από κοινού τη Μακεδονία σε δύο περιοχές· ο Δημήτριος κατέρρευσε. Αυτή η διανομή κράτησε μόνο δύο χρόνια.", "9e4b93b2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0289-01-01:0":{"b": ["Το Σάμνιο προσαρτήθηκε στη Ρώμη: ο Τρίτος Σαμνιτικός Πόλεμος έληξε", "bede9942"], "d": ["Ο Manius Curius Dentatus νίκησε οριστικά τους Σαμνίτες και τους Σαβίνους· το Σάμνιο έγινε σύμμαχος της Ρώμης. Η Ρώμη έγινε κυρίαρχος της Κεντρικής Ιταλίας και βρέθηκε αντιμέτωπη με τις ελληνικές πόλεις της Νότιας Ιταλίας (Τάρας).", "9c7619a6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0293-01-01:0":{"b": ["Ο Δημήτριος ο Πολιορκητής ανακηρύχθηκε βασιλιάς της Μακεδονίας", "a2b1eba3"], "d": ["Ο Δημήτριος, εκμεταλλευόμενος τη διαμάχη για τον θρόνο στη δυναστεία του Κασσάνδρου, ανακηρύχθηκε το φθινόπωρο του 294 από τον στρατό βασιλιάς της Μακεδονίας. Είναι η πρώτη κυριαρχία της γενιάς του Αντιγόνου στη Μακεδονία· κατέρρευσε το 288 και ο Γονατάς την έκανε μόνιμη το 276.", "959705f1"]},
"OLAYLAR_ANTIK_AKDENIZ:-0294-01-01:0":{"b": ["Σεντίνουμ: η συμμαχία Ετρούσκων, Ουμβρών, Σαμνιτών και Γαλατών ηττήθηκε από τη Ρώμη", "b5affc1b"], "d": ["Στον Τρίτο Σαμνιτικό Πόλεμο αυτή η μάχη στο Σεντίνουμ εξάλειψε την τελευταία μεγάλη αντιρωμαϊκή συμμαχία στην Ιταλία· οι ετρουσκικές πόλεις αναγκάστηκαν η μία μετά την άλλη να γίνουν σύμμαχοι της Ρώμης.", "b5bfb032"]},
"OLAYLAR_ANTIK_AKDENIZ:-0295-01-01:0":{"b": ["Ο Πύρρος επέστρεψε στον θρόνο της Ηπείρου με την υποστήριξη του Πτολεμαίου", "6288bf69"], "d": ["Ο Πύρρος, που έμεινε όμηρος στην Αίγυπτο μετά την Ιψό, με τη βοήθεια του Πτολεμαίου επέστρεψε στην Ήπειρο και ανέκτησε τον θρόνο. Η Ήπειρος από τότε απέκτησε λόγο στα ζητήματα της Μακεδονίας και της Ιταλίας.", "e15989dd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0300-01-01:0":{"b": ["Ο Λυσίμαχος έβαλε τον θησαυρό του στην Πέργαμο· ο Φιλέταιρος έγινε φρουρός του κάστρου", "e1b4ab77"], "d": ["Μετά την Ιψό ο Λυσίμαχος έβαλε να φυλαχτεί ο θησαυρός του στο κάστρο της Περγάμου στον λόφο και ανέθεσε τη φρούρηση στον ευνούχο Φιλέταιρο. Ο Φιλέταιρος το 281 πέρασε στον Σέλευκο και έθεσε τα θεμέλια της δυναστείας.", "6fabb342"]},
"OLAYLAR_ANTIK_AKDENIZ:-0301-01-01:0":{"b": ["Ο Α΄ Μιθριδάτης Κτίστης ίδρυσε τη δυναστεία του Πόντου", "490c338c"], "d": ["Ο Μιθριδάτης, που είχε πλησιάσει τον Αντίγονο Μονόφθαλμο, το 302 διέφυγε τον κίνδυνο να σκοτωθεί και κατέφυγε στην ορεινή περιοχή του Πόντου της Καππαδοκίας στα Κιμιάτα, όπου σχημάτισε τον πυρήνα του βασιλείου του Πόντου. Η δυναστεία κράτησε μέχρι το 63.", "e0d99a55"]},
"OLAYLAR_ANTIK_AKDENIZ:-0303-01-01:0":{"b": ["Η πολιορκία της Ρόδου από τον Δημήτριο τον Πολιορκητή κατέληξε σε αποτυχία", "dae6f4d6"], "d": ["Τη Ρόδο, που έμεινε στο πλευρό του Πτολεμαίου κατά του Αντιγόνου, ο Δημήτριος το 305 την περικύκλωσε με γιγαντιαίες πολιορκητικές μηχανές· οι Ρόδιοι αντιστάθηκαν ένα χρόνο και το καλοκαίρι του 304 επιτεύχθηκε ειρήνη. Στην πόλη ο Κολοσσός του Θεού του Ήλιου Ηλίου στήθηκε με τα χρήματα αυτής της νίκης.", "013a6951"]},
"OLAYLAR_ANTIK_AKDENIZ:-0305-01-01:0":{"b": ["Στη Σαλαμίνα της Κύπρου ο Δημήτριος νίκησε τον Πτολεμαίο· ο Αντίγονος και ο Δημήτριος πήραν τον τίτλο του βασιλιά", "cc308941"], "d": ["Την άνοιξη του 306 ο Δημήτριος ο Πολιορκητής νίκησε μπροστά στην Κύπρο τον στόλο του Πτολεμαίου και έδωσε την Κύπρο στον Αντίγονο· το καλοκαίρι ο Αντίγονος και ο Δημήτριος πήραν τον τίτλο του βασιλιά και οι άλλοι Διάδοχοι ανέλαβαν σύντομα τον ίδιο τίτλο. Ο Πτολεμαίος ανακατέλαβε την Κύπρο το 294.", "0720c1b6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0308-01-01:0":{"b": ["Ο Λυσίμαχος ίδρυσε τη Λυσιμάχεια: πρωτεύουσα στη Θρακική Χερσόνησο", "83b83160"], "d": ["Ο Λυσίμαχος έκανε πρωτεύουσα του βασιλείου της Θράκης τη Λυσιμάχεια που ίδρυσε στον λαιμό της Χερσονήσου της Καλλίπολης· τα στενά και η διάβαση των Δαρδανελίων συγκεντρώθηκαν στα χέρια του. Η πόλη καταστράφηκε από σεισμό τον 3ο αι. π.Χ.", "8ff0e638"]},
"OLAYLAR_ANTIK_AKDENIZ:-0310-01-01:0":{"b": ["Ειρήνη των Διαδόχων: ο Αντίγονος αναγνωρίστηκε στη διοίκηση της Ασίας, ο Κάσσανδρος της Ευρώπης, ο Πτολεμαίος της Αιγύπτου", "811c80f0"], "d": ["Στην ειρήνη που υπογράφηκε τον Δεκέμβριο του 311, ο Αντίγονος αναγνωρίστηκε διοικητής της Ασίας, ο Κάσσανδρος στρατηγός της Ευρώπης, ο Λυσίμαχος της Θράκης, ο Πτολεμαίος διοικητής της Αιγύπτου και των περιχώρων· πέρασε η αρχή της ελευθερίας των ελληνικών πόλεων. Η Βαβυλώνα του Σελεύκου έμεινε έξω από αυτή την ειρήνη.", "3c9a7c4c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0313-01-01:0":{"b": ["Η Τύρος πέρασε στον Αντίγονο: η Φοινίκη πάρθηκε από τον Πτολεμαίο", "30f78257"], "d": ["Ο Αντίγονος το 315 μπήκε στη Συρία, κατέλαβε τη Φοινίκη και πολιόρκησε την Τύρο· η πόλη έπεσε το 314. Η φοινικική ακτή και η ακτή μέχρι τη Γάζα περιήλθαν στα χέρια του (η Γάζα επιστράφηκε στον Πτολεμαίο το 312 στη Μάχη της Γάζας).", "54b4c2dc"]},
"OLAYLAR_ANTIK_AKDENIZ:-0314-01-01:0":{"b": ["Ο Κάσσανδρος ίδρυσε τη Θεσσαλονίκη", "7043bd8a"], "d": ["Ο Κάσσανδρος, ενώνοντας περισσότερους από είκοσι οικισμούς βόρεια του Θερμαϊκού κόλπου, ίδρυσε πόλη στο όνομα της συζύγου του (κόρης του Φιλίππου Β΄) Θεσσαλονίκης. Η Θεσσαλονίκη έγινε το σημαντικότερο λιμάνι της Μακεδονίας για τα επόμενα χίλια χρόνια.", "b6a8e171"]},
"OLAYLAR_ANTIK_AKDENIZ:-0315-01-01:0":{"b": ["Ο Κάσσανδρος έβαλε να ξαναϊδρυθούν οι Θήβες", "0167e784"], "d": ["Οι Θήβες, που είχε καταστρέψει ο Αλέξανδρος, με την υποστήριξη του Κασσάνδρου και τη βοήθεια από την Αθήνα και την Εύβοια, επισκευάστηκαν τα τείχη τους και ξαναιδρύθηκαν. Εξασφαλίστηκε ξανά κέντρο για τη Βοιωτική Συμπολιτεία.", "8f93a07f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0315-01-01:1":{"b": ["Γαβιηνή: ο Αντίγονος νίκησε τον Ευμένη και έγινε κυρίαρχος της Ασίας μέχρι το Ιράν", "d2990dfd"], "d": ["Τον χειμώνα του 316/5 στη Γαβιηνή ο στρατός του Ευμένη διαλύθηκε, ο διοικητής του παραδόθηκε από τους δικούς του στρατιώτες στον Αντίγονο και εκτελέστηκε. Ο Αντίγονος έγινε ο μοναδικός κυρίαρχος μιας εκτεταμένης περιοχής από το περσικό υψίπεδο μέχρι την Ανατολία· ο Σέλευκος διέφυγε στην Αίγυπτο.", "afa9a54f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0319-01-01:0":{"b": ["Ρύθμιση της Τριπαραδείσου: ο Αντίγονος ο Μονόφθαλμος έγινε στρατηγός της Ασίας", "69f6fafb"], "d": ["Μετά τη δολοφονία του Περδίκκα στην Αίγυπτο (Μάιος 320), ο Αντίπατρος στην Τριπαράδεισο ξαναμοίρασε τις σατραπείες· ο Αντίγονος τοποθετήθηκε επικεφαλής των δυνάμεων της Ασίας, ο Σέλευκος κατέλαβε τη Βαβυλώνα. Ο Αντίγονος από αυτή τη θέση επιχείρησε να ιδρύσει δική του αυτοκρατορία.", "17f6bc6b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0321-09-05:0":{"b": ["Κραννών: ο Λαμιακός Πόλεμος χάθηκε· μακεδονική φρουρά μπήκε στην Αθήνα, η δημοκρατία ανεστάλη", "6931c4f6"], "d": ["Στις 5 Σεπτεμβρίου του 322 στο Κραννών η ελληνική συμμαχία ηττήθηκε από τον Αντίπατρο και τον Κρατερό· η Αθήνα δέχτηκε να δεχτεί μακεδονική φρουρά στη Μουνυχία και να περιορίσει το κριτήριο της ιθαγένειας στους ιδιοκτήτες περιουσίας. Ο Δημοσθένης αυτοκτόνησε· η κλασική αθηναϊκή δημοκρατία έληξε στην πράξη.", "ee0f58da"]},
"OLAYLAR_ANTIK_AKDENIZ:-0322-01-01:0":{"b": ["Λαμιακός Πόλεμος: οι ελληνικές πόλεις εξεγέρθηκαν κατά της μακεδονικής ηγεμονίας μετά τον θάνατο του Αλεξάνδρου", "c31c7da4"], "d": ["Με την είδηση του θανάτου του Αλεξάνδρου (Ιούνιος 323), η Αθήνα και η Αιτωλική Συμπολιτεία εξεγέρθηκαν κατά του Αντιπάτρου· ο Αντίπατρος πολιορκήθηκε στη Λαμία. Ο πόλεμος έληξε με μακεδονική νίκη στο Κραννών (Σεπτέμβριος 322), η μακεδονική υπεροχή στο πλαίσιο της Συμμαχίας της Κορίνθου αποκαταστάθηκε.", "57d15260"]},
"OLAYLAR_ANTIK_AKDENIZ:-0325-01-01:0":{"b": ["Υδάσπης: ο Πώρος ηττήθηκε· το Παντζάμπ εξαρτήθηκε από τον Αλέξανδρο", "abab206b"], "d": ["Τον Μάιο του 326, με την υποστήριξη του ράτζα της Ταξίλα Άμπι, ο Αλέξανδρος πέρασε τον Jhelum και νίκησε τον Πώρο· το βασίλειο του Πώρου αφέθηκε στον Αλέξανδρο ως υποτελές. Ο Αλέξανδρος από αυτό το σημείο προχώρησε ανατολικά αλλά σταμάτησε στον Ύφασι με την αντίδραση του στρατού.", "b8f65fb3"]},
"OLAYLAR_ANTIK_AKDENIZ:-0325-01-01:1":{"b": ["Στις όχθες του Υφάσι (Μπέας) ο στρατός αρνήθηκε να προχωρήσει: το ανατολικό σύνορο του Αλεξάνδρου", "17b23afc"], "d": ["Λόγω των μουσώνων και της κούρασης, ο μακεδονικός στρατός αρνήθηκε να περάσει πέρα από τον Ύφασι· ο Αλέξανδρος έστησε δώδεκα βωμούς και αναγκάστηκε να επιστρέψει. Ο Ύφασις έγινε το ανατολικό άκρο των μακεδονικών κατακτήσεων στην Ινδία.", "14c7c1e0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0326-01-01:0":{"b": ["Η Βακτριανή και η Σογδιανή υποτάχθηκαν στον Αλέξανδρο· ο Αλέξανδρος παντρεύτηκε τη Ρωξάνη", "a050508d"], "d": ["Μεταξύ 329-327 η περιοχή πέρα από τον Όξο καταλήφθηκε με έντονο ανταρτικό αγώνα· ο Σπιταμένης σκοτώθηκε, ο Βράχος της Σογδιανής και το κάστρο του Χοριηνή παραδόθηκαν. Ο Αλέξανδρος, παντρευόμενος τη βακτριανή πριγκίπισσα Ρωξάνη, έδεσε τους ντόπιους ευγενείς στη διοίκηση.", "918611e2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0333-01-01:0":{"b": ["Η ακτή της Δυτικής Ανατολίας πέρασε στον Αλέξανδρο: Έφεσος, Μίλητος και Αλικαρνασσός", "f67084a4"], "d": ["Η Έφεσος με δημοκρατικό καθεστώς άνοιξε τις πύλες, η Μίλητος καταλήφθηκε στο τέλος της πολιορκίας (καλοκαίρι 334)· η πολιορκία της Αλικαρνασσού κατέληξε το φθινόπωρο στην πτώση της πόλης και η σατραπεία της Καρίας δόθηκε στην Άδα. Ο Αλέξανδρος έτσι εφάρμοσε τη στρατηγική κατάληψης από ξηρά των λιμανιών του περσικού στόλου.", "8ad1fb18"]},
"OLAYLAR_ANTIK_AKDENIZ:-0334-01-01:0":{"b": ["Οι Θήβες καταστράφηκαν με διαταγή του Αλεξάνδρου", "26c4193c"], "d": ["Τις Θήβες, που εξεγέρθηκαν με τον θάνατο του Φιλίππου, ο Αλέξανδρος τις κατέλαβε το φθινόπωρο· έβαλε μακεδονική φρουρά στην Καδμεία, έβαλε να καταστραφεί η πόλη και σκλάβωσε τον λαό (εκτός από το σπίτι του Πινδάρου). Η Βοιωτική Συμπολιτεία έληξε στην πράξη με αυτή την καταστροφή (το 316 την ξανάφτιαξε ο Κάσσανδρος).", "1aac0f0a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0335-01-01:0":{"b": ["Ο Φίλιππος Β΄ δολοφονήθηκε στις Αιγές· ο Αλέξανδρος ανέβηκε στον θρόνο", "417d909e"], "d": ["Στη θέση του Φιλίππου, που σκοτώθηκε στο θέατρο, στη γιορτή του γάμου της κόρης του Κλεοπάτρας, από τον σωματοφύλακά του Παυσανία, ο γιος του Αλέξανδρος ανακηρύχθηκε βασιλιάς από τον στρατό. Η εκστρατεία κατά των Περσών και ο έλεγχος της Ελλάδας έμειναν στον Αλέξανδρο.", "29a2af26"]},
"OLAYLAR_ANTIK_AKDENIZ:-0337-01-01:0":{"b": ["Ιδρύθηκε η Συμμαχία της Κορίνθου: οι ελληνικές πόλεις ενώθηκαν υπό την ηγεμονία του Φιλίππου Β΄", "c38074dc"], "d": ["Μετά τη Χαιρώνεια ο Φίλιππος συγκέντρωσε τις ελληνικές πόλεις στην Κόρινθο υπό κοινή ειρήνη (koine eirene) και κοινό αμυντικό όρκο· αποφασίστηκαν στρατός και διοίκηση ηγεμόνα για εκστρατεία κατά των Περσών. Μόνο η Σπάρτη δεν συμμετείχε.", "753c39e6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0337-01-01:1":{"b": ["Χαιρώνεια: ο Φίλιππος νίκησε τον αθηναϊκό και θηβαϊκό στρατό και ανέλαβε τον έλεγχο της Ελλάδας", "5e5d77e7"], "d": ["Τον Αύγουστο του 338 στην πεδιάδα της Χαιρώνειας, με την επίθεση του ιππικού που διοικούσε ο νεαρός Αλέξανδρος, ο στρατός Αθηναίων–Θηβαίων διαλύθηκε· στις Θήβες τοποθετήθηκε μακεδονική φρουρά, η Αθήνα συγχωρέθηκε με ανεκτικότητα. Η νίκη έβαλε τέλος στην ανεξαρτησία των ελληνικών πόλεων και άνοιξε τον δρόμο προς τη Συμμαχία της Κορίνθου.", "b2f75989"]},
"OLAYLAR_ANTIK_AKDENIZ:-0337-01-01:2":{"b": ["Η Λατινική Συμμαχία διαλύθηκε: το Λάτιο προσαρτήθηκε στη Ρώμη", "58849f84"], "d": ["Στο τέλος του Λατινικού Πολέμου (340-338) η Ρώμη διέλυσε τη Λατινική Συμμαχία· οι πόλεις είτε προσχώρησαν στη ρωμαϊκή ιθαγένεια είτε προσαρτήθηκαν μία-μία στη Ρώμη, η συμμαχία μεταξύ τους απαγορεύτηκε. Αυτό είναι το θεμέλιο του μοντέλου επέκτασης της Ρώμης στην Ιταλία.", "5ebbdf2e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0338-01-01:0":{"b": ["Ο Φίλιππος Β΄ νίκησε τον βασιλιά των Σκυθών Άτεα", "e4dee658"], "d": ["Ο πόλεμος του βασιλιά Άτεα με τον Φίλιππο στις όχθες του Ίστρου (Δούναβη) έληξε με τον θάνατο του Άτεα· ο Φίλιππος κατά την επιστροφή δέχτηκε επίθεση από τους Τριβαλλούς. Η σκυθική δύναμη μετατοπίστηκε πέρα από τον Δούναβη προς τα δυτικά.", "29f62ac6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0340-01-01:0":{"b": ["Ο Φίλιππος υπέταξε τη Θράκη μαζί με τη δυναστεία των Οδρυσών", "b543427a"], "d": ["Ο Φίλιππος στις εκστρατείες του 342-341 π.Χ. προχώρησε στο εσωτερικό της Θράκης, έκανε φορολογούμενο τον βασιλιά των Οδρυσών Κερσοβλέπτη και ίδρυσε πόλεις όπως η Φιλιππούπολη (Φιλιππούπολη/Πλόβντιβ). Η Θράκη έγινε ανατολική επέκταση της Μακεδονίας.", "82201f3c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0347-01-01:0":{"b": ["Η καταστροφή της Ολύνθου: η Χαλκιδική Συμμαχία πέρασε στη Μακεδονία", "89d77301"], "d": ["Παρά το γεγονός ότι η Όλυνθος ζήτησε βοήθεια από την Αθήνα, ο Φίλιππος κατέλαβε την πόλη με προδοσία και την κατέστρεψε· η χερσόνησος της Χαλκιδικής προσαρτήθηκε στη Μακεδονία. Οι λόγοι του Δημοσθένη Ολυνθιακοί βασίζονται σε αυτή την έκκληση.", "c69e91c8"]},
"OLAYLAR_ANTIK_AKDENIZ:-0354-01-01:0":{"b": ["Ο Συμμαχικός Πόλεμος έληξε: το Βυζάντιο, η Χίος, η Ρόδος και η Κως αποχώρησαν από τη Β΄ Αθηναϊκή Συμμαχία", "856a9763"], "d": ["Η εξέγερση που άρχισε το 357 π.Χ. έληξε με την ήττα των Αθηναίων διοικητών στη Χίο και την αντίθεση της περσικής υποστήριξης προς την Αθήνα, και η Αθήνα δέχτηκε ειρήνη· τέσσερα σημαντικά μέλη κέρδισαν την ανεξαρτησία τους. Η συμμαχία αποδυναμώθηκε και έμεινε ανυπεράσπιστη μπροστά στη Μακεδονία.", "170647af"]},
"OLAYLAR_ANTIK_AKDENIZ:-0356-01-01:0":{"b": ["Ο Φίλιππος πήρε την Αμφίπολη από την Αθήνα", "2c793bc6"], "d": ["Ο Φίλιππος, που πολιόρκησε και κατέλαβε την Αμφίπολη της Αθήνας στις εκβολές του Στρυμόνα, βλέποντας ότι απέκτησε πρόσβαση στα χρυσά-αργυρά μεταλλεία και στις πηγές ξυλείας της πόλης, άνοιξε προς τη θρακική ακτή. Η κατάκτηση αυτή άρχισε τη σύγκρουση Αθήνας–Μακεδονίας.", "731bf35a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0358-01-01:0":{"b": ["Ο Φίλιππος Β΄ έγινε βασιλιάς της Μακεδονίας", "d557268d"], "d": ["Με τον θάνατο του Περδίκκα Γ΄ στον πόλεμο με τους Ιλλυριούς (360/359 π.Χ.), ο Φίλιππος έγινε πρώτα αντιπρόσωπος, έπειτα βασιλιάς· αποκρούοντας τις απειλές της Ιλλυρίας, της Παιονίας και της Θράκης, έκανε τη μεταρρύθμιση του στρατού (φάλαγγα σάρισσας). Η άνοδος της Μακεδονίας αρχίζει με αυτή τη βασιλεία.", "417218f0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0361-01-01:0":{"b": ["Μαντίνεια: ο Επαμεινώνδας πέθανε, η βοιωτική ηγεμονία έληξε", "94be8d5c"], "d": ["Ο θηβαϊκός στρατός κέρδισε τη μάχη αλλά ο Επαμεινώνδας τραυματίστηκε και πέθανε· ο Ξενοφών κλείνει με «αβεβαιότητα και αναταραχή στην Ελλάδα περισσότερη από πριν». Η σύντομη ηγεμονία των Θηβών έληξε το ίδιο έτος, η ισορροπία Αθήνας–Σπάρτης–Θηβών διατηρήθηκε.", "42ad0729"]},
"OLAYLAR_ANTIK_AKDENIZ:-0368-01-01:0":{"b": ["Ιδρύθηκε η Αρκαδική Συμπολιτεία: αυτό το τμήμα της Πελοποννησιακής Συμμαχίας διαλύθηκε", "42fdc676"], "d": ["Μετά τα Λεύκτρα οι αρκαδικές πόλεις με τη θηβαϊκή υποστήριξη ίδρυσαν ομοσπονδιακή συμπολιτεία και έχτισαν τη νέα πρωτεύουσα Μεγαλόπολη. Έτσι η Πελοποννησιακή Συμμαχία της Σπάρτης διαλύθηκε στην πράξη· η Σπάρτη αποσύρθηκε μόνο στη Λακωνία.", "4cf7dd83"]},
"OLAYLAR_ANTIK_AKDENIZ:-0369-01-01:0":{"b": ["Η Μεσσηνία αποχωρίστηκε από τη Σπάρτη· ιδρύθηκε η Μεσσήνη", "e4ef9302"], "d": ["Στην εκστρατεία του Επαμεινώνδα στην Πελοπόννησο μετά τα Λεύκτρα (χειμώνας 370/69) οι είλωτες της Μεσσηνίας απελευθερώθηκαν και ιδρύθηκε στους πρόποδες του όρους Ιθώμη η ισχυρά τειχισμένη πόλη Μεσσήνη. Η Σπάρτη έχασε για πρώτη φορά μετά από αιώνες τα εδάφη της Μεσσηνίας που αποτελούσαν την οικονομική της βάση.", "fe6af875"]},
"OLAYLAR_ANTIK_AKDENIZ:-0370-01-01:0":{"b": ["Λεύκτρα: ο θηβαϊκός στρατός νίκησε τους Σπαρτιάτες· η Σπάρτη έχασε την υπεροχή στη ξηρά", "e7829597"], "d": ["Η βαθιά διάταξη συμπύκνωσης του δεξιού πλευρού του Επαμεινώνδα διέλυσε στα Λεύκτρα τη σπαρτιατική δύναμη του βασιλιά Κλεόμβροτου· με τον θάνατο περίπου 400 Σπαρτιατών, η Σπάρτη δεν μπορούσε πλέον να αναπληρώσει την απώλεια πληθυσμού. Άρχισε περίοδος ηγεμονίας υπό τις Θήβες.", "41f8774e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0376-01-01:0":{"b": ["Ιδρύθηκε η Β΄ Αθηναϊκή Συμμαχία (ψήφισμα του Αριστοτέλη)", "0e5dcaf2"], "d": ["Η Αθήνα κάλεσε τις πόλεις του Αιγαίου στη συμμαχία κατά της Σπάρτης με την αρχή της αυτονομίας και της μη είσπραξης φόρου· το ψήφισμα εκδόθηκε με πρόταση του Αριστοτέλη και ο κατάλογος των μελών-πόλεων γράφτηκε σε πέτρα. Η ίδρυση της συμμαχίας έκανε ξανά την Αθήνα ναυτική δύναμη.", "20a9657f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0378-01-01:0":{"b": ["Ο Πελοπίδας απελευθέρωσε τις Θήβες· η σπαρτιατική φρουρά διώχθηκε από την Καδμεία", "eb15a9d7"], "d": ["Η Καδμεία των Θηβών, που η Σπάρτη είχε καταλάβει και όπου είχε αφήσει φρουρά το 382 π.Χ., ανακαταλήφθηκε με νυχτερινή επιδρομή των εξορίστων· οι Θήβες έγιναν ξανά το κέντρο της Βοιωτικής Συμπολιτείας. Το γεγονός είναι η αρχή της διάλυσης της σπαρτιατικής ηγεμονίας.", "4cd862c2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0388-01-01:0":{"b": ["Αλλία: οι Γαλάτες νίκησαν τον ρωμαϊκό στρατό και λεηλάτησαν την πόλη", "db864bc9"], "d": ["Στις όχθες της Αλλίας, παραπόταμου του Τίβερη, οι Γαλάτες Σένονες διέλυσαν τον ρωμαϊκό στρατό· η Ρώμη κατελήφθη εκτός του Καπιτωλίου και λεηλατήθηκε. Ο Λίβιος γράφει ότι η «ημέρα της Αλλίας» (18 Ιουλίου) θεωρήθηκε αποφράδα για τους Ρωμαίους.", "7babd2e7"]},
"OLAYLAR_ANTIK_AKDENIZ:-0391-01-01:0":{"b": ["Η Κόρινθος ενώθηκε με το Άργος (ισοπολιτεία Άργους–Κορίνθου)", "135a3d3a"], "d": ["Κατά τον Κορινθιακό Πόλεμο (395-387 π.Χ.) η Κόρινθος ίδρυσε με το Άργος κοινή ένωση πολιτείας· η αργειακή φρουρά παρέμεινε στην Κόρινθο. Η Σπάρτη με την Ειρήνη του Βασιλέως (386) έκανε να διαλυθεί αυτή η ένωση.", "9f979507"]},
"OLAYLAR_ANTIK_AKDENIZ:-0395-01-01:0":{"b": ["Οι Βηίοι (Veii) έπεσαν στη Ρώμη: χάθηκε η πρώτη μεγάλη πόλη της Ετρουρίας στον νότο", "0d1c4fe4"], "d": ["Μετά από δεκαετή πολιορκία ο Camillus κατέλαβε τους Veii (κατά την παράδοση 396 π.Χ.)· ο λαός τους υποδουλώθηκε, τα εδάφη προσαρτήθηκαν στη Ρώμη και το ager Romanus της Ρώμης σχεδόν διπλασιάστηκε. Η ισχύς των ετρουσκικών πόλεων νότια του Τίβερη κάμφθηκε.", "7571ce55"]},
"OLAYLAR_ANTIK_AKDENIZ:-0403-01-01:0":{"b": ["Η Αθήνα παραδόθηκε στη Σπάρτη· η αθηναϊκή ναυτική αυτοκρατορία και η Δηλιακή Συμμαχία έληξαν", "43f2ddf9"], "d": ["Η Αθήνα, που έχασε τον στόλο της στους Αιγός Ποταμούς, παραδόθηκε από την πείνα· τα Μακρά Τείχη κατεδαφίστηκαν, η ναυτική αυτοκρατορία διαλύθηκε, στην πόλη ήρθε η διοίκηση των Τριάκοντα που ίδρυσαν οι Σπαρτιάτες. Στα νησιά, πρώην μέλη της Συμμαχίας, και στις ακτές της Θράκης εγκαταστάθηκαν οι δεκαρχίες που ίδρυσε ο Λύσανδρος και σπαρτιατικές φρουρές.", "3d808acd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0404-01-01:0":{"b": ["Ο Διονύσιος Α' έγινε τύραννος στις Συρακούσες", "1ad10305"], "d": ["Την εποχή που η Καρχηδόνα κατέλαβε τον Ακράγαντα και τη Γέλα, ο Διονύσιος έγινε το 405 στρατηγός και στη συνέχεια τύραννος των Συρακουσών· έκανε ειρήνη με την Καρχηδόνα (405) και υπέταξε τις ελληνικές πόλεις της Σικελίας. Η εξουσία του Διονυσίου, που θα διαρκέσει 38 χρόνια, έκανε τη Σικελία μία από τις μεγάλες δυνάμεις της Μεσογείου.", "3068782f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0404-01-01:1":{"b": ["Αιγός Ποταμοί: ο αθηναϊκός στόλος καταστράφηκε· η Δηλιακή Συμμαχία έφτασε στο χείλος της κατάρρευσης", "ce62187c"], "d": ["Τον Σεπτέμβριο του 405 ο Λύσανδρος, με αιφνιδιαστική επίθεση, κατέλαβε τον αθηναϊκό στόλο που ήταν αγκυροβολημένος στους Αιγός Ποταμούς· χάθηκε σχεδόν ολόκληρος ο στόλος και χιλιάδες αιχμάλωτοι. Ο δρόμος του Ελλησπόντου έκλεισε και ο ανεφοδιασμός της Αθήνας σε σιτηρά διακόπηκε· λίγους μήνες αργότερα η Αθήνα παραδόθηκε.", "d42a037e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0407-01-01:0":{"b": ["Ιδρύθηκε η πόλη της Ρόδου: η Λίνδος, η Ιαλυσός και η Κάμειρος ενώθηκαν", "2de55901"], "d": ["Το 408 π.Χ. οι τρεις πόλεις του νησιού της Ρόδου ίδρυσαν κοινό κράτος και ενώθηκαν στη νέα πόλη της Ρόδου· η πόλη, που χτίστηκε με το σχέδιο του Ιππόδαμου, έγινε μία από τις σημαντικότερες ναυτικές βάσεις και εμπορικά κέντρα του ελληνιστικού κόσμου.", "0db6207d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0408-01-01:0":{"b": ["Ο Αννίβας Μάγων κατέστρεψε τον Σελινούντα και την Ιμέρα: η Καρχηδόνα εγκαταστάθηκε στη δυτική Σικελία", "358f4417"], "d": ["Ο Αννίβας Μάγων, που αποβιβάστηκε στη Σικελία με έκκληση βοήθειας της Έγεστας, κατέλαβε το 409 π.Χ. τον Σελινούντα και την Ιμέρα· η περιοχή έγινε επικράτεια (epikratia) της Καρχηδόνας. Η σύγκρουση Καρχηδόνας–Συρακουσών διήρκεσε δύο αιώνες.", "58abf6b5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0412-01-01:0":{"b": ["Η Σικελική Εκστρατεία έληξε με καταστροφή: ο αθηναϊκός στρατός εξοντώθηκε μπροστά στις Συρακούσες", "b363df0d"], "d": ["Η Σικελική Εκστρατεία που ξεκίνησε η Αθήνα το 415 π.Χ., μετά την αδυναμία πολιορκίας των Συρακουσών, κατέληξε στην υποχώρηση του Νικία και του Δημοσθένη με παράδοση στις όχθες του ποταμού Ασσίναρου (φθινόπωρο 413 π.Χ.). Η Αθήνα έχασε τον στρατό της και το μεγαλύτερο μέρος του στόλου της.", "2d1f3d05"]},
"OLAYLAR_ANTIK_AKDENIZ:-0429-01-01:0":{"b": ["Ο Σιτάλκης συμμάχησε με την Αθήνα: το Οδρυσικό Βασίλειο συμμετείχε στον Πελοποννησιακό Πόλεμο", "4562f13d"], "d": ["Η Αθήνα έκανε τον γιο του Σιτάλκη Αθηναίο πολίτη και έκανε συμμαχία μαζί του· ο Σιτάλκης επιτέθηκε το 429 στη Μακεδονία. Η οδρυσική ισχύς έφτασε σε αποκορύφωμα αυτή την περίοδο.", "64e00572"]},
"OLAYLAR_ANTIK_AKDENIZ:-0430-01-01:0":{"b": ["Ξεκίνησε ο Πελοποννησιακός Πόλεμος: η Πελοποννησιακή Συμμαχία κινητοποιήθηκε εναντίον της Αθήνας", "2adee4a1"], "d": ["Με τη νυχτερινή επίθεση των Θηβών στις Πλαταιές (άνοιξη 431), η ειρήνη διαταράχθηκε στην πράξη· στις αρχές του καλοκαιριού ο στρατός της Πελοποννησιακής Συμμαχίας υπό τον βασιλιά Αρχίδαμο εισέβαλε στην Αττική. Ο πόλεμος διήρκεσε 27 χρόνια ανάμεσα στη ναυτική αυτοκρατορία της Αθήνας και στην ηπειρωτική συμμαχία της Σπάρτης.", "6d950c3b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0432-01-01:0":{"b": ["Σύβοτα: ο πόλεμος Κορίνθου–Κέρκυρας παρέσυρε την Αθήνα σε επέμβαση", "dc07b0ac"], "d": ["Στη ναυμαχία που έκανε η Κόρινθος με την αποικία της Κέρκυρα λόγω της Επιδάμνου, η Αθήνα υποστήριξε την Κέρκυρα. Η οργή της Κορίνθου προς την Αθήνα έγινε μία από τις άμεσες αιτίες του Πελοποννησιακού Πολέμου.", "f4639e4c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0437-01-01:0":{"b": ["Ο Σπάρτοκος έγινε άρχοντας στον Βόσπορο: δυναστεία των Σπαρτοκιδών", "ddc76f79"], "d": ["Τη δυναστεία των Αρχεανακτιδών στην Παντικάπαιον αντικατέστησε ο Σπάρτοκος θρακικής καταγωγής (438/7)· η δυναστεία των Σπαρτοκιδών ίδρυσε το βασίλειο του Βοσπόρου και διαχειριζόταν την εξαγωγή σιτηρών στην Αθήνα. Η δυναστεία διήρκεσε μέχρι το 109 π.Χ.", "36cf3454"]},
"OLAYLAR_ANTIK_AKDENIZ:-0445-01-01:0":{"b": ["Τριακονταετείς Σπονδές: η Αθήνα έχασε την ηπειρωτική αυτοκρατορία της (Βοιωτία, Μέγαρα, Αχαΐα)", "4f33ff13"], "d": ["Μετά τη νίκη των Βοιωτών επί του αθηναϊκού στρατού στην Κορώνεια (447), στη συνέχεια τις εξεγέρσεις της Εύβοιας και των Μεγάρων και την εισβολή της Σπάρτης στην Αττική, η Αθήνα υπέγραψε τις Τριακονταετείς Σπονδές. Η Αθήνα άφησε τα Μέγαρα, τη Νίσαια, τις Πηγές και την Τροιζήνα και την Αχαΐα στην Πελοπόννησο· κράτησε μόνο τη ναυτική της αυτοκρατορία.", "fc720780"]},
"OLAYLAR_ANTIK_AKDENIZ:-0449-01-01:0":{"b": ["Ο Τήρης ίδρυσε το Οδρυσικό βασίλειο: το πρώτο μεγάλο κράτος της Θράκης", "83caf189"], "d": ["Ο Θουκυδίδης γράφει ότι ο Τήρης ίδρυσε το πρώτο μεγάλο βασίλειο στη Θράκη· ο γιος του Σιτάλκης έφερε το βασίλειο από τον Δούναβη έως το Αιγαίο. Το οδρυσικό βασίλειο ακολούθησε πολιτική ισορροπίας ανάμεσα στην Αθήνα, στη Μακεδονία και στους Πέρσες.", "442e0b64"]},
"OLAYLAR_ANTIK_AKDENIZ:-0453-01-01:0":{"b": ["Το ταμείο της Συμμαχίας μεταφέρθηκε από τη Δήλο στην Αθήνα", "173f2e5b"], "d": ["Με αιτιολογία την ήττα στην εκστρατεία της Αιγύπτου και τον φόβο του περσικού στόλου, το κοινό ταμείο μεταφέρθηκε από τη Δήλο στην Αθήνα· οι κατάλογοι του «ενός εξηκοστού» που δινόταν στη θεά Αθηνά ξεκινούν από αυτή τη χρονιά. Το βήμα αυτό ερμηνεύεται ως ένδειξη ότι η Συμμαχία στην πράξη μετατράπηκε σε αθηναϊκή αυτοκρατορία.", "c7c6b1db"]},
"OLAYLAR_ANTIK_AKDENIZ:-0462-01-01:0":{"b": ["Η εξέγερση της Θάσου καταπνίγηκε· η Δηλιακή Συμμαχία μετατράπηκε σε αυτοκρατορία από την οποία τα μέλη δεν μπορούσαν να αποχωρήσουν", "d24bd124"], "d": ["Η Θάσος, λόγω των μεταλλείων, συγκρούστηκε με την Αθήνα και επιχείρησε να αποχωρήσει από τη συμμαχία· μετά από διετή πολιορκία (463 π.Χ.) κατέστρεψε τα τείχη της, παρέδωσε τον στόλο της και έχασε την περιοχή των ορυχείων στη θρακική ακτή. Το γεγονός είναι το πρώτο προηγούμενο που δείχνει ότι η συμμετοχή στη Συμμαχία δεν μπορούσε να εγκαταλειφθεί.", "eb9beb44"]},
"OLAYLAR_ANTIK_AKDENIZ:-0473-01-01:0":{"b": ["Ναυμαχία της Κύμης (Cumae): οι Συρακούσες νίκησαν τον ετρουσκικό στόλο, η ετρουσκική ναυτική ισχύς κάμφθηκε", "2e81670b"], "d": ["Με έκκληση βοήθειας της Κύμης, ο τύραννος των Συρακουσών Ιέρων Α' κατατρόπωσε τον ετρουσκικό στόλο μπροστά στην Κύμη· ο Ιέρων γιόρτασε τη νίκη προσφέροντας κράνος στους Δελφούς (το ετρουσκικό κράνος που αναφέρει ο Λίβιος). Η ετρουσκική κυριαρχία στην Καμπανία κλονίστηκε.", "db3832ad"]},
"OLAYLAR_ANTIK_AKDENIZ:-0477-01-01:0":{"b": ["Ιδρύθηκε η Δηλιακή Συμμαχία: αιγαιακή συμμαχία υπό την αθηναϊκή ηγεσία", "f0de153a"], "d": ["Μετά το ύφος διοίκησης του Παυσανία, οι ιωνικές πόλεις ζήτησαν ηγεσία από την Αθήνα· με φόρο που καθόρισε ο Αριστείδης (460 τάλαντα) ιδρύθηκε κοινό ταμείο στη Δήλο. Η Συμμαχία εξασφάλισε στην Αθήνα μόνιμο στόλο και φορολογική βάση στο Αιγαίο.", "bb661e1d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0478-01-01:0":{"b": ["Σαλαμίνα (29 Σεπτεμβρίου 480) και Πλαταιές: η περσική εισβολή αποκρούστηκε", "479b17e6"], "d": ["Αφού ο Ξέρξης κατέλαβε και έκαψε την Αθήνα, με την παγίδα του Θεμιστοκλή ο περσικός στόλος κατατροπώθηκε στο στενό της Σαλαμίνας (29 Σεπτεμβρίου 480)· την επόμενη χρονιά στις Πλαταιές ο ελληνικός χερσαίος στρατός υπό τον Παυσανία νίκησε τον Μαρδόνιο και έβαλε τέλος στην εισβολή. Έτσι η Ελλάδα του Αιγαίου απαλλάχθηκε από την περσική κυριαρχία.", "dd5f48b5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0479-01-01:0":{"b": ["Ιμέρα: οι Έλληνες της Σικελίας νίκησαν τον καρχηδονιακό στρατό", "ece09580"], "d": ["Η συμμαχία του Γέλωνα και του Θήρωνα κατατρόπωσε μπροστά στην Ιμέρα τον καρχηδονιακό στρατό του Αμίλκα· η Καρχηδόνα για μισό αιώνα δεν μπόρεσε να κάνει ξανά μεγάλη εκστρατεία στη Σικελία. Σύμφωνα με τον Ηρόδοτο και τον Διόδωρο, την ίδια ημέρα κερδήθηκε η Σαλαμίνα (παράδοση).", "1706c09a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0489-01-01:0":{"b": ["Μαραθώνας: η Αθήνα σταμάτησε την περσική επιδρομή", "0967ce7c"], "d": ["Οι οπλίτες της Αθήνας και των Πλαταιών υπό τον Μιλτιάδη νίκησαν την περσική δύναμη στην πεδιάδα του Μαραθώνα και εμπόδισαν την απόβαση στην Αττική. Η νίκη τροφοδότησε την αυτοπεποίθηση της αθηναϊκής δημοκρατίας και τη ναυτική πολιτική που έφτασε στη Δηλιακή Συμμαχία.", "1b107bcd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0490-01-01:0":{"b": ["Ο Μαρδόνιος υπέταξε τη Μακεδονία στους Πέρσες", "7bde569c"], "d": ["Ο Μαρδόνιος, γαμπρός του Δαρείου, πέρασε τη Θράκη και έθεσε τη Μακεδονία υπό περσική κυριαρχία· ο βασιλιάς της Μακεδονίας έδωσε στους Πέρσες γη και ύδωρ. Η Μακεδονία απέβαλε αυτή την εξάρτηση μετά τις Πλαταιές (479).", "04f10eac"]},
"OLAYLAR_ANTIK_AKDENIZ:-0492-01-01:0":{"b": ["Foedus Cassianum: η Ρώμη συμμάχησε με τη Λατινική Συμμαχία", "56db407d"], "d": ["Με τη συνθήκη που φέρει το όνομα του Spurius Cassius, η Ρώμη και η Λατινική Συμμαχία συνήψαν συμμαχία με βάση την αμοιβαία άμυνα, τη διανομή των λαφύρων και τον κοινό στρατό. Η συνθήκη αυτή είναι το πλαίσιο των σχέσεων Ρώμης-Λατίου μέχρι τον Λατινικό Πόλεμο (340-338).", "cb723394"]},
"OLAYLAR_ANTIK_AKDENIZ:-0504-01-01:0":{"b": ["Με την αποχώρηση της Κορίνθου, η εκστρατεία της Πελοποννησιακής Συμμαχίας εναντίον της Αθήνας διαλύθηκε", "b44adf6b"], "d": ["Η Σπάρτη οδήγησε τον στρατό της Πελοποννησιακής Συμμαχίας στην Αττική εναντίον της δημοκρατικής Αθήνας του Κλεισθένη· η αποχώρηση του κορινθιακού στρατού στην Ελευσίνα και η διαφωνία των δύο βασιλέων της Σπάρτης κατέρριψαν την εκστρατεία. Το γεγονός θεωρείται το πρώτο γνωστό παράδειγμα όπου το δικαίωμα ψήφου των συμμάχων στη συνέλευση της συμμαχίας άρχισε να λειτουργεί.", "f54c0949"]},
"OLAYLAR_ANTIK_AKDENIZ:-0507-01-01:0":{"b": ["Μεταρρύθμιση του Κλεισθένη: τέθηκε το θεσμικό θεμέλιο της αθηναϊκής δημοκρατίας", "b2421c86"], "d": ["Μετά την πτώση του Ιππία, ο Κλεισθένης οργάνωσε τους πολίτες με βάση τους δήμους, που ήταν οι μονάδες κατοικίας, και δέκα νέες φυλές· η Βουλή των Πεντακοσίων έγινε το κέντρο αυτής της τάξης. Είναι η ρύθμιση όπου γεννήθηκαν οι έννοιες ισονομία/δημοκρατία.", "f3da7080"]},
"OLAYLAR_ANTIK_AKDENIZ:-0508-01-01:0":{"b": ["Ο τελευταίος βασιλιάς Tarquinius Superbus εκδιώχθηκε· η βασιλεία έληξε, ξεκίνησε η Δημοκρατία", "5a4a9061"], "d": ["Σύμφωνα με τον Λίβιο, ο Tarquinius Superbus και η οικογένειά του εκδιώχθηκαν από την πόλη το 509 π.Χ. και εκλέχθηκαν οι πρώτοι ύπατοι (Brutus, Collatinus). Ο Πολύβιος συνδέει την πρώτη συνθήκη Ρώμης-Καρχηδόνας με το έτος των πρώτων υπάτων· η ημερομηνία, αν και στη σύγχρονη ιστοριογραφία θεωρείται «παράδοση», τοποθετείται στο τέλος του 6ου αι. π.Χ.", "b86ee69b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0508-01-01:1":{"b": ["Πρώτη συνθήκη ανάμεσα στη Ρώμη και στην Καρχηδόνα (Πολύβιος 3.22)", "cdef940f"], "d": ["Ο Πολύβιος μεταφέρει με το κείμενό της τη συνθήκη που έγινε ανάμεσα στη Ρώμη και στην Καρχηδόνα το έτος των πρώτων υπάτων και που όριζε τις ακτές του Λατίου στη Ρώμη και διαχώριζε την Καρχηδόνα στη δυτική Σικελία και στη Λιβύη. Η Ρώμη αναφέρεται ως κυρίαρχος του Λατίου.", "d5a9571d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0534-01-01:0":{"b": ["Ναυμαχία της Αλαλίας: οι Ετρούσκοι και οι Καρχηδόνιοι εκδίωξαν τους Φωκαείς από την Κορσική", "25efbea8"], "d": ["Στην Αλαλία οι Φωκαείς Έλληνες κέρδισαν νίκη επί χάρτου αλλά έχασαν το μεγαλύτερο μέρος του στόλου τους· άφησαν την Κορσική και αποσύρθηκαν στην Ελέα της Νότιας Ιταλίας. Στο νησί εγκαταστάθηκε ετρουσκική (Caere) κυριαρχία.", "50ab95a1"]},
"OLAYLAR_ANTIK_AKDENIZ:-0549-01-01:0":{"b": ["Συνθήκη Σπάρτης–Τεγέας: σχηματίστηκε ο πυρήνας της Πελοποννησιακής Συμμαχίας", "57098e47"], "d": ["Η Σπάρτη νίκησε την Τεγέα στην Αρκαδία και την έκανε να δεχθεί αιώνια συμμαχία (symmachia) με αντάλλαγμα να μην καταστρέψει τα εδάφη της· το ίδιο πρότυπο εξαπλώθηκε στις πόλεις της Πελοποννήσου και γεννήθηκε η Πελοποννησιακή Συμμαχία υπό σπαρτιατική ηγεσία. Η Συμμαχία λειτουργούσε εσωτερικά με τη μορφή συνέλευσης Σπάρτης και συμμάχων (υπό σπαρτιατική διοίκηση).", "b9500385"]},
"OLAYLAR_ANTIK_AKDENIZ:-0598-01-01:0":{"b": ["Οι Φωκαείς ίδρυσαν τη Μασσαλία (Marseille)", "5d46bdf2"], "d": ["Οι Φωκαείς άποικοι ίδρυσαν περίπου το 600 π.Χ. τη Μασσαλία στις εκβολές του Ροδανού· η πόλη έγινε κέντρο του ελληνικού εμπορίου στη Δυτική Μεσόγειο και της επαφής με τον κελτικό κόσμο.", "f4a73ff9"]},
"OLAYLAR_ANTIK_AKDENIZ:-0630-01-01:0":{"b": ["Ο Θηραίος Βάττος ίδρυσε την Κυρήνη", "67fd477f"], "d": ["Οι άποικοι που ήρθαν από τη Θήρα, σύμφωνα με χρησμό των Δελφών, ίδρυσαν την Κυρήνη υπό την ηγεσία του Βάττου· η δυναστεία των Βαττιαδών κυβέρνησε μέχρι το 440. Ο Λίβιος δίνει ως ημερομηνία ίδρυσης «περ. 630».", "e51d3a78"]},
"OLAYLAR_ANTIK_AKDENIZ:-0719-01-01:0":{"b": ["Η Σπάρτη κέρδισε τον Πρώτο Μεσσηνιακό Πόλεμο: η Μεσσηνία προσαρτήθηκε στη Σπάρτη", "74ad461c"], "d": ["Στην παράδοση που μεταφέρει ο Παυσανίας, ο Πρώτος Μεσσηνιακός Πόλεμος διήρκεσε είκοσι χρόνια και με την πτώση της Ιθώμης η πεδιάδα της Μεσσηνίας πέρασε στη Σπάρτη· ο λαός υποβιβάστηκε στο καθεστώς των ειλώτων. Η κατάκτηση αυτή θεωρήθηκε το θεμελιώδες γεγονός που καθόρισε τη γεωργική ισχύ και τη στρατιωτική κοινωνία της Σπάρτης.", "2066959e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0732-01-01:0":{"b": ["Οι Συρακούσες ιδρύθηκαν από τον Κορίνθιο Αρχία", "10217104"], "d": ["Σύμφωνα με τον Θουκυδίδη, ένα χρόνο μετά τη Νάξο, ο Κορίνθιος Αρχίας ίδρυσε τις Συρακούσες. Η πόλη έγινε η μεγαλύτερη ελληνική πόλη της Σικελίας.", "e5643a95"]},
"OLAYLAR_ANTIK_AKDENIZ:-0813-01-01:0":{"b": ["Η παραδοσιακή ίδρυση της Καρχηδόνας (Τίμαιος: 814/813 π.Χ.)", "908099b5"], "d": ["Σύμφωνα με τον Τίμαιο, η Καρχηδόνα ιδρύθηκε το 814/813 π.Χ. από αποίκους από την Τύρο· ο Ιουστίνος δίνει 825. Τα αρχαιολογικά στρώματα δείχνουν το τέλος του 8ου αιώνα π.Χ.", "c7e72545"]},
"OLAYLAR_ANTIK_AKDENIZ:-1199-01-01:0":{"b": ["Τα μυκηναϊκά ανακτορικά κέντρα καταστράφηκαν: η ανακτορική τάξη κατέρρευσε στην Πελοπόννησο", "d2c79152"], "d": ["Στο τέλος της Υστεροελλαδικής ΙΙΙΒ / αρχή της ΙΙΙΓ, τα ανακτορικά κέντρα στην Πύλο, στην Τίρυνθα και στις Μυκήνες δίνουν στρώμα καταστροφής ή εγκατάλειψης· η ανακτορική οικονομία που στηριζόταν στη Γραμμική Β τελειώνει. Η αιτία της καταστροφής (σεισμός, εσωτερική σύγκρουση, Λαοί της Θάλασσας, ξηρασία) είναι αμφισβητούμενη· τα στρώματα καταστροφής εκτείνονται όχι σε ένα έτος αλλά σε λίγες δεκαετίες.", "53e45d98"]},
"OLAYLAR_ANTIK_AKDENIZ:-1449-01-01:0":{"b": ["Καταστροφή των μινωικών ανακτόρων στην Κρήτη· ξεκίνησε ο μυκηναϊκός έλεγχος στην Κνωσό", "1a7f7f2b"], "d": ["Στο τέλος της Υστερομινωικής ΙΒ (μέσα του 15ου αιώνα π.Χ.), τα ανακτορικά κέντρα και οι βίλες στην Κρήτη υφίστανται καταστροφή· στην επόμενη φάση στην Κνωσό οι πινακίδες Γραμμικής Β δείχνουν ανακτορική διοίκηση που γράφεται στα ελληνικά, δηλαδή μυκηναϊκό έλεγχο. Έτσι η μινωική κυριαρχία στην Κρήτη τελειώνει.", "2b9cf7f8"]},
"OLAYLAR_ANTIK_AKDENIZ:0009-01-01:0":{"b": ["Δάσος του Τεουτοβούργου: οι τρεις λεγεώνες του Βάρου εξοντώθηκαν· η Ρώμη άφησε τη γραμμή του Έλβα", "1684ae43"], "d": ["Το 9 μ.Χ. η γερμανική συμμαχία υπό τον Αρμίνιο εξόντωσε στο Δάσος του Τεουτοβούργου τις λεγεώνες XVII, XVIII και XIX του P. Quinctilius Varus. Ο Αύγουστος παραιτήθηκε από τις κατακτήσεις πέρα από τον Ρήνο και το σύνορο του Ρήνου έγινε μόνιμο.", "842869dc"]},
"OLAYLAR_ANTIK_AKDENIZ:0014-08-19:0":{"b": ["Ο Αύγουστος πέθανε· ο Τιβέριος έγινε αυτοκράτορας", "0221344d"], "d": ["Ο Αύγουστος πέθανε στις 19 Αυγούστου 14 στη Nola· τον διαδέχθηκε ο Τιβέριος. Η αρχή της διαδοχής (υιοθεσία από την οικογένεια) εδραιώθηκε έτσι στο Principatus.", "e55fc404"]},
"OLAYLAR_ANTIK_AKDENIZ:0040-01-01:0":{"b": ["Ο βασιλιάς Πτολεμαίος σκοτώθηκε από τον Καλιγούλα· η ανεξαρτησία της Μαυριτανίας έληξε", "11337627"], "d": ["Ο Πτολεμαίος, γιος του Juba Β', σκοτώθηκε το 40 μ.Χ. στο Lugdunum με εντολή του Καλιγούλα· στη συνέχεια ξέσπασε στη Μαυριτανία η εξέγερση του Aedemon και ο Κλαύδιος το 44 χώρισε τη χώρα σε δύο επαρχίες, Tingitana και Caesariensis.", "87e30934"]},
"OLAYLAR_ANTIK_AKDENIZ:0043-01-01:0":{"b": ["Ο Κλαύδιος εισέβαλε στη Βρεταννία", "f42ba7f7"], "d": ["Το 43 μ.Χ. τέσσερις λεγεώνες υπό τον Aulus Plautius αποβιβάστηκαν στην ακτή του Kent· καταλήφθηκε το Camulodunum (Colchester) και ο Κλαύδιος παρέμεινε για σύντομο διάστημα στην πόλη. Ο νότος της Βρεταννίας έγινε νέα ρωμαϊκή επαρχία.", "96a1d864"]},
"OLAYLAR_ANTIK_AKDENIZ:0046-01-01:0":{"b": ["Η Ρώμη έκανε τη Θράκη επαρχία: η δυναστεία των Οδρυσών έληξε", "af2ba1b2"], "d": ["Με τη δολοφονία του βασιλιά της Θράκης Ροιμητάλκη Γ' από τη σύζυγό του και την αναταραχή που ακολούθησε, ο Κλαύδιος το 46 μετέτρεψε τη Θράκη σε ρωμαϊκή επαρχία. Είναι από τα τελευταία βήματα που ολοκλήρωσαν την ανατολική επαρχιακή τάξη της Ρώμης στα Βαλκάνια.", "4d5f0125"]},
"OLAYLAR_ANTIK_AKDENIZ:0106-01-01:0":{"b": ["Ο Τραϊανός κατέκτησε τη Δακία: η Sarmizegetusa έπεσε, ο Decebalus πέθανε, ιδρύθηκε η επαρχία Dacia", "a9277172"], "d": ["Στον Δεύτερο Δακικό Πόλεμο (105-106) ο Τραϊανός κατέλαβε τη Sarmizegetusa· ο Decebalus αυτοκτόνησε για να αποφύγει τη σύλληψη. Η Δακία έγινε ρωμαϊκή επαρχία και τα χρυσωρυχεία της συνδέθηκαν με τη ρωμαϊκή οικονομία Οι προηγούμενες φάσεις του πολέμου (101-105) βρίσκονται στην κρονολογία σε ξεχωριστά λήμματα..", "ba1d2c29"]},
"OLAYLAR_ANTIK_AKDENIZ:0122-01-01:0":{"b": ["Ο Αδριανός άρχισε στη Βρεταννία την ανέγερση Τείχους στο βόρειο σύνορο", "f4a886ec"], "d": ["Ο Αδριανός, αφού επισκέφθηκε τη Βρεταννία το 122 μ.Χ., έχτισε συνοριακό τείχος στη γραμμή Tyne-Solway. Το Τείχος συμβολίζει την αμυντική συνοριακή πολιτική της Ρώμης· η προέλαση δοκιμάστηκε με το Τείχος του Αντωνίνου (142) αλλά δεν έγινε μόνιμη.", "1486c2c9"]},
"OLAYLAR_ANTIK_AKDENIZ:0198-01-01:0":{"b": ["Ο Σεπτίμιος Σεβήρος έκανε τη Μεσοποταμία επαρχία· η Κτησιφώντα λεηλατήθηκε", "df466924"], "d": ["Ο Σεβήρος στον Παρθικό Πόλεμο (195-198) κατέλαβε τη Νίσιβη, λεηλάτησε την Κτησιφώντα και οργάνωσε την Άνω Μεσοποταμία ως ρωμαϊκή επαρχία. Η επαρχία μετέφερε στον 3ο αιώνα τη μακρινότερη ανατολική προέλαση της Ρώμης.", "1707eedd"]},
"OLAYLAR_ANTIK_AKDENIZ:0212-01-01:0":{"b": ["Constitutio Antoniniana: δόθηκε ρωμαϊκή υπηκοότητα σε όλους τους ελεύθερους κατοίκους της αυτοκρατορίας", "dd4e4024"], "d": ["Ο Καρακάλλας το 212 μ.Χ. έκανε τους ελεύθερους κατοίκους των επαρχιών Ρωμαίους πολίτες· στην αυτοκρατορία καταργήθηκε η διάκριση πολίτη-ξένου. Η ρύθμιση διεύρυνε και τη φορολογική βάση.", "b9e20124"]},
"OLAYLAR_ANTIK_AKDENIZ:0260-01-01:0":{"b": ["Ο Postumus ίδρυσε στη Γαλατία την αποσχιστική Γαλατική Αυτοκρατορία", "4dcda41d"], "d": ["Με την αιχμαλωσία του Βαλεριανού από τους Πάρθους (260), ο Postumus με τους στρατούς του Ρήνου ανακήρυξε αυτοκρατορία στη Γαλατία· η Γαλατία, η Βρεταννία και το μεγαλύτερο μέρος της Hispania αποσπάστηκαν από τη Ρώμη μέχρι το 274. Ο Γαλλιηνός δεν μπόρεσε να άρει τον διαχωρισμό.", "f1eada99"]},
"OLAYLAR_ANTIK_AKDENIZ:0271-01-01:0":{"b": ["Ο Αυρηλιανός εκκένωσε τη Δακία: ο βορράς του Δούναβη εγκαταλείφθηκε", "db2ca714"], "d": ["Λόγω της πίεσης των Γότθων, ο Αυρηλιανός εκκένωσε την επαρχία Δακία και απέσυρε τις λεγεώνες και τον άμαχο πληθυσμό στον νότο του Δούναβη (Dacia Ripensis). Η Ρώμη, μετά από 165 χρόνια, άφησε το πρώτο μεγάλο έδαφος βόρεια του Δούναβη.", "3e19ae74"]},
"OLAYLAR_ANTIK_AKDENIZ:0272-01-01:0":{"b": ["Ο Αυρηλιανός νίκησε την Αυτοκρατορία της Παλμύρας: τα ανατολικά εδάφη της Ζηνοβίας επέστρεψαν στη Ρώμη", "0a358790"], "d": ["Ο Αυρηλιανός το 272 νίκησε τον στρατό της Ζηνοβίας στην Αντιόχεια και στην Έμεσα και πολιόρκησε την Παλμύρα· η Ζηνοβία συνελήφθη. Η Συρία, η Αίγυπτος και ο νότος της Ανατολίας προσαρτήθηκαν ξανά στη Ρώμη.", "7b626384"]},
"OLAYLAR_ANTIK_AKDENIZ:0274-01-01:0":{"b": ["Ο Αυρηλιανός νίκησε τη Γαλατική Αυτοκρατορία: η Ρώμη ενώθηκε ξανά", "c1a6a642"], "d": ["Ο Αυρηλιανός το 274 νίκησε τον Tetricus στο Catalaunum· η Γαλατία, η Βρεταννία και η Hispania επέστρεψαν στη Ρώμη. Η αυτοκρατορία ενοποιήθηκε μετά από 14 χρόνια διαίρεσης και ο Αυρηλιανός πήρε τον τίτλο «Restitutor Orbis» («αυτός που ξαναδημιουργεί τον κόσμο»).", "872ee29d"]},
"OLAYLAR_ANTIK_AKDENIZ:0358-01-01:0":{"b": ["Ο Ιουλιανός εγκατέστησε τους Σάλιους Φράγκους στην Toxandria ως ρωμαϊκά foederati", "0fb618fe"], "d": ["Ο Καίσαρας Ιουλιανός το 358 νίκησε τους Σάλιους Φράγκους και τους επέτρεψε να εγκατασταθούν σε ρωμαϊκά εδάφη στην Toxandria (στα σημερινά σύνορα Ολλανδίας-Βελγίου). Είναι η αρχή της εγκατάστασης υπό ρωμαϊκή προστασία της περιοχής όπου θα γεννηθεί το βασίλειο των Φράγκων.", "ab1db90c"]},
"OLAYLAR_ANTIK_AKDENIZ:0375-01-01:0":{"b": ["Οι Ούννοι πέρασαν τον Δον και επιτέθηκαν στους Αλανούς και στους Οστρογότθους: η αρχή της Μεγάλης Μετανάστευσης", "659eb875"], "d": ["Σύμφωνα με τον Αμμιανό, οι Ούννοι το 375 πέρασαν τον Δον και νίκησαν τους Αλανούς, στη συνέχεια κατέστρεψαν το βασίλειο του βασιλιά των Οστρογότθων Ermanaric· ο λαός των Βησιγότθων (Tervingi) στη συνέχεια στηρίχθηκε στον Δούναβη. Η εποχή της κυριαρχίας των Ούννων στην Ευρώπη ξεκίνησε έτσι.", "bc56aef2"]},
"OLAYLAR_ANTIK_AKDENIZ:0376-01-01:0":{"b": ["Οι Γότθοι Τερβίγγοι πέρασαν τον Δούναβη και εγκαταστάθηκαν σε ρωμαϊκά εδάφη", "3e9de0e6"], "d": ["Υπό την πίεση των Ούννων, οι Τερβίγγοι Γότθοι του Φριτιγέρνου το 376 πήραν άδεια από τον Βάλη να περάσουν τον Δούναβη και να εγκατασταθούν σε ρωμαϊκά εδάφη· τα προβλήματα ανεφοδιασμού και διοίκησης μετατράπηκαν σε εξέγερση. Το αποτέλεσμα ήταν η ήττα της Αδριανούπολης (Εντίρνε) το 378.", "ce90a65f"]},
"OLAYLAR_ANTIK_AKDENIZ:0406-12-31:0":{"b": ["Οι Βάνδαλοι, οι Αλανοί και οι Σουηβοί πέρασαν τον Ρήνο και μπήκαν στη Γαλατία", "2b3354ba"], "d": ["Στις 31 Δεκεμβρίου 406, κατά την παραδοσιακή ημερομηνία (πάνω από τον παγωμένο Ρήνο), οι Βάνδαλοι, οι Αλανοί και οι Σουηβοί μπήκαν στη ρωμαϊκή Γαλατία· η άμυνα του Ρήνου κατέρρευσε. Στη συνέχεια η διέλευσή τους στην Ισπανία (409) αποσπάσε βασικές επαρχίες της Δυτικής Ρώμης.", "2dbbe2e6"]},
"OLAYLAR_ANTIK_AKDENIZ:0409-01-01:0":{"b": ["Οι Βάνδαλοι, οι Αλανοί και οι Σουηβοί πέρασαν στην Ισπανία: η Ισπανία μοιράστηκε", "b7036608"], "d": ["Οι ομάδες Βανδάλων, Αλανών και Σουηβών που πέρασαν τα Πυρηναία από τη Γαλατία το φθινόπωρο του 409, το 411 μοίρασαν τη χερσόνησο μεταξύ τους: οι Ασδίγγοι και οι Σουηβοί πήραν τη Γαλλαικία, οι Σιλίγγοι τη Βαιτική, οι Αλανοί τη Λουσιτανία και την Καρθαγενή. Οι Βησιγότθοι (416-418) συνέτριψαν τους Σιλίγγους και τους Αλανούς και προετοίμασαν τη διέλευση των Βανδάλων στην Αφρική.", "28caca34"]},
"OLAYLAR_ANTIK_AKDENIZ:0418-01-01:0":{"b": ["Η Ρώμη εγκατέστησε τους Βησιγότθους στην Aquitania Secunda: βησιγοτθικό βασίλειο με κέντρο την Τουλούζη", "38a7699e"], "d": ["Η Ρώμη υπό τη διοίκηση του Κωνστάντιου, αφού χρησιμοποίησε τους Βησιγότθους του Βάλλια στην Ισπανία κατά των Βανδάλων-Αλανών, το 418 τους εγκατέστησε ως foederati στην Aquitania Secunda στην κοιλάδα του Γαρούνα. Το βησιγοτθικό βασίλειο με κέντρο την Τουλούζη θεωρείται το πρώτο γερμανικό βασίλειο σε ρωμαϊκό έδαφος.", "49ca3c3f"]},
"OLAYLAR_ANTIK_AKDENIZ:0434-01-01:0":{"b": ["Συνθήκη του Margus: οι Ούννοι έλαβαν από τη Ρώμη 700 λίτρες χρυσού ετησίως", "833d8854"], "d": ["Μετά τον θάνατο του βασιλιά των Ούννων Ρούα (433/4), ο Αττίλας και ο Βλέδας έκαναν στο Margus συνθήκη με την Ανατολική Ρώμη: ο ετήσιος φόρος αυξήθηκε από 350 σε 700 λίτρες χρυσού, οι Ούννοι πρόσφυγες επιστράφηκαν. Οι Ούννοι απέκτησαν δικαίωμα εμπορίου στα σύνορα του Δούναβη.", "d18e188d"]},
"OLAYLAR_ANTIK_AKDENIZ:0435-01-01:0":{"b": ["Συνθήκη του Ίππωνα: η Ρώμη αναγνώρισε τους Βανδάλους ως foederati σε τμήμα της Νουμιδίας και της Μαυριτανίας", "f7dba59f"], "d": ["Ο βασιλιάς των Βανδάλων Γκαϊσέριχος, αφού πέρασε στην Αφρική το 429, έκανε το 435 τη συνθήκη του Ίππωνα με τη Ρώμη· οι Βάνδαλοι κράτησαν μέρος της Νουμιδίας και της Μαυριτανίας με την ιδιότητα των foederati. Η συνθήκη παραβιάστηκε το 439 με την κατάληψη της Καρχηδόνας.", "1cde8863"]},
"OLAYLAR_ANTIK_AKDENIZ:0441-01-01:0":{"b": ["Ο Αττίλας κατέλαβε τα κάστρα του Δούναβη: το Βιμινάκιο και το Σιγγιδούνο (Βελιγράδι) πέρασαν στους Ούννους", "0abb2c54"], "d": ["Όταν ο ανατολικορωμαϊκός στρατός βρισκόταν στην εκστρατεία της Σικελίας και κατά των Βανδάλων, ο Αττίλας το 441 πέρασε τον Δούναβη· καταλήφθηκαν το Margus, το Βιμινάκιο και το Σιγγιδούνο. Και το Σίρμιο έπεσε σε αυτές τις εκστρατείες και οι Ούννοι έφτασαν στο εσωτερικό των Βαλκανίων.", "93414c5c"]},
"OLAYLAR_ANTIK_AKDENIZ:0442-01-01:0":{"b": ["Η Ρώμη και οι Βάνδαλοι έκαναν νέα συνθήκη: η Africa Proconsularis, η Βυζακηνή και μέρος της Νουμιδίας έμειναν στους Βανδάλους", "e5700ddc"], "d": ["Ο Γκαϊσέριχος, που κατέλαβε την Καρχηδόνα (439), με τη συνθήκη που έκανε το 442 με τον Βαλεντινιανό Γ΄ έκανε νομικά βανδαλικό έδαφος την Africa Proconsularis, τη Βυζακηνή, την Αβαριτανή και μέρος της Νουμιδίας· η Ρώμη κράτησε μόνο τη Μαυριτανία και τη δύση της Νουμιδίας.", "3910a28d"]},
"OLAYLAR_ANTIK_AKDENIZ:0448-01-01:0":{"b": ["Ειρήνη του Ανατολίου: μια εκτεταμένη λωρίδα νότια του Δούναβη αφέθηκε στους Ούννους", "ee8ad838"], "d": ["Μετά την ανατολικορωμαϊκή ήττα στον Ούτο, ο Ανατόλιος το 447 έκανε ειρήνη με τον Αττίλα: η Ρώμη άφησε στους Ούννους νότια του Δούναβη μια λωρίδα πλάτους πέντε ημερών που εκτεινόταν από το Σιγγιδούνο μέχρι τη Νόβα, ο ετήσιος φόρος αυξήθηκε σε 2100 λίτρες χρυσού.", "591853fc"]},
"OLAYLAR_ANTIK_AKDENIZ:0451-01-01:0":{"b": ["Μάχη των Καταλαυνικών Πεδίων (Châlons): ο Αέτιος και ο Θευδέριχος Α΄ έδιωξαν τον Αττίλα από τη Γαλατία", "80f10e32"], "d": ["Το 451 ο Αττίλας μπήκε στη Γαλατία και πολιόρκησε την Ορλεάνη· ο συνασπισμός του Αέτιου και του βασιλιά των Βησιγότθων Θευδέριχου Α΄ τον απέκρουσε στην Πεδιάδα των Καταλαυνικών (ο Θευδέριχος πέθανε). Η προέλαση των Ούννων στη Δυτική Ευρώπη έτσι σταμάτησε.", "89c6bc9e"]},
"OLAYLAR_ANTIK_AKDENIZ:0452-01-01:0":{"b": ["Ο Αττίλας μπήκε στην Ιταλία· η Ακυληία καταστράφηκε", "1349c67a"], "d": ["Το 452 ο Αττίλας μπήκε από τις Άλπεις στη Βόρεια Ιταλία, ισοπέδωσε την Ακυληία και λεηλάτησε την πεδιάδα του Πάδου· αποσύρθηκε λόγω ασθένειας και της αντεπίθεσης της Ανατολικής Ρώμης. Οι πρόσφυγες της Ακυληίας στις λιμνοθάλασσες σχημάτισαν τον πυρήνα της Βενετίας.", "cb78da70"]},
"OLAYLAR_ANTIK_AKDENIZ:0453-01-01:0":{"b": ["Ο Αττίλας πέθανε· το κράτος των Ούννων διαλύθηκε", "47009384"], "d": ["Ο Αττίλας το 453 πέθανε τη νύχτα του γάμου του· η διανομή μεταξύ των γιων του και η εξέγερση των γερμανικών υπηκόων ένα χρόνο αργότερα στο Νεδάο (454) τερμάτισαν την ουννική υπεροχή. Οι Ούννοι αποσύρθηκαν στην Ανατολική Ευρώπη.", "f5a5a41d"]},
"OLAYLAR_ANTIK_AKDENIZ:0475-01-01:0":{"b": ["Το βησιγοτθικό βασίλειο του Ευρίχου αποσπάστηκε στην πράξη από τη Ρώμη: η Overnia αφέθηκε στους Βησιγότθους", "4bbe7b0c"], "d": ["Ο Εύριχος, κάνοντας κατακτήσεις στην Ισπανία και τη Γαλατία από το 466, διεύρυνε το βασίλειό του· το 475 ο Ιούλιος Νέπως, αφήνοντας την Overnia (Auvergne), αναγνώρισε στην πράξη την ανεξάρτητη κυριαρχία του. Το βησιγοτθικό βασίλειο έλεγχε τα εδάφη της Δυτικής Ρώμης από τον Λίγηρα μέχρι τη Μεσόγειο.", "06af5e95"]},
"OLAYLAR_ANTIK_AKDENIZ:0480-01-01:0":{"b": ["Ο Ιούλιος Νέπως δολοφονήθηκε στη Δαλματία: ο τελευταίος νόμιμος αυτοκράτορας της Δυτικής Ρώμης", "3b965f33"], "d": ["Ο Νέπως, που αποσύρθηκε στη Δαλματία μετά την ανατροπή του Ρωμύλου, σκοτώθηκε το 480· μετά τον θάνατό του δεν έμεινε κανείς να διεκδικήσει τον θρόνο της Δυτικής Ρώμης και ο Οδόακρος συνέχισε την πραγματική εξουσία του στην Ιταλία στο όνομα του Ζήνωνα.", "4f4d9885"]},
"OLAYLAR_ANTIK_AKDENIZ:0489-08-28:0":{"b": ["Ο Θευδέριχος έβαλε τους Οστρογότθους στην Ιταλία: ο Οδόακρος ηττήθηκε στο Ισόντσο και στη Βερόνα", "6a998bf8"], "d": ["Με την έγκριση του Ανατολικορωμαίου αυτοκράτορα Ζήνωνα, ο Θευδέριχος μπήκε στην Ιταλία το 489, νίκησε τον Οδόακρο στο Ισόντσο και στη Βερόνα· ο Οδόακρος κλείστηκε στη Ραβέννα. Η τριετής πολιορκία έληξε το 493 με την παράδοση της Ραβέννας.", "092f7492"]},
"OLAYLAR_ANTIK_AKDENIZ:0493-03-05:0":{"b": ["Ο Θευδέριχος έβαλε να σκοτωθεί ο Οδόακρος στη Ραβέννα· η Ιταλία έγινε του Οστρογοτθικού Βασιλείου", "5a2db0ed"], "d": ["Το τέλος του Βασιλείου της Ιταλίας του Οδόακρου: ολόκληρη η Ιταλία (συμπεριλαμβανομένων πόλεων όπως η Γένοβα, το Μπρίντιζι, η Aricia) πέρασε στο Βασίλειο των Ανατολικών Γότθων (Οστρογότθων). Μετά την τριετή πολιορκία της Ραβέννας, τον Μάρτιο του 493 ο Οδόακρος και ο Θευδέριχος συμφώνησαν σε κοινή διοίκηση· στη συνέχεια ο Θευδέριχος σκότωσε τον Οδόακρο σε συμπόσιο. Η Ιταλία με την έγκριση της Ανατολικής Ρώμης έγινε Οστρογοτθικό Βασίλειο και πρωτεύουσά του είναι η Ραβέννα.", "1024674c"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0020-01-01:0":{"b": ["Ειρήνη της Σάμου: οι απεσταλμένοι της Kush πήραν ειρήνη από τον Αύγουστο· η Ρώμη κατήργησε τον φόρο που είχε επιβάλει στην Kush, το σύνορο χαράχθηκε στην Κάτω Νουβία (Ιερά Συκάμινος)", "c3c4c20d"], "d": ["Οι απεσταλμένοι της Kandake, με την καθοδήγηση του Πετρώνιου, πήγαν στη Σάμο όπου βρήκαν τον Αύγουστο· ο Αύγουστος δέχθηκε όλα τα αιτήματά τους και κατήργησε και τους φόρους που είχε επιβάλει ο Πετρώνιος στην Kush. Ως αποτέλεσμα της ειρήνης το ρωμαιοκουσιτικό σύνορο εδραιώθηκε νότια των Φιλών, στη γραμμή της Ιεράς Συκαμίνου (Maharraqa) και για περίπου τριακόσια χρόνια δεν υπήρξε σοβαρή σύγκρουση.", "4ff5e832"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0022-01-01:0":{"b": ["Ο Πετρώνιος εκστράτευσε εναντίον της Kush και κατέλαβε την Πσέλκιδα, την Πρέμνη και τη Νάπατα· εγκατέστησε φρουρά στην Ibrim", "4884ed51"], "d": ["Ο έπαρχος Πετρώνιος, με περίπου δέκα χιλιάδες πεζούς και οκτακόσιους ιππείς, νίκησε τριάντα χιλιάδες στρατιώτες της Kush, κατέλαβε την Πσέλκιδα, κατέλαβε το φρούριο της Πρέμνης (Qasr Ibrim) με την πρώτη επίθεση και ισοπέδωσε τη Νάπατα, όπου βρισκόταν το ανάκτορο της Kandake. Θεωρώντας δύσκολο να προχωρήσει περισσότερο, κατά την επιστροφή άφησε στην Πρέμνη φρουρά τετρακοσίων ανδρών με εφόδια δύο ετών. Όταν η Kandake προσπάθησε να ανακαταλάβει την Πρέμνη, ο Πετρώνιος πρόλαβε και υπερασπίστηκε το φρούριο.", "672f8f4e"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0024-01-01:0":{"b": ["Υπό την ηγεσία της Kandake η Kush κατέλαβε την Ελεφαντίνη, τη Συήνη και τους Φίλες· γκρέμισαν τα αγάλματα του Αυγούστου", "aa665fad"], "d": ["Όταν μέρος των ρωμαϊκών μονάδων στην Αίγυπτο αποσύρθηκε για την εκστρατεία του Aelius Gallus στην Αραβία, οι Κουσίτες μπήκαν στη Θηβαΐδα· νίκησαν τη φρουρά τριών κοορτών στη Συήνη και κατέλαβαν τη Συήνη, την Ελεφαντίνη και τους Φίλες, αιχμαλώτισαν τον λαό και γκρέμισαν τα αγάλματα του Καίσαρα. Ο Στράβων γράφει ότι η βασίλισσα που κυβερνούσε την Kush εκείνη την εποχή ήταν γυναίκα με τον τίτλο «Kandake», μονόφθαλμη.", "63e07dc6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0028-01-01:0":{"b": ["Ο Κορνήλιος Γάλλος έγινε ο πρώτος έπαρχος της Αιγύπτου· κατέστειλε τις εξεγέρσεις της Ηρώων πόλεως και των Θηβών, το σύνορο με την Kush εξασφαλίστηκε", "9f688855"], "d": ["Ο Οκταβιανός έκανε την Αίγυπτο ιδιαίτερη επαρχία υποκείμενη σε φόρο και άφησε τη διοίκησή της όχι σε σενατορα αλλά σε έπαρχο από την τάξη των ιππέων· πρώτος έπαρχος έγινε ο Κορνήλιος Γάλλος. Ο Στράβων γράφει ότι ο Γάλλος κατέλαβε με λίγους στρατιώτες μια κωμόπολη που είχε εξεγερθεί στην Ηρώων πόλη και κατέστειλε σε σύντομο χρόνο την εξέγερση που ξέσπασε στις Θήβες λόγω φόρου. Η στήλη του Γάλλου στους Φίλες αναφέρει ότι εκεί έγιναν δεκτοί απεσταλμένοι του ηγεμόνα της Kush και ότι η περιοχή του Τριακοντασχοίνου τέθηκε υπό προστασία.", "ae3f8fab"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0029-08-01:0":{"b": ["Ο Οκταβιανός μπήκε στην Αλεξάνδρεια· το κράτος των Πτολεμαίων έληξε, η Αίγυπτος πέρασε στη Ρώμη", "553804ca"], "d": ["Μετά το πέρασμα του στόλου και του ιππικού του Αντωνίου στον Οκταβιανό, ο Οκταβιανός μπήκε στην Αλεξάνδρεια· ο Αντώνιος αυτοκτόνησε και η Κλεοπάτρα πέθανε λίγο αργότερα. Ο Οκταβιανός συγχώρεσε τον λαό της Αλεξάνδρειας, λέγοντας «ήθελα να δω βασιλιά, όχι νεκρούς» δεν επισκέφθηκε τους τάφους των Πτολεμαίων και έδωσε την Αίγυπτο ως χώρα υποκείμενη σε φόρο στον Κορνήλιο Γάλλο. Με αυτή την ημερομηνία το τριακοσιετές βασίλειο των Πτολεμαίων έληξε.", "c1595889"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0030-09-02:0":{"b": ["Ναυμαχία του Ακτίου: ο Οκταβιανός νίκησε τον Αντώνιο και την Κλεοπάτρα", "7e46cc73"], "d": ["Ο στόλος του Οκταβιανού νίκησε στο Άκτιο τον στόλο του Αντωνίου και της Κλεοπάτρας· οι δύο αποσύρθηκαν στην Αίγυπτο. Ο Δίων, συγγραφέας που αποφεύγει να δίνει ημερομηνίες, αναφέρει ειδικά αυτή την ημέρα επειδή ο Οκταβιανός από τότε κρατούσε μόνος του την αυτοκρατορία και τα έτη της εξουσίας του μετρήθηκαν από αυτή την ημέρα.", "7747a2e5"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0033-01-01:0":{"b": ["Οι Δωρεές της Αλεξάνδρειας: ο Αντώνιος ανακήρυξε την Κλεοπάτρα και τα παιδιά της ηγεμόνες των ανατολικών βασιλείων", "24e24981"], "d": ["Ο Αντώνιος, που έστησε χρυσούς θρόνους μπροστά στο πλήθος που είχε συγκεντρωθεί στο Γυμνάσιο, ανακήρυξε την Κλεοπάτρα βασίλισσα της Αιγύπτου, της Κύπρου, της Λιβύης και της Κοίλης Συρίας, τον Καισαρίωνα συγκυρίαρχό της και τα παιδιά της βασιλείς της Αρμενίας, της Μηδίας, των Πάρθων και της Φοινίκης-Συρίας-Κιλικίας. Στη Ρώμη η τελετή αυτή έγινε προπαγάνδα εναντίον του Αντωνίου και επιτάχυνε τον εμφύλιο πόλεμο.", "dc9e5d73"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0035-01-01:0":{"b": ["Ο Αντώνιος χάρισε στην Κλεοπάτρα την Κύπρο, τη Φοινίκη, την Κοίλη Συρία και μέρος της Κιλικίας", "cf19a357"], "d": ["Σύμφωνα με τον Πλούταρχο, ο Αντώνιος, όταν ήρθε στη Συρία, έδωσε στην Κλεοπάτρα τη Φοινίκη, την Κοίλη Συρία, την Κύπρο, το μεγαλύτερο μέρος της Κιλικίας, την πλευρά της Ιουδαίας που παράγει βάλσαμο και το τμήμα της Ναβαταίας που φτάνει στη θάλασσα. Έτσι το κράτος των Πτολεμαίων, για πρώτη φορά από τον Πτολεμαίο Γ', έλεγξε ευρεία περιοχή στην Ανατολική Μεσόγειο (παρά την οργή της Ρώμης).", "2c5122e4"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0046-01-01:0":{"b": ["Πόλεμος της Αλεξάνδρειας: ο Καίσαρας νίκησε τον Πτολεμαίο ΙΓ' και άφησε την Αίγυπτο στην Κλεοπάτρα", "96c9b516"], "d": ["Όταν ο Καίσαρας ήρθε στην Αλεξάνδρεια και ήθελε να διαιτητεύσει ανάμεσα στην Κλεοπάτρα και τον Πτολεμαίο ΙΓ', οι δυνάμεις του ανακτόρου τον πολιόρκησαν· στον οδομαχικό πόλεμο που διήρκεσε όλο τον χειμώνα έφτασε βοήθεια στον Καίσαρα και στη Μάχη του Νείλου ο Πτολεμαίος ΙΓ' πνίγηκε. Ο Καίσαρας έδωσε την Αίγυπτο στην Κλεοπάτρα και στον μικρότερο αδελφό της Πτολεμαίο ΙΔ'· οι ρωμαϊκές λεγεώνες έμειναν στην Αλεξάνδρεια.", "bc41a5ff"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0054-01-01:0":{"b": ["Ο Γαβίνιος επανέφερε τον Πτολεμαίο ΙΒ' στον θρόνο της Αιγύπτου με ρωμαϊκό στρατό· στην Αλεξάνδρεια έμεινε ρωμαϊκή φρουρά", "41d8f47d"], "d": ["Ο εκδιωγμένος Πτολεμαίος ΙΒ' (Αυλητής) αγόρασε την είσοδο στην Αίγυπτο δίνοντας μεγάλο δωροδοκία στον κυβερνήτη της Συρίας Γαβίνιο· ο Γαβίνιος εγκατέλειψε την εκστρατεία στους Πάρθους, μπήκε στην Αίγυπτο από το Πηλούσιο και επανέφερε τον Αυλητή στον θρόνο. Αυτή είναι η στιγμή που η ανεξαρτησία της Αιγύπτου συνδέθηκε στην πράξη με τη ρωμαϊκή εγγύηση. Ο Γαβίνιος αργότερα δικάστηκε στη Ρώμη.", "2ebc08ef"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0057-01-01:0":{"b": ["Η Ρώμη πήρε την Κύπρο από τον Πτολεμαίο και την προσάρτησε· ο Κάτων στάλθηκε στο νησί", "678b2115"], "d": ["Ο βασιλιάς της Κύπρου, αδελφός του Πτολεμαίου ΙΒ', δεν αντιστάθηκε στην κατάληψη του νησιού από τη Ρώμη με πρόταση του Κλώδιου· ο Κάτων στάλθηκε να παραλάβει το νησί. Το κράτος των Πτολεμαίων έχασε την Κύπρο και έχασε την τελευταία ναυτική βάση στην ακτή. Ο Πλούταρχος αναφέρει την «αποστολή του Κάτωνα στην Κύπρο» στη βιογραφία του Πομπήιου.", "2ec72ea2"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0167-01-01:0":{"b": ["«Ημέρα της Ελευσίνας»: ο Ρωμαίος απεσταλμένος Popilius Laenas ανάγκασε τον Αντίοχο Δ' να αποσυρθεί από την Αίγυπτο", "e6883e6a"], "d": ["Αμέσως μετά τη Μάχη της Πύδνας (22 Ιουνίου π.Χ. 168), ο Ρωμαίος απεσταλμένος Gaius Popilius Laenas ανακοίνωσε στον Αντίοχο, που πολιορκούσε την Αλεξάνδρεια, την εντολή της Συγκλήτου να σταματήσει τον πόλεμο· χάραξε έναν κύκλο γύρω του για να σκεφτεί ο βασιλιάς την απάντησή του. Ο Αντίοχος αποσύρθηκε. Η Αίγυπτος διατήρησε την ανεξαρτησία της χωρίς να τη χάσει υπό τη ρωμαϊκή προστασία.", "4831dad7"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0168-01-01:0":{"b": ["Ο Αντίοχος Δ' επιτέθηκε στην Αίγυπτο· στον Έκτο Συριακό Πόλεμο προχώρησε στη Μέμφιδα και στη Ναύκρατη", "b85e6712"], "d": ["Ο Αντίοχος Δ', ως απάντηση στις προετοιμασίες του Πτολεμαίου ΣΤ' να ανακτήσει την Κοίλη Συρία, μπήκε στην Αίγυπτο και κατέβηκε από το Πηλούσιο στον Νείλο· υπερασπίστηκε το δικαίωμά του στην Κοίλη Συρία και φέρθηκε καλά στον λαό της Ναυκράτεως. Ο πόλεμος έληξε ένα χρόνο αργότερα με την επέμβαση της Ρώμης, χωρίς να καταστρέψει την Αίγυπτο αλλά αποδυναμώνοντας το κράτος.", "f329f8b1"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0185-01-01:0":{"b": ["Η εξέγερση των Θηβών καταπνίγηκε: ο Κομάνος ανέκτησε την Άνω Αίγυπτο στην πτολεμαϊκή κυριαρχία", "4c0e4f10"], "d": ["Μετά από περίπου είκοσι χρόνια αποσχιστικής διοίκησης, ο πτολεμαϊκός διοικητής Κομάνος ανέκτησε τις Θήβες από τον ντόπιο φαραώ Ankhwennefer και η Άνω Αίγυπτος συνδέθηκε ξανά με το κράτος των Πτολεμαίων.", "24386cc8"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0195-03-27:0":{"b": ["Η Σύνοδος της Μέμφιδας εξέδωσε το Διάταγμα της Ροζέττας: ο Πτολεμαίος Ε' παραχώρησε φορολογικές απαλλαγές στους ναούς", "5643b91f"], "d": ["Η σύνοδος που συγκέντρωσαν οι ιερείς της Αιγύπτου στη Μέμφιδα, επικυρώνοντας την άνοδο του Πτολεμαίου Ε' στον θρόνο, ανακήρυξε τις φορολογικές δωρεές του βασιλιά στους ναούς, την καταστολή των εξεγέρσεων και την ίδρυση της λατρείας του βασιλιά. Το διάταγμα γράφτηκε στα ελληνικά, στα δημοτικά και στα ιερογλυφικά· η Λίθος της Ροζέττας είναι αυτό το τρίγλωσσο κείμενο. Το κείμενο αναφέρεται επίσης στην καταστολή των στασιαστών στο Δέλτα (Λυκόπολη).", "80eb0165"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0199-01-01:0":{"b": ["Μάχη του Πανείου: ο Αντίοχος Γ' νίκησε τον Σκόπα· η Κοίλη Συρία πέρασε από τους Πτολεμαίους στους Σελευκίδες", "97e30e58"], "d": ["Στον Πέμπτο Συριακό Πόλεμο ο Αντίοχος Γ' κατατρόπωσε στο Πάνειο τον πτολεμαϊκό διοικητή Σκόπα τον Αιτωλό· σύμφωνα με τον Ιώσηπο, ο Αντίοχος ανέκτησε τις πόλεις της Κοίλης Συρίας που είχε καταλάβει ο Σκόπας και κατέλαβε και τη Σαμάρεια, οι Ιουδαίοι προσχώρησαν στον Αντίοχο με τη θέλησή τους. Η Κοίλη Συρία (Συρία-Παλαιστίνη) από τότε πέρασε στη σελευκιδική διοίκηση· το κράτος των Πτολεμαίων αποσύρθηκε από την περιοχή.", "930d7d22"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0204-01-01:0":{"b": ["Στις Θήβες εμφανίστηκαν αποσχιστικοί ντόπιοι φαραώ: η Άνω Αίγυπτος αποσπάστηκε από την πτολεμαϊκή κυριαρχία", "d10abb36"], "d": ["Οι ντόπιοι Αιγύπτιοι, που εξοπλίστηκαν μετά τη νίκη της Ραφίας, κατά την έκφραση του Πολύβιου, φουσκωμένοι από τη νίκη δεν υπάκουαν στις διαταγές του βασιλιά· στο Δέλτα και στην Άνω Αίγυπτο ξέσπασαν εξεγέρσεις. Στις Θήβες οι ντόπιοι φαραώ (Horwennefer, στη συνέχεια Ankhwennefer) κράτησαν επί περίπου είκοσι χρόνια την Άνω Αίγυπτο εναντίον των Πτολεμαίων.", "aed92c1c"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0216-01-01:0":{"b": ["Μάχη της Ραφίας: ο Πτολεμαίος Δ' νίκησε τον Αντίοχο Γ'· η Κοίλη Συρία έμεινε στους Πτολεμαίους", "34362178"], "d": ["Στη Ραφία ο στρατός του Πτολεμαίου Δ', με τη δομή του που περιλάμβανε μεγάλο αριθμό ντόπιων Αιγυπτίων φαλαγγιτών (οπλιτών), νίκησε τον στρατό του Αντιόχου Γ'· ο Αντίοχος αποσύρθηκε από την Κοίλη Συρία και η περιοχή έμεινε στα χέρια των Πτολεμαίων μέχρι το 200. Ο εξοπλισμός των ντόπιων Αιγυπτίων τροφοδότησε αργότερα τις αποσχιστικές εξεγέρσεις στην Άνω Αίγυπτο.", "e5e7e848"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0218-01-01:0":{"b": ["Ο Αντίοχος Γ' ανέκτησε τη Σελεύκεια της Πιερίας από τους Πτολεμαίους", "39ee3a52"], "d": ["Ο Αντίοχος Γ' πολιόρκησε τη Σελεύκεια της Πιερίας, που βρισκόταν σε πτολεμαϊκά χέρια, και την κατέλαβε δωροδοκώντας αξιωματικούς· ο Πολύβιος γράφει ότι η πόλη κρατιόταν από την εποχή του Πτολεμαίου Γ' από φρουρά που ανήκε στους βασιλείς της Αιγύπτου. Με αυτή τη νίκη οι Σελευκίδες απέκτησαν το λιμάνι της Αντιόχειας και προετοιμάστηκαν για πορεία προς την Κοίλη Συρία (Τέταρτος Συριακός Πόλεμος).", "6964f9b2"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0245-01-01:0":{"b": ["Ο Πτολεμαίος Γ' στον Πόλεμο της Λαοδίκης εισέβαλε στη Συρία και στη Μεσοποταμία· η Σελεύκεια της Πιερίας πέρασε στους Πτολεμαίους", "04472253"], "d": ["Ο Πτολεμαίος Β' πέθανε στις 28 Ιανουαρίου π.Χ. 246· ο Πτολεμαίος Γ' επιτέθηκε στο σελευκιδικό κράτος για να προστατεύσει την αδελφή του Βερενίκη. Έγινε δεκτός στη Σελεύκεια της Πιερίας και στην Αντιόχεια· το Βαβυλωνιακό Χρονικό (BCHP 11) αναφέρει ότι ο στρατός του είχε φτάσει στη Βαβυλώνα από τον Δεκέμβριο π.Χ. 246. Η επιγραφή της Αδούλης ισχυρίζεται ότι κατέκτησε τη δυτική όχθη του Ευφράτη, την Κιλικία, την Παμφυλία και τη Θράκη. Η Σελεύκεια της Πιερίας έμεινε για πολλά χρόνια στα χέρια των Πτολεμαίων.", "54ffdc9c"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0300-01-01:0":{"b": ["Μετά την Ιψό ο Πτολεμαίος κατέλαβε την Κοίλη Συρία· ο Σέλευκος διαμαρτυρήθηκε (η ρίζα των Συριακών Πολέμων)", "a109388f"], "d": ["Μετά τη Μάχη της Ιψού (π.Χ. 301), ο Σέλευκος, ο Λυσίμαχος και ο Κάσσανδρος συμφώνησαν και έδωσαν ολόκληρη τη Συρία στον Σέλευκο· ο Πτολεμαίος όμως κατέλαβε με στρατό την Κοίλη Συρία και την κράτησε. Αυτή η διαφωνία γέννησε στους επόμενους δύο αιώνες έξι Συριακούς Πολέμους. Ο Αντίοχος Γ' αργότερα υποστήριξε αυτή την άποψη όπως τη μεταφέρει ο Πολύβιος.", "21348480"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0304-01-01:0":{"b": ["Ο Πτολεμαίος ανακήρυξε τον εαυτό του βασιλιά· η δυναστεία των Πτολεμαίων ιδρύθηκε επίσημα", "008c723a"], "d": ["Μετά την ανάληψη του τίτλου του βασιλιά από τον Αντίγονο και τον Δημήτριο (π.Χ. 306), και ο Πτολεμαίος πήρε τον τίτλο του βασιλιά· η Αίγυπτος άρχισε να αναφέρεται ως ανεξάρτητο ελληνιστικό βασίλειο. Η παρουσίαση της δυναστείας ως φαραώ της Αιγύπτου επιτάχυνε και τον συμβιβασμό με την ντόπια ιερατική τάξη.", "318a8821"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0311-01-01:0":{"b": ["Μάχη της Γάζας: ο Πτολεμαίος και ο Σέλευκος νίκησαν τον Δημήτριο (η Συρία για σύντομο διάστημα στον Πτολεμαίο)", "ea0d264f"], "d": ["Ο Δημήτριος, γιος του Αντιγόνου, ηττήθηκε μπροστά στη Γάζα από τον ενωμένο στρατό του Πτολεμαίου και του Σελεύκου· ο Πτολεμαίος μπήκε στην Κοίλη Συρία. Με την αντεπίθεση του Αντιγόνου η περιοχή ξέφυγε ξανά σύντομα από τα χέρια του, η ειρήνη (π.Χ. 311) το σταθεροποίησε.", "619ae833"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0320-01-01:0":{"b": ["Η εκστρατεία του Περδίκκα στην Αίγυπτο απέτυχε στη διάβαση του Νείλου· ο Περδίκκας σκοτώθηκε από τον στρατό του", "c1792117"], "d": ["Στον πόλεμο των Διαδόχων, ο αντιβασιλέας του Αλεξάνδρου Περδίκκας μπήκε στην Αίγυπτο εναντίον του Πτολεμαίου, που είχε αρπάξει την κηδεία του Αλεξάνδρου, αλλά δεν μπόρεσε να περάσει τον Νείλο, έχασε πολλούς άνδρες και σκοτώθηκε από τους αξιωματικούς του. Ο Πτολεμαίος κράτησε την Αίγυπτο.", "0057b746"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0321-01-01:0":{"b": ["Ο Πτολεμαίος προσάρτησε την Κυρήνη (Κυρηναϊκή) στην Αίγυπτο", "65316c50"], "d": ["Ο Πτολεμαίος, παρεμβαίνοντας στις εσωτερικές έριδες της Κυρήνης, προσάρτησε στην Αίγυπτο, υπό τη διοίκηση του Οφέλλα, την περιοχή της Κυρηναϊκής στη Λιβύη. Έτσι ο Πτολεμαϊκός Αίγυπτος επεκτάθηκε και προς τα δυτικά· η Κυρηναϊκή έμεινε τους επόμενους αιώνες στα χέρια ενός κλάδου της δυναστείας των Πτολεμαίων.", "5d0e2ba6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0330-01-01:0":{"b": ["Ο Αλέξανδρος συμβουλεύτηκε τον Μάντη του Άμμωνα στην όαση Σίβα", "c437ced0"], "d": ["Ο Αλέξανδρος πέρασε από την ακτή στην έρημο και πήγε στην όαση Σίβα, όπου βρίσκεται ο Ναός του Άμμωνα, και συμβουλεύτηκε το μαντείο· ο Αρριανός γράφει ότι πήρε την απάντηση που θα τον ευχαριστούσε. Η επίσκεψη αυτή τροφοδότησε τη νομιμότητα του Αλεξάνδρου στην Αίγυπτο και τις μεταγενέστερες αφηγήσεις ότι θεωρήθηκε γιος του θεού.", "40603afa"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0331-01-01:0":{"b": ["Ο Αλέξανδρος μπήκε στην Αίγυπτο· ο Πέρσης σατράπης Μαζάκης παραδόθηκε, η Αίγυπτος πέρασε σε μακεδονική διοίκηση", "c4a5f014"], "d": ["Ο Αλέξανδρος, που ξεκίνησε από τη Γάζα, έφτασε την έβδομη ημέρα στο Πηλούσιο, και ο στόλος του είχε φτάσει επίσης εκεί. Ο σατράπης Μαζάκης, που μετά την Ισσό δεν είχε περσική υποστήριξη, δεν αντιστάθηκε και δέχθηκε φιλικά τον Αλέξανδρο στις πόλεις. Ο Αλέξανδρος εγκατέστησε φρουρά στο Πηλούσιο και προχώρησε στη Μέμφιδα· άφησε τη διοίκηση σε δύο ντόπιους (Δολόασπις, Πετίσης) κυβερνήτες και διόρισε Μακεδόνες διοικητές στη Μέμφιδα και στο Πηλούσιο. Η Αίγυπτος βγήκε από την περσική κυριαρχία και προσαρτήθηκε στην αυτοκρατορία του Αλεξάνδρου.", "08c837eb"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0342-01-01:0":{"b": ["Ο Αρταξέρξης Γ' κατέκτησε ξανά την Αίγυπτο· ο Νεκτανεβώ Β' διέφυγε στη Νουβία", "55d78a8d"], "d": ["Στην πορεία του Αρταξέρξη Γ' προς την Αίγυπτο μετά την κατάληψη της Σιδώνας, η άμυνα του Πηλουσίου κατέρρευσε· ο Νεκτανεβώ Β', χωρίς να περιμένει πολιορκία στη Μέμφιδα, διέφυγε στην Άνω Αίγυπτο και στη Νουβία. Η Αίγυπτος έγινε για δεύτερη φορά περσική σατραπεία· η τύχη του τελευταίου ντόπιου φαραώ είναι άγνωστη.", "373a5f39"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0359-01-01:0":{"b": ["Ο Τάχως εκστράτευσε στη Συρία· ο Νεκτανεβώ Β' κατέλαβε τον θρόνο με πραξικόπημα, ο Αγησίλαος άλλαξε στρατόπεδο", "4e1e9804"], "d": ["Ο Τάχως συγκέντρωσε Έλληνες μισθοφόρους (τον βασιλιά της Σπάρτης Αγησίλαο και τον Αθηναίο Χαβρία) για να επιτεθεί στην περσική Συρία· ενώ βρισκόταν στην εκστρατεία, ο ανιψιός του Νεκτανεβώ Β' ανακήρυξε τον εαυτό του βασιλιά. Ο Αγησίλαος τάχθηκε στο πλευρό του Νεκτανεβώ· ο Πλούταρχος γράφει ότι στην Ελλάδα επικρίθηκε το ότι ο Αγησίλαος στα γεράματά του πολέμησε με αμοιβή για έναν «βάρβαρο στασιαστή».", "d9ffa449"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0372-01-01:0":{"b": ["Ο Νεκτανεβώ Α' απέκρουσε την περσική εισβολή (Φαρνάβαζος-Ιφικράτης)", "0a8bc67d"], "d": ["Ο Νεκτανεβώ Α', ιδρυτής της 30ής Δυναστείας, απέκρουσε την απόβαση στο Δέλτα του περσικού στρατού υπό τον Φαρνάβαζο και του Αθηναίου Ιφικράτη χάρη στην πλημμύρα του Νείλου και στη διαφωνία των διοικητών. Αυτή η επιτυχία παρέτεινε την ανεξαρτησία της Αιγύπτου κατά 30 χρόνια ακόμη.", "edb11f45"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0459-01-01:0":{"b": ["Η εξέγερση του Ινάρου: η αιγυπτιακή εξέγερση με αθηναϊκή υποστήριξη στρίμωξε τους Πέρσες στη Μέμφιδα, κατέρρευσε το 454 στην Προσωπίτιδα", "0cd93c33"], "d": ["Ο Λίβυος Ίναρος εξέγειρε σχεδόν ολόκληρη την Αίγυπτο εναντίον του Αρταξέρξη και ζήτησε βοήθεια από τους Αθηναίους· ο αθηναϊκός στόλος μπήκε στον Νείλο, κατέλαβε τα δύο τρίτα της Μέμφιδας και πολιόρκησε το εναπομείναν «Λευκό Τείχος». Ο Πέρσης διοικητής Μεγάβυζος πολιόρκησε τους Αθηναίους στο νησί Προσωπίτιδα για ένα χρόνο και έξι μήνες (ξεραίνοντας το κανάλι) και τους εξόντωσε· ο Ίναρος αιχμαλωτίστηκε και σταυρώθηκε. Ο Αμυρταίος στα έλη του Δέλτα δεν συνελήφθη.", "452e1e06"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0485-01-01:0":{"b": ["Η Αίγυπτος εξεγέρθηκε κατά της περσικής κυριαρχίας· ο Ξέρξης Α΄ κατέστειλε την εξέγερση και διοίκησε την Αίγυπτο πιο σκληρά", "9d3d7462"], "d": ["Η αιγυπτιακή εξέγερση, που άρχισε πριν από τον θάνατο του Δαρείου Α΄, καταστάλθηκε στα πρώτα χρόνια του Ξέρξη Α΄· ο Ξέρξης διόρισε σατράπη τον αδελφό του Αχαιμένη και άρχισε να διοικεί την Αίγυπτο πιο σκληρά από την εποχή του Δαρείου.", "db4dbf1d"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0522-01-01:0":{"b": ["Η εκστρατεία του Καμβύση στην Κους απέτυχε από έλλειψη νερού και τροφίμων· το νότιο σύνορο της Αιγύπτου έμεινε στην Ελεφαντίνη", "4ebbad8c"], "d": ["Ο Καμβύσης, μετά την Αίγυπτο, σχεδίασε εκστρατεία κατά των «Μακρόβιων Αιθιόπων» (Κους)· σύμφωνα με τον Ηρόδοτο, ο βασιλιάς της Κους έστειλε το τόξο του στους Πέρσες απεσταλμένους και τους είπε να επιτεθούν «όταν μπορούν να τεντώσουν εύκολα το τόξο». Ο στρατός έμεινε στην έρημο χωρίς προμήθειες και επέστρεψε. Και ο Στράβων αναφέρει τον τόπο όπου ο στρατός του Καμβύση χάθηκε στην καταιγίδα της ερήμου. Η Κους παρέμεινε ανεξάρτητη· το νότιο σύνορο των Περσών σταμάτησε στην Ελεφαντίνη.", "141a4dc5"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0569-01-01:0":{"b": ["Ο Άμασις νίκησε τον Απρίη και ανέβηκε στον θρόνο της Αιγύπτου· οι Έλληνες έμποροι εγκαταστάθηκαν στη Ναύκρατη", "75a24b0b"], "d": ["Ο Απρίης, που επέστρεφε από την εκστρατεία στη Λιβύη με Έλληνες μισθοφόρους, ηττήθηκε στη Μέμφιδα από τον Άμασι, που είχε αναλάβει επικεφαλής των ντόπιων μονάδων του στρατού· ο Άμασις διοίκησε την Αίγυπτο από τη Σάιδα και παραχώρησε στους Έλληνες τη Ναύκρατη ως μοναδικό εμπορικό λιμάνι. Στο τέλος της εξουσίας του (526 π.Χ.) η περσική απειλή μεγάλωσε.", "821328d0"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0592-01-01:0":{"b": ["Ο Ψαμμήτιχος Β΄ έκανε εκστρατεία στη Νουβία: το βάρος της Κους στα αιγυπτιακά σύνορα έσπασε", "8f0aaf9d"], "d": ["Η εκστρατεία του Ψαμμήτιχου Β΄ στη Νουβία αναφέρεται στον Ηρόδοτο ως «εκστρατεία στην Αιθιοπία»· ο αιγυπτιακός στρατός και οι Έλληνες/Κάρες μισθοφόροι άφησαν ελληνικές επιγραφές στο Αμπού Σιμπέλ. Η στήλη του 3ου έτους στη Θήβα (Καρνάκ) αναφέρει ότι επιβλήθηκε βαριά ήττα στο βασίλειο της Κους και η στήλη νίκης της Καλαμπσά το μνημονεύει· η εκστρατεία θεωρείται ότι έφτασε μέχρι τον Τρίτο ή Τέταρτο Καταρράκτη. Σύμφωνα με τις πηγές, το πολιτικό κέντρο της Κους στη μεταγενέστερη περίοδο (Ασπέλτα, π. 591 π.Χ.) μετατοπίστηκε νότια, στη Μερόη.", "17c955db"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0600-01-01:0":{"b": ["Ο Ναβουχοδονόσορ επιτέθηκε στα αιγυπτιακά σύνορα· στην ανοιχτή μάχη και οι δύο πλευρές έχασαν βαριά, η Βαβυλώνα αποσύρθηκε", "45655313"], "d": ["Ο βασιλιάς της Βαβυλώνας Ναβουχοδονόσορ το 4ο έτος του βάδισε στην Αίγυπτο· ο βασιλιάς της Αιγύπτου συγκέντρωσε τον στρατό του και συναντήθηκε μαζί του, στην ανοιχτή μάχη οι δύο πλευρές εξάντλησαν βαριά η μία την άλλη. Ο Ναβουχοδονόσορ επέστρεψε στη Βαβυλώνα και αποσύρθηκε για να ανασυγκροτήσει τον στρατό του. Η Αίγυπτος υπερασπίστηκε τα σύνορά της, όμως η Συρία-Παλαιστίνη είχε μείνει στη Βαβυλώνα.", "c561b28b"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0604-01-01:0":{"b": ["Μάχη της Καρχεμίς: ο Ναβουχοδονόσορ νίκησε τον αιγυπτιακό στρατό· η Αίγυπτος έχασε τη Συρία", "ba486ac1"], "d": ["Ο διάδοχος Ναβουχοδονόσορ με τον βαβυλωνιακό στρατό πέρασε τον Ευφράτη εναντίον του αιγυπτιακού στρατού που βρισκόταν στην Καρχεμίς και τον διέλυσε, εξόντωσε όσους διέφυγαν στην περιοχή της Χαμάθ και κατέλαβε ολόκληρη την περιοχή της Χαμάθ. Η Αίγυπτος αποσύρθηκε από τη Συρία και επέστρεψε πίσω από τα σύνορα του Σινά· η Βαβυλώνα έγινε κυρίαρχος της Συρίας-Παλαιστίνης.", "61bb7c47"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0608-01-01:0":{"b": ["Ο Νεχώ Β΄ μπήκε στη Συρία-Παλαιστίνη· στη Μεγιδδώ νίκησε τον Ιωσία και προχώρησε προς τον Ευφράτη", "f887d6fd"], "d": ["Ο Νεχώ Β΄, που στράφηκε να καταλάβει τις δυτικές επαρχίες της καταρρέουσας Ασσυρίας, βάδισε στη Συρία· στον δρόμο του έβαλε να σκοτωθεί στη Μεγιδδώ ο βασιλιάς του Ιούδα Ιωσίας. Ο Ηρόδοτος λέει «ο Νεχώ νίκησε τους Σύρους στη Μάγδωλο και κατέλαβε τη μεγάλη συριακή πόλη Κάδυτιν». Έτσι η Αίγυπτος για σύντομο διάστημα έλεγξε τη Συρία-Παλαιστίνη μέχρι τον Ευφράτη.", "573a58de"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0655-01-01:0":{"b": ["Ο Ψαμμήτιχος Α΄ έβαλε την κόρη του Νιτώκρη να υιοθετηθεί από τη Σύζυγο του Θεού της Θήβας και έθεσε υπό έλεγχο την Άνω Αίγυπτο", "bf768452"], "d": ["Ο Ψαμμήτιχος Α΄, το 9ο έτος του, φρόντισε να σταλεί η κόρη του Νιτώκρις στη Θήβα ως θετή κόρη της Σεπενουπέτ (Σύζυγος του Θεού της Θήβας), κόρης του βασιλιά της Κους Ταχάρκα· η Σεπενουπέτ μεταβίβασε την περιουσία της στη Νιτώκρι και έτσι η ναϊκή περιουσία της Θήβας πέρασε στα χέρια των Σαϊτών. Η στήλη υιοθεσίας δείχνει ότι το 9ο έτος του Ψαμμήτιχου απέκτησε τον πλήρη έλεγχο της Θήβας και ότι ο Ταντάμανι είχε χάσει την Άνω Αίγυπτο μέχρι την ημερομηνία εκείνη.", "f750f320"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0662-01-01:0":{"b": ["Ο ασσυριακός στρατός λεηλάτησε τη Θήβα· ο Ταντάμανι αποσύρθηκε νότια, η κυριαρχία της Κους στην Αίγυπτο κατέρρευσε", "777fc1a5"], "d": ["Οι στρατοί του Ασσουρμπανιπάλ, καταδιώκοντας τον Ταντάμανι από τη Μέμφιδα, προχώρησαν μέχρι τη Θήβα και λεηλάτησαν την πόλη· οι ναϊκοί θησαυροί της Θήβας μεταφέρθηκαν στη Νινευή. Ο Ταντάμανι αποσύρθηκε στη Νουβία· η κυριαρχία της Κους στην Άνω Αίγυπτο διαλύθηκε. Αυτή η λεηλασία στην Παλαιά Διαθήκη αναφέρεται ως «Νο-Αμμών» (Ναούμ 3:8).", "3d4dea25"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0663-01-01:0":{"b": ["Άρχισε η XXVI Δυναστεία: ο Ψαμμήτιχος Α΄ ήρθε στην εξουσία στη Σάιδα ως ασσυριακός υποτελής στην Κάτω Αίγυπτο", "f270eac3"], "d": ["Ανάμεσα στους πρίγκιπες του Δέλτα που εγκατέστησε η Ασσυρία στην Αίγυπτο, ο ηγεμόνας της Σάιδας Ψαμμήτιχος Α΄ ξεκίνησε την XXVI (Σαϊτική) Δυναστεία. Σύμφωνα με τον Ηρόδοτο, ο Ψαμμήτιχος ξεχώρισε ανάμεσα στους «δώδεκα βασιλιάδες», εκδιώχθηκε στον βάλτο και απέκτησε ξανά το Δέλτα. Μετά την Ασσυρία και την Κους, η Αίγυπτος περιήλθε ξανά στα χέρια ντόπιας δυναστείας· η απόκτηση της Θήβας και της Άνω Αιγύπτου χρειάστηκε μερικά χρόνια.", "eaebf639"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0663-01-01:1":{"b": ["Ο Ταντάμανι κατέβηκε από την Κους και κατέλαβε ξανά τη Θήβα και τη Μέμφιδα· πολιόρκησε τους ασσυριακούς υποτελείς", "f84c87a4"], "d": ["Ο Ταντάμανι, διάδοχος του Ταχάρκα, σύμφωνα με τη Στήλη του Ονείρου, αφού στέφθηκε στη Νάπατα κατέβηκε με το ποτάμι προς τα βόρεια: προσέφερε στην Ελεφαντίνη προσφορά στον Χνούμ, ήρθε στη Θήβα και στη Μέμφιδα, όπου πέρασε από σφαγή όσους του αντιστάθηκαν και κατέλαβε την πόλη, ενώ οι άρχοντες του Δέλτα κρύφτηκαν ή υποτάχθηκαν. Η προσπάθεια αυτή απείλησε την τάξη του Δέλτα του Ψαμμήτιχου Α΄ και της Ασσυρίας και έφερε την τιμωρητική εκστρατεία της Ασσυρίας.", "d8ce2798"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0670-01-01:0":{"b": ["Ο Ασσαραδδών μπήκε στην Αίγυπτο και κατέλαβε τη Μέμφιδα· ο Ταχάρκα αποσύρθηκε νότια", "a138bcac"], "d": ["Ο βασιλιάς της Ασσυρίας Ασσαραδδών το 10ο έτος του βάδισε στην Αίγυπτο· ο ασσυριακός στρατός έκανε μεγάλη σφαγή στην Αίγυπτο και ο βασιλιάς της Κους Ταχάρκα διέφυγε νότια. Τα πριγκιπάτα του Δέλτα έγιναν ασσυριακοί υποτελείς, η Μέμφιδα και η Βόρεια Αίγυπτος πέρασαν προσωρινά στα χέρια της Ασσυρίας. Ο Ασσαραδδών, καθώς ξεκινούσε νέα εκστρατεία δύο χρόνια αργότερα, πέθανε στον δρόμο.", "4c58b398"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0700-01-01:0":{"b": ["Ο Σενναχηρείμ, στην εκστρατεία του Ιούδα, συναντήθηκε με τον στρατό Κους-Αιγύπτου στην Ελτεκέ", "7f423351"], "d": ["Στην εκστρατεία του βασιλιά της Ασσυρίας Σενναχηρείμ στη Χαναάν, ο αιγυπτιακός στρατός της Κους ήρθε σε βοήθεια του Ιούδα και συγκρούστηκε με την Ασσυρία στην Ελτεκέ· ο ασσυριακός στρατός αποσύρθηκε χωρίς να καταλάβει την Ιερουσαλήμ. Ο Ιώσηπος αφηγείται ότι ο Σενναχηρείμ, μαθαίνοντας ότι ο βασιλιάς της Κους Τιρχάκα ερχόταν με μεγάλο στρατό, έφυγε από το Πηλούσιο. Αυτή είναι η πρώτη άμεση σύγκρουση της Κους-Αιγύπτου με την Ασσυρία.", "0bc942e3"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0724-01-01:0":{"b": ["Ο Πιγιέ (Πανχί) κατέβηκε στην Αίγυπτο: νίκησε τον συνασπισμό του Τεφνάχτ και υπέταξε τους ηγεμόνες της Μέμφιδας και του Δέλτα", "bb36f7c4"], "d": ["Ο Τεφνάχτ της Σάιδας είχε συγκροτήσει συμμαχία που εκτεινόταν από το Δέλτα μέχρι τη Μέμφιδα και τη Μέση Αίγυπτο και είχε πολιορκήσει την Ηρακλεόπολη. Ο Πιγιέ, που έκανε εκστρατεία από τη Νάπατα, το 21ο έτος του κατέβηκε βόρεια, κατέλαβε τις συμμαχικές πόλεις (Ερμούπολη, Μέμφιδα, Ηλιούπολη) και δέχτηκε την παράδοση των πριγκίπων του Δέλτα· έπειτα επέστρεψε στη Νάπατα. Έτσι η Κους έγινε επικεφαλής ολόκληρης της Αιγύπτου (25η Δυναστεία).", "8a8bbba6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0749-01-01:0":{"b": ["Ο βασιλιάς της Κους (Νάπατα) Κάσττα προχώρησε στην Άνω Αίγυπτο· επέδρασε στην Ελεφαντίνη και στη Θήβα", "b0f5be7f"], "d": ["Οι βασιλιάδες της Κους στη Νάπατα, εκμεταλλευόμενοι τον κατακερματισμό της Αιγύπτου στην Γ΄ Ενδιάμεση Περίοδο, ισχυροποιήθηκαν προς τα βόρεια. Από τα μνημεία γίνεται κατανοητό ότι ο Κάσττα επέβαλε επιρροή στην Άνω Αίγυπτο μέχρι την Ελεφαντίνη· η Αμενιρδίς Α΄ (αδελφή του Πιγιέ) από τη δυναστεία της Κους εγκαταστάθηκε στη Θήβα με τον τίτλο «Σύζυγος του Θεού» του Άμμωνα και το αξίωμα αυτό έγινε το μέσο της Κους στη Θήβα. Έτσι προετοιμάστηκε το έδαφος για την ίδρυση της 25ης Δυναστείας.", "3540bb2c"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0924-01-01:0":{"b": ["Ο Σεσώνχις έκανε εκστρατεία στη Χαναάν: η Ιερουσαλήμ και πόλεις του Ισραήλ-Ιούδα μπήκαν στον κατάλογο του Καρνάκ", "1607ae3a"], "d": ["Η εκστρατεία του Σεσώνχι στη Χαναάν συμπίπτει με την αφήγηση της Τορά που αναφέρει ότι έλαβε φόρο από την Ιερουσαλήμ το 5ο έτος του βασιλιά Ροβοάμ (1 Βασιλέων 14:25)· στην Πύλη των Βουβαστιτών στο Καρνάκ παρατάσσονται περίπου 150 ονόματα πόλεων (περίπου πενήντα-εξήντα του Ισραήλ, εκατό του Ιούδα). Και ο Ιώσηπος αφηγείται ότι ο Σισάκ κατέλαβε την Ιερουσαλήμ και πήρε τον θησαυρό. Αυτή η εκστρατεία είναι η μακρύτερη εξωτερική επιχείρηση της Αιγύπτου στην Γ΄ Ενδιάμεση Περίοδο.", "13f6482e"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0944-01-01:0":{"b": ["Ο Α΄ Σεσώνχις (από τη γενιά των Μεσουές/Λίβυων) ίδρυσε την XXII Δυναστεία· πρωτεύουσα η Βούβαστις", "dae122c7"], "d": ["Οι στρατηγοί των Μεσουές λιβυκής καταγωγής είχαν εγκατασταθεί στο Δέλτα μετά το Νέο Βασίλειο· από αυτούς ο Α΄ Σεσώνχις, μετά την XXI Δυναστεία στην Τάνιδα, επανένωσε την Αίγυπτο. Κάνοντας τον γιο του Αρχιερέα του Άμμωνα, συνέδεσε και τη Θήβα με τη δυναστεία. Η εποχή αυτή έδωσε στην Αίγυπτο μια σύντομη ανάκαμψη που την έστρεψε ξανά στην εξωτερική πολιτική (εκστρατεία στη Χαναάν).", "09d0b8f9"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1068-01-01:0":{"b": ["Το Νέο Βασίλειο έληξε: στα τελευταία χρόνια του Ραμσή ΙΑ΄ ο Σμένδης (Τάνις) στο Δέλτα και ο αρχιερέας του Άμμωνα στη Θήβα ήταν στην πράξη ανεξάρτητοι", "1828ceb0"], "d": ["Στην τελευταία περίοδο του Ραμσή ΙΑ΄ το κεντρικό κράτος κατέρρευσε: στη Θήβα ο Αρχιερέας του Άμμωνα Χεριχώρ ελέγχει την Άνω Αίγυπτο, στην Τάνιδα του Δέλτα διοικεί ο Νεσουμπενεμπντέντ (Σμένδης)· η Ιστορία του Βενεμούν καταγράφει αυτή τη διαίρεση (το ταξίδι του Βενεμούν από τον Χεριχώρ στον Σμένδη). Ο Σμένδης ίδρυσε τελικά την XXI Δυναστεία· και η Νουβία βγήκε μέσα σε αυτή την αναταραχή από τον έλεγχο της Αιγύπτου.", "2317479f"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1176-01-01:0":{"b": ["Ο Ραμσής Γ΄ νίκησε τους Λαούς της Θάλασσας στη στεριά (Τζαχί) και στη θάλασσα στο Δέλτα", "9068ae7b"], "d": ["Στο 8ο έτος του Ραμσή Γ΄, οι Πελεσέτ, Τζέκερ, Ντένιεν, Σέρντεν και οι άλλοι Λαοί της Θάλασσας στράφηκαν προς τα αιγυπτιακά σύνορα από ξηρά και θάλασσα· ο αιγυπτιακός στρατός πρώτα στα σύνορα της Χαναάν και έπειτα στη ναυμαχία στις εκβολές του Δέλτα τους σταμάτησε. Τα ανάγλυφα του Μεντινέτ Χαμπού το τεκμηριώνουν. Η Αίγυπτος κράτησε ξανά τη Χαναάν, αλλά μετά από αυτή την εποχή η επιρροή της στην Ανατολική Μεσόγειο άρχισε να φθίνει.", "a7654a37"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1208-01-01:0":{"b": ["Ο Μερνεπτά νίκησε στο δυτικό Δέλτα τη συμμαχία των Λίβυων και των Λαών της Θάλασσας· το όνομα «Ισραήλ» αναφέρθηκε για πρώτη φορά στη Χαναάν", "e512311e"], "d": ["Στο 5ο έτος του Μερνεπτά, οι Μεσουές με επικεφαλής τους Λίμπου και οι «Λαοί που Ήρθαν από τη Θάλασσα» (Εκουές, Τερές, Λούκα, Σαρδάνα, Σεκελές) κατέλαβαν το δυτικό Δέλτα· ο αιγυπτιακός στρατός τους διέλυσε σε εξάωρη μάχη στην Περιρέ. Η στήλη νίκης που αφηγείται τα ίδια γεγονότα κατονομάζει στη Χαναάν την Ασκάλων, τη Γκέζερ, το Γενοάμ και το «Ισραήλ»· αυτή είναι η αρχαιότερη γνωστή αναφορά του ονόματος Ισραήλ.", "6a9d6afc"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1258-01-01:0":{"b": ["«Αιώνια Συνθήκη» μεταξύ Ραμσή Β΄ και Χατουσίλι Γ΄: ο αιγυπτιοχετιτικός πόλεμος έληξε", "100f2a75"], "d": ["Στο 21ο έτος του Ραμσή Β΄, οι Χετταίοι απεσταλμένοι έφεραν στην Πι-Ραμσές την πινακίδα της συνθήκης. Η συνθήκη τερμάτισε τον περίπου δεκαπενταετή πόλεμο στη Συρία: οι δύο πλευρές παραιτήθηκαν από περαιτέρω σχέδια κατακτήσεων στη Συρία, έκαναν αμυντική συμμαχία, δέχτηκαν την έκδοση φυγάδων και την αμοιβαία βοήθεια. Σύμφωνα με τη σύνοψη του Breasted, το σύνορο δεν αναφέρεται στο κείμενο· η σφαίρα επιρροής των δύο κρατών έμεινε στην de facto κατάσταση (η ζώνη Κάδεσ-Αμουρρού στη Χάττι, η Χαναάν στην Αίγυπτο).", "9b723519"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1273-01-01:0":{"b": ["Ο Ραμσής Β΄ αντιμετώπισε στην Κάδεσ τους Χετταίους του Μουβατάλι Β΄· το αποτέλεσμα έμεινε ισόπαλο", "f5ad96db"], "d": ["Ο Ραμσής Β΄ συναντήθηκε μπροστά στην Κάδεσ, στις όχθες του Ορόντη, με τον χετιτικό στρατό· με την ενέδρα των χετιτικών πολεμικών αρμάτων ο αιγυπτιακός στρατός έφτασε στο σημείο να διαλυθεί, ο Ραμσής με τη δική του φρουρά αντεπιτέθηκε και τους απώθησε. Η μάχη δεν έδωσε οριστικό αποτέλεσμα· η Κάδεσ και η Αμουρρού έμειναν υπό χετιτικό έλεγχο, το βόρειο σύνορο της Αιγύπτου έμεινε πάλι στις ακτές της Χαναάν.", "b58cad94"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1293-01-01:0":{"b": ["Ο Σέτι Α΄ έκανε εκστρατεία από τη Νότια Χαναάν μέχρι τη φοινικική ακτή: η Αίγυπτος κυριάρχησε ξανά στη Χαναάν και στη λιβανική ακτή, κατέλαβε την Κάδεσ", "ad7bf1cd"], "d": ["Σύμφωνα με τα ανάγλυφα του Καρνάκ, η εκστρατεία του 1ου έτους του Σέτι Α΄ υπέταξε πρώτα τους βεδουίνους Σάσου, έπειτα, ανεβαίνοντας βόρεια μέσω της Παλαιστίνης, το Πεχέρ και το Μπεθ-Σεάν, το Γενοάμ, την Τύρο και τους άρχοντες του Λιβάνου. Στην πάνω σειρά των αναγλύφων απεικονίζεται και η κατάληψη της Κάδεσ. Ο Breasted επισημαίνει ότι το μόνιμο βόρειο σύνορο δεν εκτεινόταν πέρα από τη γραμμή ανατολής-δύσης κατά μήκος της φοινικικής ακτής και ότι η χετιτική δύναμη δεν είχε σπάσει· αυτό είναι το παρασκήνιο της μάχης της Κάδεσ του Ραμσή Β΄.", "aa320c30"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1339-01-01:0":{"b": ["Στην εποχή της Αμάρνα η κυριαρχία της Αιγύπτου στη Βόρεια Συρία διαλύθηκε· η Αμουρρού και η Κάδεσ μετακινήθηκαν στη σφαίρα επιρροής των Χετταίων", "90d00c5a"], "d": ["Τα γράμματα της Αμάρνα (EA) δείχνουν ότι οι υποτελείς της Βόρειας Συρίας (ο Αζίρου από την Αμουρρού, οι ηγεμόνες της Κάδεσ) έπαιζαν μεταξύ Αιγύπτου, Μιτάνι και Χάττι και ότι η Αίγυπτος δεν μπορούσε να παρέμβει στην περιοχή. Ως αποτέλεσμα των εκστρατειών του Χετταίου βασιλιά Α΄ Σουππιλουλίουμα που εξάντλησαν το Μιτάνι, η Αμουρρού και η Κάδεσ μπήκαν στην χετιτική επιρροή· έτσι το βόρειο σύνορο της Αιγύπτου στη Συρία αποσύρθηκε στη Χαναάν.", "c876708d"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1347-01-01:0":{"b": ["Ο Αμένοφις Δ΄ (Ακενατών) μετέφερε την πρωτεύουσα της Αιγύπτου στην Αχετατόν (Αμάρνα)", "53cadac3"], "d": ["Ο Ακενατών, κάνοντας τη λατρεία του Ατόν κρατική θρησκεία, ανακήρυξε πρωτεύουσα μια νέα πόλη (Αχετατόν) που άνοιξε στην έρημο της Μέσης Αιγύπτου· οι «Στήλες Ορίων» που καθορίζουν τα όρια της πόλης χρονολογούνται στα έτη 4-5. Τα γράμματα της Αμάρνα δείχνουν ότι στην εποχή αυτή οι υποτελείς της Συρίας ζητούσαν βοήθεια αλλά η Αίγυπτος δεν ανταποκρινόταν.", "a7911bcf"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1424-01-01:0":{"b": ["Ο Αμένοφις Β΄ έφτασε στη Νάπατα στη Νουβία και έστησε νότια συνοριακή στήλη: το νοτιότερο σημείο της Αιγύπτου", "2f61f824"], "d": ["Ο Αμένοφις Β΄ κατά την επιστροφή από την εκστρατεία στη Συρία (Ιούλιο) πέρασε στη Νουβία· σύμφωνα με τις επιγραφές των ναών στην Ελεφαντίνη και την Αμάντα, από τους εφτά πρίγκιπες που έφερε από τη Συρία έβαλε να κρεμαστούν οι έξι στα τείχη της Θήβας και ο έβδομος στα τείχη της Νάπατα. Σύμφωνα με τον Breasted, ο βασιλιάς έστησε στη Νάπατα ή αμέσως πάνω από αυτήν μια στήλη που δείχνει το νότιο σύνορο: η πραγματική κυριαρχία της Αιγύπτου στη Νουβία έτσι εκτάθηκε πέρα από το Τόμπος (Τρίτος Καταρράκτης) μέχρι την περιοχή του Τέταρτου Καταρράκτη.", "31d51fb0"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1446-01-01:0":{"b": ["Ο Θουθμώσης Γ΄ πέρασε τον Ευφράτη και μπήκε στα εδάφη του Μιτάνι· έστησε συνοριακή στήλη στη Ναχαρίν", "ebdbeebe"], "d": ["Στο 33ο έτος ο Θουθμώσης Γ΄ προχώρησε από το Ρετένου, πέρασε τον Ευφράτη, λεηλάτησε τις πόλεις της Ναχαρίν και έστησε συνοριακή στήλη ανατολικά του ποταμού· έβαλε μια δεύτερη δίπλα στη στήλη του πατέρα του. Η εκστρατεία αυτή είναι το βορειότερο άκρο της αιγυπτιακής επιρροής και δείχνει το κατώφλι της άμεσης σύγκρουσης με το Μιτάνι.", "e7a917e6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1456-01-01:0":{"b": ["Ο Θουθμώσης Γ΄ νίκησε στη Μεγιδδώ τον χαναανιτικό συνασπισμό υπό την Κάδεσ· η Χαναάν-Συρία περιήλθε στην αιγυπτιακή κυριαρχία", "439dc6e8"], "d": ["Στο 23ο έτος του Θουθμώσης Γ΄, την 21η ημέρα του 1ου μήνα Σέμου, μπροστά στη Μεγιδδώ νίκησε τον χαναανιτικό συνασπισμό με επικεφαλής τον ηγεμόνα της Κάδεσ· ο εχθρός διέφυγε στην πόλη και η Μεγιδδώ παραδόθηκε μετά από μακρά πολιορκία. Η εκστρατεία αυτή, καταγεγραμμένη στα Χρονικά του Καρνάκ, έκανε μόνιμη την εξάρτηση της Χαναάν και της Νότιας Συρίας από την Αίγυπτο και ήταν η αρχή της επέκτασης της αυτοκρατορίας.", "8c75d558"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1498-01-01:0":{"b": ["Ο Θουθμώσης Α΄ έκανε ασιατική εκστρατεία που έφτασε μέχρι τις όχθες του Ευφράτη (Ναχαρίν)", "50ce0679"], "d": ["Σύμφωνα με τις επιγραφές του Αχμόσε-Πεννεκχμπέτ και του Αχμόσε-Εμπάνα, ο Θουθμώσης Α΄ μετά την εκστρατεία στη Νουβία έκανε μεγάλη εκστρατεία στη Ναχαρίν· ο Θουθμώσης Γ΄ αργότερα προσθέτει τη δική του στήλη δίπλα στη συνοριακή στήλη που είχε στήσει ο πατέρας του στον Ευφράτη. Αυτή είναι η πρώτη καταγεγραμμένη περίοδος που η αιγυπτιακή επιρροή έφτασε μέχρι τον Ευφράτη.", "bc058844"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1524-01-01:0":{"b": ["Ο Άχμοσε έκανε εκστρατεία στην Κάτω Νουβία και κατέστειλε τους Νουβίους των υψιπέδων", "dbbd94b7"], "d": ["Ο Άχμοσε, αφού νίκησε τους Ασιάτες, ανέβηκε με το ποτάμι νότια, στο Χεντ-χεν-νεφέρ, και κατέστειλε τους Νουβίους των υψιπέδων. Αυτή η εκστρατεία είναι το πρώτο βήμα της διαδικασίας προσάρτησης στην Αίγυπτο της Κάτω Νουβίας, που ήταν στα χέρια της Κέρμα από την εποχή της γραμμής φρουρίων του Μέσου Βασιλείου.", "df3be70d"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1529-01-01:0":{"b": ["Ο Άχμοσε κατέλαβε την Αβάρις, πρωτεύουσα των Υξώς, και πολιόρκησε και κατέλαβε τη Σαρουχέν", "b7bb3099"], "d": ["Ο Άχμοσε πολιόρκησε και κατέλαβε την Αβάρις στο Ανατολικό Δέλτα· οι Υξώς διέφυγαν στην Ασία και τους καταδίωξε μέχρι τη Σαρουχέν στη Νότια Χαναάν. Η επιγραφή του Άχμοσε, γιου της Εμπάνα, αναφέρει ότι η Σαρουχέν πολιορκήθηκε 6 χρόνια. Έτσι το Δέλτα της Αιγύπτου βγήκε από τον έλεγχο των Υξώς και η Αίγυπτος βρέθηκε σε θέση να ασκεί πολιτική επιρροή στη Χαναάν.", "48e6f876"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1549-01-01:0":{"b": ["Ο Α΄ Άχμοσε ανέβηκε στον θρόνο στη Θήβα· άρχισαν η XVIII Δυναστεία και η περίοδος του Νέου Βασιλείου", "0798cfa3"], "d": ["Ο Άχμοσε, αδελφός του Καμόσε, του τελευταίου βασιλιά της XVII Δυναστείας στη Θήβα, ανέβηκε στον θρόνο σε παιδική ηλικία· κατά τη βασιλεία του θα έδιωχνε τους Υξώς από την Αίγυπτο και θα αποκαθιστούσε την κυριαρχία στη Νουβία και στη Χαναάν, ξεκινώντας την XVIII Δυναστεία και την περίοδο του Νέου Βασιλείου. Η άνοδος στον θρόνο δεν είναι το τέλος των Υξώς, αλλά η αρχή της τελευταίας φάσης του αγώνα.", "a003c4aa"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1649-01-01:0":{"b": ["Η Αίγυπτος διαιρέθηκε στα δύο: οι Υξώς (XV Δυναστεία) κυβέρνησαν από την Αβάρις την Κάτω και Μέση Αίγυπτο, η XVII Δυναστεία στη Θήβα την Άνω Αίγυπτο", "cd743737"], "d": ["Οι «ξένοι ηγεμόνες» (Υξώς) χαναανιτικής καταγωγής, εγκατεστημένοι στην Αβάρις στο Ανατολικό Δέλτα, ίδρυσαν την XV Δυναστεία και κυβέρνησαν την Κάτω Αίγυπτο και τη Μέση Αίγυπτο μέχρι την Κούσαε (Κουσίγια)· η ντόπια XVII Δυναστεία στη Θήβα κρατούσε την Άνω Αίγυπτο. Νότια της Θήβας το βασίλειο της Κέρμα στάθηκε ως ανεξάρτητη δύναμη. Ότι η Αβάρις ήταν η πρωτεύουσα των Υξώς επιβεβαιώνεται στον Breasted με την αφήγηση της πολιορκίας του Άχμοσε.", "6bb8eb9b"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1866-01-01:0":{"b": ["Ο Σενουσρέτ Γ΄ στη Σεμνά έφερε το νότιο σύνορο της Αιγύπτου στον Β΄ Καταρράκτη· απαγόρευσε τη διέλευση των Νουβίων", "753ef5fd"], "d": ["Η στήλη της Σεμνά του 8ου έτους του Σενουσρέτ Γ΄ καθορίζει το «νότιο σύνορο»: απαγορεύεται στους Νουβίους, εκτός από όσους έρχονται στην Ικέν για εμπόριο, να περνούν αυτή τη γραμμή από ξηρά ή ποτάμι. Ο βασιλιάς ίδρυσε στην Κάτω Νουβία αλυσίδα φρουρίων (Μπουχέν, Σεμνά, Κούμμα, Ουρονάρτι κ.ά.) και σταμάτησε την προς τα βόρεια επέκταση της Κέρμα. Αυτό είναι το νοτιότερο μόνιμο σύνορο του Μέσου Βασιλείου στη Νουβία.", "e50a591d"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1984-01-01:0":{"b": ["Ο Αμενεμχέτ Α΄ ίδρυσε την XII Δυναστεία· η πρωτεύουσα μεταφέρθηκε στην Ιτζ-τάουι", "26c43dad"], "d": ["Ο Αμενεμχέτ Α΄, που από βεζίρης έγινε βασιλιάς, ίδρυσε την XII Δυναστεία και μετέφερε την πρωτεύουσα από τη Θήβα στη νέα πόλη (Ιτζ-τάουι) ανάμεσα στη Μέμφιδα και το Φαγιούμ. Η δυναστεία αυτή καθιέρωσε την πιο σταθερή περίοδο του Μέσου Βασιλείου και το σύστημα φρουρίων προς τη Νουβία.", "55432fe0"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2015-01-01:0":{"b": ["Ο Μεντουχοτέπ Β΄ νίκησε την Ηρακλεόπολη και επανένωσε την Αίγυπτο (Σεματάουι)", "dbc6136f"], "d": ["Γύρω στο 39ο έτος της βασιλείας του, ο Μεντουχοτέπ Β΄, εξαλείφοντας την Ηρακλεόπολη, έδεσε την Άνω και Κάτω Αίγυπτο σε ενιαία διοίκηση και πρόσθεσε στον τίτλο του το όνομα «Αυτός που ενώνει τις Δύο Χώρες» (Σεματάουι). Η κεντρική διοίκηση μεταφέρθηκε στη Θήβα· οι εξουσίες των νομαρχών περιορίστηκαν.", "d3ad8b02"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2054-01-01:0":{"b": ["Ο Μεντουχοτέπ Β΄ ανέβηκε στον θρόνο στη Θήβα· άρχισε η περίοδος του Μέσου Βασιλείου και ο πόλεμος κατά της Ηρακλεόπολης εντάθηκε", "edde038d"], "d": ["Η μακρά βασιλεία του Μεντουχοτέπ Β΄ (51 χρόνια) θεωρείται η αρχή του Μέσου Βασιλείου. Στο πρώτο μισό της βασιλείας του η Θήβα ήταν σε πόλεμο με την Ηρακλεόπολη· στο 14ο έτος του, όταν οι δυνάμεις της Ηρακλεόπολης βεβήλωσαν το ιερό νεκροταφείο στην Άβυδο, ο βασιλιάς έστειλε στρατό προς τα βόρεια. Η πραγματική ένωση της Αιγύπτου έγινε πολύ αργότερα, στο 39ο έτος της βασιλείας του (επόμενο λήμμα).", "5db4eeba"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2124-01-01:0":{"b": ["Στη Θήβα άρχισε η XI Δυναστεία: η δυναστεία των Ιντεφ ίδρυσε ανεξάρτητο βασίλειο στην Άνω Αίγυπτο", "0e021743"], "d": ["Οι νομάρχες της Θήβας από τη γενιά των Ιντεφ πήραν τον τίτλο του βασιλιά και ίδρυσαν στο νότιο άκρο της Άνω Αιγύπτου (από την Ελεφαντίνη ως την Άβυδο) δικό τους βασίλειο. Ο επόμενος Ιντεφ αναφέρει στην επιγραφή του ότι κατέλαβε τον νομό Τινις όπου βρίσκεται η Άβυδος και «άνοιξε όλα τα φρούριά του»· έτσι το σύνορο Θήβας-Ηρακλεόπολης χαράχτηκε γύρω από την Άβυδο.", "eddec482"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2159-01-01:0":{"b": ["Στην Ηρακλεόπολη (Χενεν-νεσουτ) IX-X Δυναστεία: τη Βόρεια Αίγυπτο κυβέρνησε η δυναστεία των Χέτι", "9dde2d0c"], "d": ["Στην Α΄ Ενδιάμεση Περίοδο το κενό της Μέμφιδας το κάλυψε η δυναστεία στην Ηρακλεόπολη· πιστοί νομάρχες, όπως ο Τεφίμπι, διοικητής της Σιούτ στη Μέση Αίγυπτο, πολέμησαν στο πλευρό αυτού του βασιλείου κατά του νότου (Θήβα). Η επιγραφή του τάφου της Σιούτ αφηγείται την προέλαση των Νότιων από την Ελεφαντίνη προς τα βόρεια και ότι αποκρούστηκαν μέχρι το «νότιο σύνορο». Έτσι η Αίγυπτος διαιρέθηκε σε δύο κύριες δυνάμεις, την Ηρακλεόπολη (Βορράς) και τη Θήβα (Νότος).", "5e8484b5"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2180-01-01:0":{"b": ["Το Παλαιό Βασίλειο κατέρρευσε: μετά τον Πεπί Β΄ το κεντρικό κράτος διαλύθηκε, άρχισε η Α΄ Ενδιάμεση Περίοδος", "0339e96b"], "d": ["Μετά τη μακρά βασιλεία του Πεπί Β΄ η VI Δυναστεία έληξε· το βασίλειο διασπάστηκε σε περιοχές όπου οι νομάρχες (επαρχιακοί διοικητές) παρέμειναν στην πράξη ανεξάρτητοι. Οι επιγραφές των τάφων (Σιούτ, Ελεφαντίνη κ.ά.) δείχνουν ότι οι τοπικοί διοικητές έδιναν χρονολογίες στο όνομά τους και κινητοποιούσαν δικό τους στρατό. Οι βραχύβιες VII-VIII Δυναστείες στη Μέμφιδα δεν μπόρεσαν να ελέγξουν ολόκληρη τη χώρα.", "67f3dd29"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2279-01-01:0":{"b": ["Οι εκστρατείες του διοικητή της Ελεφαντίνης Χαρχούφ στη χώρα Γιαμ: διπλωματικός-εμπορικός δεσμός πέρα από τη Νουβία", "705b9808"], "d": ["Ο διοικητής της Ελεφαντίνης Χαρχούφ έκανε για τον Μερενρέ και τον Πεπί Β΄ αρκετές εκστρατείες προς τα νότια, στη χώρα Γιαμ· στην επιγραφή του αφηγούνται ο δρόμος που κυριάρχησε και τα προϊόντα που έφερε. Και το γράμμα που του έγραψε ο παιδί-βασιλιάς Πεπί Β΄ διατηρείται στην επιγραφή του τάφου. Οι εκστρατείες αυτές είναι καταγραφές επαφής με τις κοινότητες της προ-Κέρμα/Παλαιάς Κέρμα στο νότιο σύνορο του Παλαιού Βασιλείου.", "31a49890"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2299-01-01:0":{"b": ["Στη VI Δυναστεία, υπό τον Ουένι, μεγάλη εκστρατεία στα σύνορα της Χαναάν με νουβιακές μονάδες", "69c94c55"], "d": ["Σύμφωνα με την αυτοβιογραφία του Ουένι, ο βασιλιάς συγκέντρωσε στρατό δεκάδων χιλιάδων ανδρών κατά των «Ασιατών Κατοίκων των Αμμόλοφων»· ο στρατός αποτελούνταν από μονάδες που στρατολογήθηκαν από τη Νότια Αίγυπτο (μέχρι την Ελεφαντίνη), από τον Βορρά και επίσης από νουβιακές φυλές (Ιρτζέτ, Μετζά, Γιαμ, Ουαουάτ, Κάου). Το κείμενο δείχνει ότι το Παλαιό Βασίλειο χρησιμοποιούσε τη Νουβία ως δεξαμενή στρατιωτών και μπορούσε να κάνει εκστρατεία μέχρι τη Νότια Χαναάν.", "4a1574fe"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2559-01-01:0":{"b": ["Χτίστηκε η Μεγάλη Πυραμίδα του Χουφού (Χέοπα) στη Γκίζα", "282359fc"], "d": ["Η πυραμίδα του ηγεμόνα της IV Δυναστείας Χουφού στη Γκίζα είναι σύμβολο της κινητοποίησης εργατικού δυναμικού και πόρων του Παλαιού Βασιλείου. Η αφήγηση των αιγύπτιων ιερέων που μεταφέρει ο Ηρόδοτος παρουσιάζει τον Χουφού ως τύραννο που έκλεισε τους ναούς και ανάγκασε τον λαό να μεταφέρει πέτρες· αυτό είναι η οπτική της επόμενης εποχής, όχι σύγχρονο έγγραφο.", "6bc26700"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2685-01-01:0":{"b": ["Ο Τζοσέρ (III Δυναστεία) ανέβηκε στον θρόνο· Παλαιό Βασίλειο και Βαθμιδωτή Πυραμίδα της Σακκάρα", "23e99ef4"], "d": ["Με την εξουσία του Τζοσέρ (Νετσερικχέτ) αρχίζει το Παλαιό Βασίλειο με κέντρο τη Μέμφιδα· η Βαθμιδωτή Πυραμίδα, το πρώτο μεγάλο δείγμα λίθινης αρχιτεκτονικής, χτίστηκε για αυτόν. Στην περίοδο αυτή το κράτος διοικεί την Κοιλάδα του Νείλου και το Δέλτα από το κέντρο· τα μεταλλεία του Σινά και το νουβιακό σύνορο (Ελεφαντίνη) βρίσκονται υπό τον έλεγχο του κράτους.", "3b6eb1c6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-3099-01-01:0":{"b": ["Ο Ναρμέρ (Μηνάς) ένωσε την Άνω και Κάτω Αίγυπτο· η I Δυναστεία και η Μέμφιδα έγινε πρωτεύουσα", "cd3fadb1"], "d": ["Ο ηγεμόνας της Άνω Αιγύπτου (περιοχή Τινις/Άβυδος) Ναρμέρ, σύμφωνα με τους περισσότερους Αιγυπτιολόγους, είναι το ίδιο πρόσωπο με τον Μηνά. Με την προσάρτηση της Κάτω Αιγύπτου στη διοίκησή του, η Κοιλάδα του Νείλου και το Δέλτα έγιναν για πρώτη φορά ενιαίο κράτος. Σύμφωνα με την παλιά αφήγηση, ο Μηνάς, εκτρέποντας την κοίτη του Νείλου, ίδρυσε τη θέση της Μέμφιδας· η ένωση δεν είναι ένα γεγονός αλλά αποτέλεσμα μακράς διαδικασίας που συνεχιζόταν από τη Naqada III.", "f5802ba8"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0069-07-01:0":{"b": ["Ο Βεσπασιανός ανακηρύχθηκε αυτοκράτορας στην Αλεξάνδρεια: η πηγή σιτηρών της Αιγύπτου καθόρισε την τύχη του εμφυλίου πολέμου", "02b78348"], "d": ["Ο έπαρχος της Αιγύπτου Τιβέριος Αλέξανδρος έβαλε τις λεγεώνες στην Αλεξάνδρεια να ορκιστούν πίστη στο όνομα του Βεσπασιανού· ο όρκος έγινε την 1η Ιουλίου και ο Βεσπασιανός θεώρησε την ημέρα αυτή ως ημέρα της δικής του ανόδου στον θρόνο. Ο ιουδαϊκός στρατός ορκίστηκε δύο ημέρες αργότερα ενώπιον του Βεσπασιανού. Η παραγωγή σιτηρών της Αιγύπτου θεωρείται το στρατηγικό στήριγμα αυτής της πρωτοβουλίας.", "da411a30"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0115-01-01:0":{"b": ["Ιουδαϊκή εξέγερση στην Αίγυπτο, στην Κυρήνη και στην Κύπρο: επί Τραϊανού η Ρώμη κατέστειλε την περιοχή με δυσκολία", "54787782"], "d": ["Ενώ συνεχιζόταν η εκστρατεία του Τραϊανού κατά των Πάρθων, στην Κυρήνη οι Ιουδαίοι υπό την ηγεσία του Ανδρέα έσφαξαν Ρωμαίους και Έλληνες· σύμφωνα με τον Δίωνα, παρόμοια γεγονότα έγιναν στην Αίγυπτο και στην Κύπρο και ο αριθμός των νεκρών εκφράστηκε σε εκατοντάδες χιλιάδες. Ο Λούσιος Κουίετος, που έστειλε ο Τραϊανός, κατέστειλε την εξέγερση· στους Ιουδαίους απαγορεύτηκε η είσοδος στην Κύπρο.", "40f5a14f"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0172-01-01:0":{"b": ["Εξέγερση των Βουκόλων: μια εξέγερση στο Δέλτα απείλησε την Αλεξάνδρεια, την κατέστειλε ο Αβίδιος Κάσσιος", "5f94e6bf"], "d": ["Ο λαός του Δέλτα που αποκαλούνταν Βουκόλοι (βοσκοί) εξεγέρθηκε υπό την ηγεσία ενός ιερέα ονόματι Ισίδωρου· σύμφωνα με τον Δίωνα, οι επαναστάτες νίκησαν ρωμαϊκή μονάδα και λίγο έλειψε να καταλάβουν την Αλεξάνδρεια. Ο Κάσσιος, που στάλθηκε από τη Συρία, διασπώντας την ενότητα των επαναστατών κατέστειλε την εξέγερση.", "ab9f3aff"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0175-01-01:0":{"b": ["Ο Αβίδιος Κάσσιος ανακήρυξε τον εαυτό του αυτοκράτορα στη Συρία και στην Αίγυπτο· τρεις μήνες αργότερα δολοφονήθηκε", "ce33ca9d"], "d": ["Ο Κάσσιος, διοικητής των ανατολικών επαρχιών, με την είδηση του θανάτου του Μάρκου Αυρήλιου ανακήρυξε αυτοκρατορία· η εξέγερση εξαπλώθηκε στη Συρία και στην Αίγυπτο (στον Δίωνα αναφέρεται ότι ο έπαρχος της Αιγύπτου Φλάβιος Καλβίσιος, λόγω της σχέσης του με την εξέγερση, δεν θανατώθηκε αργότερα αλλά εξορίστηκε σε νησί). Ο Κάσσιος, σύμφωνα με τον Δίωνα, μετά από «όνειρο αυτοκρατορίας» τριών μηνών και έξι ημερών, σκοτώθηκε από έναν από τους δικούς του αξιωματικούς· ο Μάρκος Αυρήλιος επισκέφθηκε την Αίγυπτο και τη Συρία χωρίς να τιμωρήσει κανέναν.", "d3821bc7"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0270-01-01:0":{"b": ["Η Παλμύρα (Ζηνοβία) κατέλαβε την Αίγυπτο· ο Ρωμαίος στρατηγός Πρόβος ηττήθηκε", "54568441"], "d": ["Ο στρατηγός της Παλμύρας Ζαβδάς, που ενεργούσε στο όνομα της Ζηνοβίας, μπήκε στην Αίγυπτο με στρατό εβδομήντα χιλιάδων· ο Ρωμαίος στρατηγός Τενάγκινος Πρόβος κατέλαβε για κάποιο διάστημα την Αλεξάνδρεια αλλά ηττήθηκε και κλείστηκε στο φρούριο της Βαβυλώνας, και όταν αιχμαλωτίστηκε αυτοκτόνησε. Η Αίγυπτος θεωρήθηκε για ένα-δύο χρόνια μέρος του Κράτους της Παλμύρας στο όνομα της Ζηνοβίας.", "ea44ec63"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0297-01-01:0":{"b": ["Ο Domitius Domitianus ανακηρύχθηκε αυτοκράτορας στην Αίγυπτο· ο Διοκλητιανός πολιορκώντας τις Θήβες και στη συνέχεια την Αλεξάνδρεια κατέστειλε την εξέγερση", "3c765005"], "d": ["Ως αντίδραση στη φορολογική μεταρρύθμιση και στην απόσυρση των ρωμαϊκών μονάδων στο παρθικό μέτωπο, ο Domitius Domitianus ανακηρύχθηκε Αύγουστος στην Αίγυπτο τον Ιούλιο-Αύγουστο του 297· το μεγαλύτερο μέρος της Αιγύπτου, μαζί με την Αλεξάνδρεια, τον αναγνώρισε. Ο Διοκλητιανός το φθινόπωρο κατέστειλε τους στασιαστές των Θηβών και πολιόρκησε την Αλεξάνδρεια· ο Domitianus πέθανε τον Δεκέμβριο του 297, την άμυνα της πόλης συνέχισε ο Aurelius Achilleus και η πόλη, μετά από πολιορκία περίπου οκτώ μηνών, παραδόθηκε πιθανότατα τον Μάρτιο του 298.", "8d6ec081"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0298-01-01:0":{"b": ["Ο Διοκλητιανός μετέφερε το νότιο σύνορο της Αιγύπτου στη γραμμή Ελεφαντίνη/Φίλες· η Κάτω Νουβία αφέθηκε στους Nobatae", "725574bb"], "d": ["Ο Προκόπιος αφηγείται ότι ο Διοκλητιανός, βλέποντας το κόστος της διατήρησης της ευρείας ερήμου (Δωδεκασχοίνος) στο νοτιότερο άκρο της Αιγύπτου, άφησε το νότο της Ελεφαντίνης στους Nobatae και στους Blemmyes και καθόρισε το σύνορο στην Ελεφαντίνη (μεταφέρεται επίσης ότι σε αντάλλαγμα καθορίστηκε ετήσια πληρωμή). Η ρωμαϊκή διοίκηση έτσι αποσύρθηκε από το σύνορο της Ιεράς Συκαμίνου που είχε χαράξει ο Αύγουστος.", "bba78e53"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0349-01-01:0":{"b": ["Ο βασιλιάς του Aksum Ezana νίκησε την Kush· το βασίλειο του Meroe έληξε (περ. 350 μ.Χ.)", "7c9d95d7"], "d": ["Ο βασιλιάς του Aksum Ezana επιτέθηκε στο βασίλειο της Kush, που είχε αποδυναμωθεί από την πίεση των Noba και των Blemmyes· οι επιγραφές του Ezana αφηγούνται την εκστρατεία του εναντίον των λαών Noba και Kasu (Kush), στο Meroe βρέθηκαν δύο αποσπασματικές ελληνικές επιγραφές που ανήκουν στη νίκη του Aksum. Οι τελευταίες πυραμίδες στο Meroe χρονολογούνται στα μέσα του 4ου αιώνα· το κράτος της Kush διαλύθηκε και χωρίστηκε στα βασίλεια της Nobatia, της Makuria και της Alodia.", "49687083"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0391-01-01:0":{"b": ["Ο Θεόφιλος κατεδάφισε το Σεραπείο στην Αλεξάνδρεια: το κέντρο ειδωλολατρικής λατρείας στην Αίγυπτο έκλεισε", "119a26c7"], "d": ["Μετά τα διατάγματα του Θεοδοσίου Α' που απαγόρευαν τις ειδωλολατρικές λατρείες, ο επίσκοπος της Αλεξάνδρειας Θεόφιλος κατεδάφισε τον ναό του Σεράπιδος (Σεραπείο)· η ένταση ανάμεσα σε χριστιανούς και ειδωλολάτρες στην πόλη κορυφώθηκε με αυτό το γεγονός. Η τύχη των ιερών κειμένων και των συλλογών βιβλίων είναι αμφισβητούμενη.", "5128d07a"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0395-01-17:0":{"b": ["Ο Θεοδόσιος Α' πέθανε· η αυτοκρατορία χωρίστηκε οριστικά στα δύο, η Αίγυπτος έμεινε στη Ανατολική Ρώμη (Αρκάδιος)", "54a12472"], "d": ["Με τον θάνατο του Θεοδοσίου, οι γιοι του Αρκάδιος πήρε την Ανατολή, ο Ονώριος τη Δύση· η Αίγυπτος, αν και ήταν ο κύριος προμηθευτής των αναγκών σε σιτηρά της Ρώμης, έμεινε επαρχία της Ανατολικής Αυτοκρατορίας (Βυζάντιο) και τους επόμενους αιώνες έγινε η πηγή σιτηρών της Κωνσταντινούπολης.", "c418b085"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0451-10-08:0":{"b": ["Σύνοδος της Χαλκηδόνας: ο πατριάρχης Αλεξάνδρειας Διόσκορος καταδικάστηκε· η Εκκλησία της Αιγύπτου χωρίστηκε από την αυτοκρατορική Εκκλησία", "5d2d05c6"], "d": ["Όταν η Σύνοδος της Χαλκηδόνας καταδίκασε τον πατριάρχη Αλεξάνδρειας της Αιγύπτου Διόσκορο, οι περισσότεροι χριστιανοί της Αιγύπτου δεν δέχθηκαν τις αποφάσεις· έτσι στην Αίγυπτο χωρίστηκαν η Κοπτική (Αιγυπτιακή) Εκκλησία και η αυτοκρατορική Εκκλησία (Μελχίτες). Ο διχασμός αυτός προετοίμασε το έδαφος της πολιτικής απομάκρυνσης της Αιγύπτου από το Βυζάντιο τους επόμενους αιώνες.", "0d1827cd"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0019-01-01:0":{"b": ["Συνθήκη ανάμεσα στον Αύγουστο και τον Φραάτη Δ': επιστράφηκαν τα ρωμαϊκά λάβαρα του Κράσσου", "be5f8bda"], "d": ["Τα χαμένα ρωμαϊκά λάβαρα του Κράσσου και του Αντωνίου επιστράφηκαν στον Αύγουστο από τον Φραάτη Δ' ως διπλωματική χειρονομία. Η συνθήκη ενίσχυσε τον Ευφράτη ως ρωμαιοπαρθικό σύνορο και άφησε την Αρμενία ως ουδέτερη ζώνη.", "8cca70ad"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0039-01-01:0":{"b": ["Ο Πάκορος και ο Λαβιηνός εισέβαλαν στη Συρία και στην Παλαιστίνη", "68669aa1"], "d": ["Ο Πάρθος πρίγκιπας Πάκορος και ο Λαβιηνός, που διέφυγε από τη Ρώμη και κατέφυγε στους Πάρθους, εισέβαλαν στις ρωμαϊκές επαρχίες της Συρίας και κατέλαβαν την Αντιόχεια και την Παλαιστίνη. Ο στρατηγός του Αντωνίου Βεντίδιος το 38 νίκησε τους Πάρθους στα Γίνδαρα και ανέκτησε την περιοχή.", "c3d65f7c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0052-01-01:0":{"b": ["Μάχη των Κάρρων (Harran): ο Σουρήνας εξόντωσε τον ρωμαϊκό στρατό του Κράσσου", "3a91cd75"], "d": ["Οι ρωμαϊκές λεγεώνες του Κράσσου ηττήθηκαν κοντά στις Κάρρες από το παρθικό ιππικό και τους έφιππους τοξότες· ο Κράσσος σκοτώθηκε. Η μάχη είναι μία από τις βαρύτερες ήττες της Ρώμης στην Ανατολή και ενίσχυσε το σύνορο του Ευφράτη υπέρ των Πάρθων.", "3f9d31bb"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0091-01-01:0":{"b": ["Ο Σύλλας και ο Πάρθος απεσταλμένος Ωροβάζος συναντήθηκαν στον Ευφράτη· πρώτη διπλωματική επαφή Ρώμης-Πάρθων", "f8913f2b"], "d": ["Ο κυβερνήτης της Καππαδοκίας Σύλλας συναντήθηκε στις όχθες του Ευφράτη με τον απεσταλμένο του βασιλιά των Πάρθων Μιθριδάτη Β', Ωροβάζο· η Ρώμη και οι Πάρθοι ήρθαν για πρώτη φορά σε επίσημη επαφή. Ο Ευφράτης θα γίνει αργότερα το σύνορο των δύο κρατών.", "64f67e31"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0128-01-01:0":{"b": ["Ο Αντίοχος Ζ' Σιδήτης πέθανε σε εκστρατεία εναντίον των Πάρθων· οι Σελευκίδες δεν μπόρεσαν να ανακτήσουν τη Μεσοποταμία", "e5897112"], "d": ["Ο Αντίοχος Ζ' Σιδήτης το 130-129 ανέκτησε από τους Πάρθους τη Μεσοποταμία και τη Μηδία, αλλά στο χειμερινό στρατόπεδο, με εξέγερση και παρθική επίθεση, έχασε τον στρατό και τη ζωή του. Αυτή η αποτυχία έβαλε τέλος στην ανατολική αξίωση των Σελευκιδών.", "0ceb2108"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0137-01-01:0":{"b": ["Οι Πάρθοι αιχμαλώτισαν τον Δημήτριο Β' Νικάτορα· οι Σελευκίδες έχασαν οριστικά τη Βαβυλώνα και τη Μεσοποταμία", "94a764ce"], "d": ["Ο παρθικός στρατός του Μιθριδάτη Α' συνέλαβε τον βασιλιά των Σελευκιδών Δημήτριο Β' και τον κράτησε στο παρθικό ανάκτορο. Ο Μιθριδάτης πρόσθεσε τη Μεσοποταμία στην Παρθική Αυτοκρατορία· το σελευκιδικό κράτος στριμώχτηκε στην ακτή και αποσύρθηκε στη Συρία.", "d53eb877"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0166-01-01:0":{"b": ["Εξέγερση των Μακκαβαίων: στην Ιουδαία ξεκίνησε εξέγερση εναντίον των θρησκευτικών απαγορεύσεων του Αντιόχου Δ'", "41c25b76"], "d": ["Όταν ο Αντίοχος Δ' Επιφανής αφιέρωσε τον Ναό της Ιερουσαλήμ στον Δία Ολύμπιο και απαγόρευσε τις ιουδαϊκές θρησκευτικές πρακτικές, ο Ματταθίας και οι γιοι του εξεγέρθηκαν στο Μωδεΐν. Ο Ιούδας Μακκαβαίος το 164 ανακατέλαβε και καθάρισε τον Ναό (Χανουκά)· γεννήθηκε το κράτος των Ασμοναίων.", "ad039b3f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0170-01-01:0":{"b": ["Ο Μιθριδάτης Α' ανέβηκε στον παρθικό θρόνο· ξεκίνησε η περίοδος επέκτασης της παρθικής αυτοκρατορίας", "cc77639b"], "d": ["Ο Μιθριδάτης Α' μετέτρεψε τους Πάρθους σε αυτοκρατορία: κατέλαβε τη Μηδία (147), τη Βαβυλώνα και τη Σελεύκεια (141), εγκαθίδρυσε κυριαρχία στην Ελυμαΐδα και στην Περσίδα. Η Κτησιφώντα θα γίνει αργότερα η χειμερινή πρωτεύουσα.", "248f554a"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0187-01-01:0":{"b": ["Συνθήκη της Απάμειας: οι Σελευκίδες αποσύρθηκαν από τα δυτικά του Ταύρου, πλήρωσαν αποζημίωση", "f5197a70"], "d": ["Η συνθήκη ανάμεσα στη Ρώμη και τον Αντίοχο Γ' έδωσε την Ανατολία δυτικά του Ταύρου στους συμμάχους της Ρώμης (Πέργαμος, Ρόδος)· περιορίστηκαν ο σελευκιδικός στόλος και ο αριθμός των ελεφάντων, πληρώθηκε αποζημίωση 15.000 ταλάντων. Οι Σελευκίδες έγιναν πλέον κράτος Συρίας-Μεσοποταμίας.", "08e214af"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0204-01-01:0":{"b": ["Ανατολική εκστρατεία του Αντιόχου Γ' (209-204): οι βασιλείς των Πάρθων και της Βακτριανής υποτάχθηκαν σε σελευκιδικό φόρο", "5c81f302"], "d": ["Ο Αντίοχος Γ', για να ανακτήσει τα χαμένα ανατολικά εδάφη των Σελευκιδών, βάδισε στη Μηδία, στην Παρθία και στη Βακτριανή: ο Αρσάκης Β' και ο Ευθύδημος υποτάχθηκαν σε φόρο. Μετά από αυτή την εκστρατεία ο Αντίοχος πήρε τον τίτλο «Μέγας».", "473faaed"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0249-01-01:0":{"b": ["Ο Αρσάκης Α' και ο Τιριδάτης κατέλαβαν την Παρθαύα και ίδρυσαν το παρθικό (Αρσακιδικό) κράτος", "2cd572ca"], "d": ["Ο Αρσάκης, αρχηγός της νομαδικής φυλής των Parni, ανέτρεψε τον σελευκιδικό σατράπη Ανδραγόρα, κατέλαβε την Παρθαύα και έγινε ο πρώτος βασιλιάς του παρθικού βασιλείου· πρωτεύουσά του είναι η Εκατόμπυλος. Το παρθικό κράτος θα κυριαρχήσει τους επόμενους τρεις αιώνες στη Μεσοποταμία και στο Ιράν.", "1fb67f39"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0249-01-01:1":{"b": ["Ο σατράπης της Βακτριανής Διόδοτος αποσπάστηκε από τους Σελευκίδες· γεννήθηκε το Ελληνοβακτριανό Βασίλειο", "52faafa6"], "d": ["Ο Διόδοτος, σατράπης της Βακτριανής και της Σογδιανής, εκμεταλλευόμενος την αδυναμία του Αντιόχου Β', ανακήρυξε την ανεξαρτησία του. Η Ελληνοβακτριανή ανάγκασε το ανατολικό σύνορο του σελευκιδικού κράτους να αποσυρθεί από την Παρθαύα και τη Βακτριανή.", "ac02ccda"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0273-01-01:0":{"b": ["Α' Συριακός Πόλεμος (274-272): οι σελευκιδικές δυνάμεις ανέκτησαν τη Δαμασκό· έγινε ειρήνη", "0c17ee3d"], "d": ["Όταν ο Αντίοχος Α' νίκησε τους Γαλάτες με την «μάχη των ελεφάντων» (275) και εξασφαλίστηκε, πολέμησε ξανά με τον Πτολεμαίο Β'· ο σελευκιδικός στρατηγός ανέκτησε τη Δαμασκό, ο Μάγας επιτέθηκε στην Αίγυπτο, τελικά έγινε ειρήνη το 272. Ο πόλεμος είναι η αρχή της πτολεμαιοσελευκιδικής διαμάχης για την Κοίλη Συρία.", "20ab588f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0279-01-01:0":{"b": ["Πόλεμος της Καρίας: ο Πτολεμαίος Β' πήρε από τον Αντίοχο Α' την Ιωνία, την Καρία, τη Λυκία, την Παμφυλία και μέρος της Κιλικίας", "afe190ca"], "d": ["Ο Πτολεμαίος Β', με σύντομη και επιτυχημένη εκστρατεία, κατέλαβε τη νότια και δυτική ακτή της Ανατολίας και έφτασε στη Δαμασκό· ο Αντίοχος, βλέποντας ότι η δύναμή του δεν υστερούσε από του πατέρα του, έκανε ανακωχή. Ο Αντίοχος αποδέχθηκε την απώλεια, γιατί έπρεπε να οργανώσει τις κατακτήσεις του πατέρα του στο εσωτερικό της Ανατολίας.", "868966e1"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0280-01-01:0":{"b": ["Ο Σέλευκος Α' σκοτώθηκε από τον Πτολεμαίο Κεραυνό· ο Αντίοχος Α' ανέβηκε στον θρόνο", "4703b674"], "d": ["Ο Σέλευκος, που νίκησε τον Λυσίμαχο στο Κουροπέδιο και κατέλαβε την Ανατολία, μαχαιρώθηκε από τον Πτολεμαίο Κεραυνό καθώς περνούσε στην Ευρώπη. Ο γιος του Αντίοχος Α' παρέλαβε το κράτος αλλά θα δυσκολευτεί στη Δυτική Ανατολία.", "18a3f3a5"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0299-01-01:0":{"b": ["Ο Σέλευκος Α' ίδρυσε την Αντιόχεια", "f4b98967"], "d": ["Ο Σέλευκος, μετά την Ιψό, ίδρυσε στη Συρία, στις όχθες του Ορόντη, την Αντιόχεια στο όνομα του πατέρα του· η πόλη έγινε η δυτική πρωτεύουσα του Σελευκιδικού Βασιλείου και μία από τις μεγαλύτερες πόλεις της Αρχαιότητας. Η Σελεύκεια στον Τίγρη είχε ιδρυθεί νωρίτερα ως ανατολική πρωτεύουσα.", "0ab29d65"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0300-01-01:0":{"b": ["Μάχη της Ιψού: ο Σέλευκος και ο Λυσίμαχος νίκησαν τον Αντίγονο· η Συρία πέρασε στον Σέλευκο", "93bf2aa9"], "d": ["Στην αποφασιστική μάχη των πολέμων των Διαδόχων, ο Σέλευκος και ο Λυσίμαχος νίκησαν τον Αντίγονο (ο Αντίγονος σκοτώθηκε στη μάχη). Ολόκληρη η Ανατολή και η Συρία έπεσαν στο μερίδιο του Σελεύκου· ο Πτολεμαίος όμως, καταλαμβάνοντας την Κοίλη Συρία, δημιούργησε την αιτία των πρώτων Συριακών πολέμων.", "a2ab17a8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0304-01-01:0":{"b": ["Ο Σέλευκος Α' ίδρυσε τη Σελεύκεια στον Τίγρη", "032efabd"], "d": ["Ο Σέλευκος ίδρυσε τη Σελεύκεια στις όχθες του Τίγρη κοντά στη Βαβυλώνα και άρχισε να μεταφέρει εκεί τον πληθυσμό της Βαβυλώνας. Η Σελεύκεια, με πληθυσμό περίπου 300 χιλιάδων, έγινε η μεγαλύτερη ελληνιστική πόλη της Ανατολής και αργότερα γείτονας της πρωτεύουσας της παρθικής αυτοκρατορίας.", "a1aa43e3"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0304-01-01:1":{"b": ["Ο Σέλευκος Α' συνήψε συνθήκη στην Ινδία με τον Chandragupta Maurya· η Αραχωσία, η Γεδρωσία και οι Παροπαμισάδες αφέθηκαν στους Maurya", "3ef3bdee"], "d": ["Ο Σέλευκος βάδισε στην Ινδία για να ανακτήσει τις ινδικές σατραπείες του Αλεξάνδρου αλλά συμφώνησε με τον Chandragupta και αντάλλαξε μέρος των ανατολικών εδαφών με 500 πολεμικούς ελέφαντες. Η συνθήκη μετέφερε το δυτικό σύνορο της Αυτοκρατορίας των Maurya στον Ινδοκαύκασο και εξασφάλισε στον Σέλευκο ελέφαντες για τη Δύση.", "95b2b8bb"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0309-01-01:0":{"b": ["Ο Αλέξανδρος Δ' σκοτώθηκε μαζί με τη μητέρα του Ρωξάνη· η δυναστεία των Αργεαδών έληξε", "3be9d974"], "d": ["Μετά την ειρήνη του 311, με εντολή του Κασσάνδρου (σύμφωνα με τον Διόδωρο ο δήμιος Γλαυκίας) σκοτώθηκαν ο δωδεκάχρονος Αλέξανδρος Δ' και η μητέρα του Ρωξάνη. Δεν έμεινε ονομαστικός ηγεμόνας της Αυτοκρατορίας του Αλεξάνδρου· οι Διάδοχοι στράφηκαν στην ανακήρυξη των δικών τους βασιλείων (π.Χ. 306-305).", "46aa8fb2"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0329-01-01:0":{"b": ["Ο Αλέξανδρος έφτασε στην Περσέπολη· η πόλη και ο θησαυρός πέρασαν στα χέρια των Μακεδόνων", "c1dbaada"], "d": ["Ο Αλέξανδρος, που μετά τα Σούσα πέρασε τις Περσικές Πύλες, έφτασε στην Περσέπολη στα τέλη Ιανουαρίου του 330· η πόλη παραδόθηκε χωρίς αντίσταση. Η αχαιμενιδική κυριότητα της Περσέπολης τελειώνει αυτή τη χρονιά (το ανάκτορο κάηκε τον Μάιο του 330).", "de8726c8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0329-01-01:1":{"b": ["Η πυρπόληση των ανακτόρων της Περσέπολης (Απρίλιος)", "6e6cdfe0"], "d": ["Ο Αλέξανδρος διέταξε τον Απρίλιο του 330 να καούν μερικά ανακτορικά κτίρια στην Περσέπολη· προβάλλονται οι λόγοι ότι ο θησαυρός δεν έπρεπε να πέσει στα χέρια του εχθρού και ότι δεν ήταν ακόμη μοναδικός ηγεμόνας. Αρχαιολογικά φαίνεται ότι κάηκε και το Ανάκτορο του Ξέρξη· ολόκληρη η πόλη εγκαταλείφθηκε.", "c22d037f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0329-07-01:0":{"b": ["Ο Δαρείος Γ' σκοτώθηκε από τους ανθρώπους του σατράπη της Βακτριανής Βήσσου· η αχαιμενιδική δυναστεία έληξε", "bedcca87"], "d": ["Ο Δαρείος Γ', που διέφυγε από τα Εκβάτανα προς την ανατολή, τραυματίστηκε τον Ιούλιο του 330 στην Παρθία από τον Βήσσο και τους οπαδούς του και αφέθηκε και πέθανε· ο Αλέξανδρος έστειλε το πτώμα στην Περσέπολη. Το πραγματικό τέλος της Αχαιμενιδικής Αυτοκρατορίας.", "dc8ceef3"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0330-10-01:0":{"b": ["Μάχη των Γαυγαμήλων: ο Αλέξανδρος νίκησε οριστικά τον στρατό του Δαρείου Γ'", "a5b082d7"], "d": ["Στα Γαυγάμηλα ο στρατός του Δαρείου, που αποτελούνταν από πολλά πολεμικά άρματα και ιππικό, διαλύθηκε στην επίθεση που διαπέρασε την άμυνα του αριστερού πλευρού του Αλεξάνδρου· ο Δαρείος διέφυγε πάλι. Η μάχη καθόρισε το τέλος της Περσικής Αυτοκρατορίας· η Βαβυλώνα και τα Σούσα άνοιξαν τις πύλες τους.", "b31c6746"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0330-10-22:0":{"b": ["Ο Αλέξανδρος μπήκε στη Βαβυλώνα· ο Μαζαίος παρέδωσε την πόλη και η Σατραπεία της Βαβυλώνας πέρασε στον Αλέξανδρο", "c8d2afb3"], "d": ["Μετά τα Γαυγάμηλα ο σατράπης της Βαβυλώνας Μαζαίος άνοιξε τις πύλες στον Αλέξανδρο· ο Αλέξανδρος διέταξε την επισκευή του ναού του Μαρδούκ και χρησιμοποίησε την πόλη επί 34 ημέρες. Η Βαβυλώνα πέρασε από την περσική διοίκηση στη μακεδονική.", "b84160e8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0330-12-15:0":{"b": ["Ο Αλέξανδρος κατέλαβε τα Σούσα· ο περσικός θησαυρός περιήλθε στα χέρια του", "fbf417db"], "d": ["Ο Αλέξανδρος, φεύγοντας από τη Βαβυλώνα, μπήκε στα Σούσα· ο σατράπης Αβουλίτης παρέδωσε την πόλη και τον μεγάλο θησαυρό. Τα Σούσα έγιναν η οικονομική βάση της ανατολικής εκστρατείας της Μακεδονίας.", "b65699b7"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0331-01-01:0":{"b": ["Πολιορκία της Τύρου: ο Αλέξανδρος κατέλαβε και κατέστρεψε την πόλη στο νησί με επιχωμάτωση", "89ede146"], "d": ["Ο Αλέξανδρος κατέλαβε το νησί της Τύρου, βάση του περσικού στόλου, σε επτά μήνες κατασκευάζοντας τεχνητό πέρασμα· η πόλη λεηλατήθηκε, το μεγαλύτερο μέρος του λαού σκοτώθηκε ή υποδουλώθηκε. Η περσική ναυτική ισχύς κατέρρευσε έτσι και άνοιξε ο δρόμος προς την Αίγυπτο.", "22842728"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0332-11-01:0":{"b": ["Μάχη της Ισσού: ο Αλέξανδρος νίκησε τον Δαρείο Γ'· ο Δαρείος άφησε την οικογένειά του και διέφυγε", "3803fc30"], "d": ["Σε μια στενή παράκτια πεδιάδα, ο μεγάλος στρατός του Δαρείου Γ' ηττήθηκε από τον Αλέξανδρο· ο βασιλιάς των Περσών άφησε την οικογένεια και τον θησαυρό του και διέφυγε. Η νίκη της Ισσού εξασφάλισε την παράδοση της Συρίας και της φοινικικής ακτής και στη συνέχεια της Αιγύπτου στον Αλέξανδρο.", "a711a81e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0333-01-01:0":{"b": ["Μάχη του Γρανικού: ο Αλέξανδρος νίκησε τους Πέρσες σατράπες", "1aae30d4"], "d": ["Ο βασιλιάς της Μακεδονίας Αλέξανδρος πέρασε στην Ασία τον Μάιο του 334 και στις αρχές Ιουνίου νίκησε στον Γρανικό τους Πέρσες σατράπες. Οι πύλες της Δυτικής Ανατολίας άνοιξαν· οι Σάρδεις και οι ιωνικές πόλεις παραδόθηκαν στον Αλέξανδρο.", "8cc08bd9"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0335-01-01:0":{"b": ["Ο Δαρείος Γ' ανέβηκε στον περσικό θρόνο (δολοφονία του Άρση)", "706f8a9f"], "d": ["Ο αυλικός Βαγώας σκότωσε τον Αρταξέρξη Δ'· ο σατράπης της Αρμενίας Artašata έγινε βασιλιάς με το όνομα Δαρείος Γ' (Codomannus). Τον Οκτώβριο του 336 στη Μακεδονία σκοτώθηκε ο Φίλιππος και ο Αλέξανδρος ανέβηκε στον θρόνο.", "c082bdae"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0337-01-01:0":{"b": ["Ο Αρταξέρξης Γ' πέθανε· ο Αρταξέρξης Δ' (Άρσης) ανέβηκε στον θρόνο", "d38e2edc"], "d": ["Ο Αρταξέρξης Γ' πέθανε το καλοκαίρι του 338 από φυσικά αίτια (παρά την ιστορία δηλητηρίασης του Διόδωρου)· ο Άρσης ανέβηκε στον θρόνο. Οι εξεγέρσεις της Αιγύπτου και της Βαβυλώνας και οι προετοιμασίες του βασιλιά της Μακεδονίας Φιλίππου για την Ανατολία συμπίπτουν χρονικά.", "09f24497"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0344-01-01:0":{"b": ["Ο Αρταξέρξης Γ' κατέλαβε και κατέστρεψε τη Σιδώνα· η εξέγερση του Τέννη καταπνίγηκε", "d1b533cc"], "d": ["Κατά την αντιπερσική εξέγερση του βασιλιά της Σιδώνας Τέννη, με αιγυπτιακή υποστήριξη, ο Αρταξέρξης Γ' κατέλαβε την πόλη· ο Τέννης πρόδωσε τους Πέρσες, η πόλη έκαψε τον εαυτό της και πολλοί άνθρωποι σκοτώθηκαν. Οι φοινικικές πόλεις περιήλθαν ξανά σε περσικό έλεγχο και άνοιξε ο δρόμος για την κατάκτηση της Αιγύπτου.", "050b8e4e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0386-01-01:0":{"b": ["Ειρήνη του Βασιλέως (Ανταλκίδας): οι ελληνικές πόλεις της Ανατολίας και η Κύπρος αφέθηκαν στους Πέρσες", "17e871ad"], "d": ["Με την ειρήνη που υπαγόρευσε ο βασιλιάς των Περσών Αρταξέρξης Β', οι ελληνικές πόλεις στην Ασία και η Κύπρος θεωρήθηκαν περσικές και στις ελληνικές πόλεις αναγνωρίστηκε αυτονομία. Η Σπάρτη, ως εκπρόσωπος των Περσών, εφάρμοσε την ειρήνη.", "7bf00868"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0400-01-01:0":{"b": ["Μάχη των Κουνάξων: ο Κύρος ο Νεότερος ηττήθηκε από τον μεγαλύτερο αδελφό του Αρταξέρξη Β' και σκοτώθηκε", "90346087"], "d": ["Ο Κύρος ο Νεότερος, βαδίζοντας στη Βαβυλώνα με τους Μυρίους, Έλληνες μισθοφόρους, ηττήθηκε στα Κούναξα από τον μεγαλύτερο αδελφό του Αρταξέρξη Β' και σκοτώθηκε στη μάχη. Η πορεία επιστροφής των Μυρίων στη Μαύρη Θάλασσα αφηγείται στην Κύρου Ανάβαση του Ξενοφώντα.", "664d8d4f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0479-01-01:0":{"b": ["Ο Ξέρξης πέρασε τον Ελλήσποντο· Θερμοπύλες και κατάληψη της Αθήνας", "9bf22df1"], "d": ["Ο Ξέρξης, με τον μεγάλο στρατό του, νίκησε στις Θερμοπύλες τη σπαρτιατική-συμμαχική δύναμη του Λεωνίδα και μπήκε στην Αττική· η Αθήνα εκκενώθηκε και κάηκε μαζί με την Ακρόπολη. Ο περσικός στρατός προχώρησε μέχρι τη μέση της Ελλάδας.", "3b81a962"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0479-01-01:1":{"b": ["Ναυμαχία της Σαλαμίνας: ο ελληνικός στόλος κατατρόπωσε τον περσικό στόλο", "010e3aab"], "d": ["Ο ελληνικός στόλος υπό τον Θεμιστοκλή νίκησε τον περσικό στόλο στη Σαλαμίνα, στο στενό, και κατέλαβε τη ναυτική υπεροχή. Ο Ξέρξης επέστρεψε στην Ασία με το μεγαλύτερο μέρος του χερσαίου στρατού, ο Μαρδόνιος έμεινε στην Ελλάδα.", "f55ed3ca"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0483-01-01:0":{"b": ["Οι εξεγέρσεις των Bêl-šimânni και Šamaš-eriba στη Βαβυλώνα καταπνίγηκαν από τον Ξέρξη Α'", "ebcef5a9"], "d": ["Στην αρχή της βασιλείας του Ξέρξη Α' ξέσπασαν δύο εξεγέρσεις στη Βαβυλώνα (Bêl-šimânni, Šamaš-eriba). Ο Ξέρξης κατέστειλε τις εξεγέρσεις· διαίρεσε τη σατραπεία της Βαβυλώνας και μείωσε τα προνόμια της πόλης.", "015c253c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0493-01-01:0":{"b": ["Ναυμαχία της Λάδης: ο περσικός στόλος νίκησε τον ιωνικό στόλο· η Μίλητος έπεσε", "86396cf1"], "d": ["Ο στόλος των Περσών, με φοινικική πλειοψηφία, κατατρόπωσε στη Λάδη τον ιωνικό στόλο· η Μίλητος πολιορκήθηκε και καταστράφηκε, ο λαός της εξορίστηκε στη Μεσοποταμία. Η Ιωνική Εξέγερση έληξε και η Ιωνία περιήλθε ξανά σε περσικό έλεγχο.", "b72ba00d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0497-01-01:0":{"b": ["Οι Ίωνες έκαψαν τις Σάρδεις", "adf677bd"], "d": ["Οι Ίωνες και οι Αθηναίοι-Ερετριείς βάδισαν στις Σάρδεις, κέντρο της περσικής σατραπείας, και έκαψαν την πόλη. Ο Δαρείος μετά από αυτό αποφάσισε να τιμωρήσει την Αθήνα· το γεγονός είναι ο λόγος της εκστρατείας του Μαραθώνα.", "32e33dce"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0498-01-01:0":{"b": ["Ξεκίνησε η Ιωνική Εξέγερση: όταν απέτυχε η εκστρατεία του Αρισταγόρα στη Νάξο, οι ελληνικές πόλεις της Ιωνίας ξεσηκώθηκαν εναντίον των Περσών", "aab8ff2f"], "d": ["Όταν κατέρρευσε η εκστρατεία του τυράννου της Μιλήτου Αρισταγόρα στη Νάξο, οι πόλεις της Ιωνίας ανέτρεψαν τους τυράννους τους και ζήτησαν βοήθεια από την Αθήνα και την Ερέτρια. Αυτή η εξέγερση είναι το φυτίλι των περσοελληνικών πολέμων.", "7d70c2ee"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0512-01-01:0":{"b": ["Ο Δαρείος πέρασε τον Ίστρο (Δούναβη) και εκστράτευσε στους Σκύθες· η Θράκη προσαρτήθηκε στην περσική σατραπεία", "a5891101"], "d": ["Ο Δαρείος πέρασε στη Θράκη με γέφυρα πάνω από τον Βόσπορο, υπέταξε τους Γέτες, πέρασε τον Δούναβη και εκστράτευσε εναντίον των Σκυθών. Αν και δεν μπόρεσε να νικήσει τους Σκύθες, ο Μεγάβαζος πρόσθεσε στην περσική κυριαρχία τη Θράκη και την ακτή της Μακεδονίας.", "f464fbf8"]}
});
